/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150629-8","meetingId":"h27-cm06","date":"2015年6月29日","dateIso":"2015-06-29","committee":"建設委員会","time":"午前１０時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件抜き出しています。","topics":[{"id":"topic-01","title":"の１、議案審査","agenda":"の１、議案審査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回のそうしたバリアフリー計画を策定していく上での策定メンバーというのを教えてください。「荏原地域の交通結節点として」という言葉もありますけれども、今回のバリアフリー計画の策定、この計画と上位計画のまちづくりのマスタープラン、旗の台が地域生活拠点と位置づけられているわけですけれども、この関係、整合性というのはあるのか、そこをお伺いします。","respondent":"鈴木防災課長、中村都市計画課長","answer":"耐震化だけでなく、感震ブレーカーや初期消火、そのようなものを科目の一つの中に情報として入れまして、しっかりと日ごろから自助・共助で備えていただくというような形で啓発をする予定です。３０年度から事業の実施という予定です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"防災学校のほうですけれども、耐震化も啓発の中の一つということで考えているというような理解は、言えないことはないというような私の今の理解ですけれども、ぜひもっと積極的に、やはり今回、何といっても住宅が倒れてしまったら人命が失われますし、救助もできなくなりますし、初期消火もできなくなりますし、避難所も自宅で待機できない者でいっぱいになってしまうわけですから。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"特にこの３０号線、これは計画道路としての整備はありますけれども、これとバリアフリーとは並行して進めるべきものでありまして、バリアフリーはバリアフリーで適切な範囲に定めて。そういったものをまた地域の中で共有していく、その中に、次のステップとして、それを実際どのように実現していくのか、どう取り組んでいくのか、そういったその地域の機運が盛り上がってきておりますので。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"訂正いたします。３００万円新規ということですけれども、昨年現状調査をしたら空き室が目立ったということで、昭和６１年ですか、この時期にあった再開発ですけれども、やはり陰りが見えてきているというふうな印象を持ったのですけれども、何で空き室が目立ってきているのか、その原因についてどういったように考えているのか、お伺いします。それとあわせて、今回たくさんあるので、聞かせていただきます。","respondent":"溝口都市開発課長、寺嶋木密整備推進課長、中村都市計画課長、矢木住宅担当課長","answer":"そういった中で、いかに活力ある地域、または、他の地域に負けないような形でのにぎわいをつくっていくか。軒数とは、何棟とか、そういった形の数字を持ち合わせておりませんで、面的な話になりますが、先ほど言った定義に該当する面で捉えておりますので。バリアフリーと３０号線ということで、このバリアフリーの対象の地域はこれから検討してまいりますので、また、全ての道路に言えることですけれども。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"すみません、あわせて、荏原町駅前地区の追加の意味というのを聞いたのですけれども、それをお伺いしたいのと、それと、困難区域測量委託のほうですが、そういった定義があるということは聞きました。借り上げて、共同住宅にして、そこに地権者の方を入れるとか、そういったところに使用される可能性というのは０％と言えるのかどうかというのをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"あわせて、すみません、最後、こちら、大崎駅西口交通広場の件に行ってしまいますけれども、当初予算に対しての追加ということだと思うのですけれども、今回は屋根を追加ということだったのですが、初めは予定がないのに、何で後で屋根がつくのかというのが、そこら辺、後から屋根を追加する理由というのですか、最初から載せてもよかったのではないかと思うのですけれども、そこら辺はどうなのでしょうか。","respondent":"寺嶋木密整備推進課長、溝口都市開発課長、中村都市計画課長","answer":"理解の進みについて、区のほうでどのような認識かというところですけれども、こちらは先ほどもご答弁申し上げましたとおり。当初予算では、バスターミナル運営に必要な最低限の施設ということで、今回、４つのバスが停まるバスバースというものを設けます。空き家の有効活用は有効活用で、区としてどんな活用方法が最適なのか、そういったことを検討することが第一だというふうに考えてあります。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"既に予算は３月で審議をしているわけですが、２カ月ぐらいで補正になっているというのは、何か当初予算に入れられないものがあったのか、そこら辺の事情をお聞きしたいということと、それから、大崎駅西口交通広場、これ、なぜ、この追加分が必要なのか。それと、空き家のところですが、改修工事というのは、これは、空き家活用モデル検討に対する改修工事というふうな理解でいいのでしょうか。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"１点だけ、大崎駅の西口広場なのですが、これは公共施設ということで、区民の皆様方の利便性という意味では、本当に品川区がカバーするということは必要なのでしょうが、やはり民間バス会社があるわけですから、その方たちはどういう考え方を持っているのか。それから、空き家の活用、思った以上にお申し出があったという、非常にありがたいと思っています。これは要望です。１件だけお願いします。","respondent":"溝口都市開発課長","answer":"バスターミナルに関するご質問にお答えします。ちょっと説明が足りなくて申しわけありませんでした。今回つくりますバスターミナルというか、大崎駅の西口交通広場につきましては、都市計画施設ということでご説明させていただきました。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"全体的な事業の内容はわかりました。その中で１点だけ確認をさせていただきたいのですが、天王洲地区のまちづくりに関してなのですが、これ、地域的にいうと、どの程度の範囲まで考えていらっしゃるのかというのを１つお伺いします。","respondent":"溝口都市開発課長","answer":"ですから、公園も含めて、全体の東品川２丁目のまちづくりを今後どうしていくのかというところで考えている。ですから、検討の範囲としては全体を考えているところです。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ごめんなさい、２丁目地区というのは、イメージがわからなかったのだけれども、何を聞きたいかというと、船舶中継所、あの辺のことというのは今回のところで頭に入っているのか、入っていないのかということで。","respondent":"溝口都市開発課長","answer":"ただ、もともと清掃事業という形で使われていた土地を区のほうに無償でいただく、そういう条件で一応、清掃事業として活用というのが前提でありますので、今すぐにという話ではありませんが、将来的にはその形というのも視野に入れながらではありますが。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"部署が違ってしまうところがあるから、あまり余計なことも言えないけれども、あそこの、限定してまず使えない、清掃事業にかかわっていることでないとだめという前提があるから、やはりこれは議会のほうでもこの活用を早くしたいということも要望しているし、これは、防災まちづくり部の方からも企画のほうにプッシュしていただいて、ぜひ早く進めていただきたい。これはいかがでしょうか。","respondent":"溝口都市開発課長","answer":"そういった好立地といいますか、さらなる有効活用が可能な土地だとは考えておりますので、そういったところも視野に入れながら、将来的にはいずれ何かしらのまちづくりを進めていきたいという思いはありますので、そういったことに備えて。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この前、あの辺に行ったら、運河を渡ったところに、昔、船着き場があったところ、あそこが今、マンションが建っている状況だったので、それだけまた人の流れも変わってきてしまう。天王洲に勤める方ではなくて、居住者もまた出てくるということを考えると、その辺も含めて検討していってください。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"すみません、細かいところなのですけれども、まず、防災学校なのですが、先ほど、アドバイザー研修については啓発ということなのですが、区民対象とかのコース、細かいところで、それぞれのコース、先ほど思ったのだけれども、時間があいてしまったから、飛んでしまったのですが、それぞれの学習カリキュラム、コースはどのぐらいの時間のスパンというのでしょうか。","respondent":"鈴木防災課長","answer":"それぞれの自助についての意識啓発ということで、修了証ですが、委員のご質問の中にもありましたように、既存のアドバイザー研修、それから、ステップアップ研修も取り込みまして、全体として学校のカリキュラムを組む予定ですので、修了証についても。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"品川区は区内全域が指定箇所以外は違法喫煙で、いろいろ重複しているステッカーも既存ものがありますけれども、これはまさにスポット的に雨水ますのところに貼付するというもので、より一層の効果があるとは思うのですが、当然、そうした、今までの既存のものと連携させながら、より一層そういったことをさせないという防止策を強化するということですけれども、まずその辺の。","respondent":"稲田道路課長","answer":"スポット的に、我々、道路で管理する雨ますというところではありますが、地域活動課等でやっている活動があります。こういう中でも連携をとりながら、設置する場合は、連携してやっていきたいというふうに考えております。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"最後、すみません、空き家のところで、産・学・官のほうで空き家活用モデル検討経費ということで、プレス発表の資料では、これは２３区としては初というふうに言っていますが、いろいろ私もアイデアというところでいろいろなものを追っかける中で、全国ではいろいろ既に学生とかからご意見をいただいて、いろいろな形で、本当に過疎地域だったり。","respondent":"矢木住宅担当課長","answer":"ただ、現時点で、アンケートを実施したときからは半年程度時間が経過しておりますので、また改めてアンケート等々で意思確認をさせていただきたいと考えています。","id":"exchange-014"},{"speaker":"つる委員","kind":"確認","question":"なので、ぜひ今回の取り組みを成功させて、広がっていってほしいというところは思っていますが、その上で、今、これからというのがありましたけれども、居住用途というのは、あくまでも公共のものとしての居住用ということですか、個人のあれではないですか、住宅ということではなくて、大前提がそもそもそうではないと。括弧書きで「居住用途」とあるので、そこだけ確認をさせてください。","respondent":"矢木住宅担当課長","answer":"」という話になれば、そこで改修という形になってまいりますので、広い意味での居住用途ですので、特に公共利用というふうには、今のところは限定しておりません。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"そうすると、１、２、３とそれぞれ別立てであるのですが、例えば、ここでそういったアイデアがつくられて、それを実際に実施するときの経費の助成とかというのは、今の段階では、特に区としては考えていないし、これからどうなのかというのは、全然まだ検討の余地もないということなのか、例えば、１だと、これは公共的施設として活用する場合には助成金が示されておりますけれども。","respondent":"矢木住宅担当課長","answer":"委員ご指摘のとおり、また今後の検討の経過次第ではありますが、今のところ、そういうところまでは考えてございません。","id":"exchange-016"},{"speaker":"安藤委員","kind":"意見","question":"それと、バリアフリーのところは、もちろん私どもの党も重要、旗の台駅のホーム柵をつくってほしいですとか、切実な声をたくさんいただいて、大事なところだと思うのですけれども、まず、本心として、やはり旗の台駅検討経費なのですけれども、バリアフリーの名で、３０号線の道路ですとか再開発につなげようという懸念が払拭できませんでした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-02","title":"の第６１号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"の第６１号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３点伺いたいのですが、今回のエレベーター、昇降機部分についての、容積率に算入しないという改正なのですが、この目的は何だったのでしょうかということが１点と、それと、２点目の改正部分として、備蓄倉庫等の点もあるのですけれども、これを一定割合、容積率に算入しないというところに加えるとありますが、それで、こういったマンションを建てる施工者、施工主、必ずこの変更で。","respondent":"鈴木建築課長","answer":"居住者の高齢化に対応して、今まではエレベーターがなかったのですけれども、高齢者対応で、どうしても後からエレベーターをつけたいというような場合は、やはり容積がネックになりまして、エレベーターがつけられなかった等々ございまして、こういった指摘あるいは声を受けて。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"例えば、３ｍ掛ける３ｍぐらいの、大体１０m2ぐらいの面積のエレベーターがあるとしたら、それが１０階建てだと、それぞれの階で重複してという話だったので、１００m2の部分が新たに１つ部屋をつくれるということになりますので、やはり大規模なマンションであればあるほど、こうした今回の改定というのは、開発者の利益につながってくるというふうに思うのですけれども。","respondent":"溝口都市開発課長、鈴木建築課長","answer":"両地区でいきますと、まず１点大きいところは、開発事業者の利益というよりも、どちらかというと、今回の工事費の高騰等によりまして、本来であれば、権利者の権利分を少し削って事業に充てる。今のお話に追加しまして、先ほどご説明させていただいたとおり、やはり高齢化社会を迎えまして、既存の共同住宅にエレベーターをどうしてもつけたいというご相談が非常に多いです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"それで、質問なのですけれども、今回、高層化、さらに誘導化していくというふうな、あるいは、そういうふうな方向になっていくと思うのですけれども、そこに関する区の認識だけ伺います。今回の改正が、さらなる超高層化、まちづくりにつながっていくというふうに私は思っていますが、そこに関する区の認識はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"今回の条例改正、規制緩和がさらなる区内の開発の推進、超高層化の推進につながるというふうに私は思うのですけれども、区の認識をお伺いします。","respondent":"藤田都市環境部長","answer":"今回の改正、大きな建物について当てはまるものもあれば、小さな建物についても、エレベーターを設置したい、あるいは既にエレベーターがある老朽化したマンション等についても考え方が、建替えを進めていこうと思うようなケースについては。","id":"exchange-021"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、条例施行予定日は、具体的にはいつ、何年何月になりますか。","respondent":"鈴木建築課長","answer":"施行期日ですが、これから、本会議、日程でご審議いただいて、採決いただいて、本条例が公布していくのに合わせて、この本条例も公布です。","id":"exchange-022"},{"speaker":"筒井委員","kind":"確認","question":"確認になってしまうのですが、もちろんこの条例は建て直しのときでももちろん適用されるのかということと、また、先ほど安藤委員からご質問があったように、当然、高層化になった場合、周りの住民への配慮とか景観への配慮ということも忘れずにやっていただけるのかということをお聞きしたいと思います。","respondent":"こんの委員長","answer":"筒井委員に申し上げます。先ほども安藤委員に申し上げましたが、いわゆる条例は、建替え、高層、そういうことではないのです。ですので、条例上、中身、そういうことではありませんので。","id":"exchange-023"},{"speaker":"筒井委員","kind":"意見","question":"そうですね。万が一そういった弊害が起きたら、配慮、当然だと思うのですけれども、やっていただけるかどうかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"つる委員","kind":"確認","question":"ご答弁をする中で、事前にさまざま確認させていただきましたが、エレベーターの部分、それから、防災等々と、特にこれまでさまざま、３.１１以降、そうした形で大きいマンションの方からも防災に資する場所を提供したいと、そういう話をいただく中で、これからのところについてもそうした意識をしっかりと捉えて、地域に戻していただくということも含めて、答弁の中でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"反対です。今回の条例改正のもとになっている建築基準法改正自体が多岐にわたっているのですけれども、全体が、破綻が明らかなアベノミクスに基づく行財政対策の一環として進められた改正でした。品川区というのは本当に超高層ビルも再開発も進めている区ですので、かなり進められている地域ですので、区民はさらなる高層化を望んでいません。むしろ規制を強めるべきだと思います。今回の改正には反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"賛成ですが、意見を１つだけ言わせていただきますが、エレベーターの設置というのは非常に利便性がよくなって、区民の皆様方にはいいと思うのですが、逆に今後考えていただきたいのは、震災があったときのエレベーターの中での閉じ込めとか、ここはまた違うということなので、これを参考にということで、こちらのほうも気をつけていただいて、配慮していただきたいという意見を述べさせていただき。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"の２、請願・陳情審査","agenda":"の２、請願・陳情審査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"お伺いしたいのは、ここで「公営住宅入居の要求は、ますます強くなっています。」とありますけれども、繰り返しますが、私もそう思うのですけれども、区としては、要求がますます強くなっているという認識はあるのでしょうか、お伺いします。","respondent":"矢木住宅担当課長","answer":"要求が強くなっているという認識があるかどうかというご質問ですが、要求が一定程度あるということは認識しております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"それと、今、西中延の区営住宅は、建替えということですけれども、現存戸数を維持するということがありました。しかし、私は、こうした建替えのときには、ほかの施設と複合したとしても、やはり今の建築技術の発展もありますし、これを機会に増設していくというのが区民の願いだと思いますし、そうしていくべきだと思うのですけれども、なぜ建替え時に合わせて今回増やさなかったのでしょうか、お伺いします。","respondent":"矢木住宅担当課長","answer":"こちら、高度利用ということができるということに関しまして、区営住宅も建替えを行っているところです。皆様のご希望は、区営住宅のみならず、さまざまな建設のご要望がありますので、その時々の社会状況の動向に従いまして、建設計画を立てているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"ですから、これから区の施策なども拝見しますと、老朽化をかなり迎えている区営住宅がたくさんあるのですけれども、これから維持管理、場合によっては補強だけではなくて、建替えということがあるかもしれない。そうした場合に、やはり品川区が公営住宅の区民ニーズが高まっていると判断した場合は、増設するということがあるのでしょうか。それをお伺いします。","respondent":"矢木住宅担当課長","answer":"委員ご指摘のとおり、老朽化、維持管理の費用というのは、今後ますます増大するところです。そこの、今あるものを長く使っていく、そういうところに予算を一定程度入れていくということでございまして、今後、区営住宅の増設は考えておりません。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"といいますのは、まず一つ書かれておりますのが、品川区の最低居住面積水準未満の世帯は、２３区平均より大きいと。ですから、こうした区の実態分析からしても、高齢者が低廉で良質な公営住宅を必要としているという実態を私は指摘していると思うのです。こうしたことに照らして、公営住宅を増やす必要性というのを、区は認識していないのでしょうか、お伺いします。","respondent":"矢木住宅担当課長","answer":"こちらの民間住宅ストックの有効活用を図っていく、すなわち、空き家を有効活用するために、貸し主のお貸し出しできないところをどうしたら貸せるようになるかというようなことを施策として考えていくとともに、住宅の確保が困難な方々への住宅供給の仕組みづくりを考えていく。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"品川区は、こうした、国が定めている公営住宅の供給についての義務といいますか、指導というか、推進をどのように考えているのか。それを緩和する必要があると認めるときは公営住宅の供給を行わなければならないと書いているわけですけれども、低額所得者、住宅に困っている方々の住宅不足というのはあると考えているのでしょうか、ないと考えているのか、そこら辺をお伺いします。","respondent":"藤田都市環境部長","answer":"私ども住宅施策を進める中で、公営住宅、こちらのものにつきましては、しっかりとこれまでも供給をしてきたという考え方です。そうした中で、高い倍率の申し込みもあるということから、先ほど担当課長も申し上げたとおり、一定程度の要望はあるというふうに理解をしています。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"一定程度のストックがあると言いますけれども、私はまだまだ足りないというふうに思っております。ですから、家賃が払えない、高い家賃の住宅には入れないと。しかし、それを実現するためには、こうした制度というのも具体的に検討していく必要があると思うのですけれども、そうした考えは、品川区はどうでしょうか。","respondent":"矢木住宅担当課長、藤田都市環境部長","answer":"ただいまの家賃助成等の施策を考えていくかどうかというご質問ですが、こちらにつきましては、住宅を確保するために配慮が必要な方々へどのような形で供給していったらいいのか、そういう会議体というのをまず研究してまいりまして。その辺が先ほどの有効活用の中の産・学・官協働の中で、学生のアイデアをいただく中で、何らかの形で開始をする中で、民間住宅としての貸し出し。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"というのも、建築年度が昭和４０年代のものもありますし、それこそ先ほどの品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例による容積率の緩和によって、ある程度高層階のものに建て直して、戸数を増やしていくというようなお考えがあるのかどうか、そういった将来検討する余地があるのかということをお聞きしたいと思います。","respondent":"矢木住宅担当課長","answer":"現時点においては、現在、西中延区営住宅を建替え中。その後、中延一丁目区営住宅を建替え予定です。その他の住宅につきましては、全て耐震改修が終了してございまして、今のところ、建替え等の予定は持ってございません。","id":"exchange-034"},{"speaker":"西本委員","kind":"確認","question":"区の考え方を確認したいのですが、先ほど、都のほうから申し出があったら考えるというお話だったのですけれども、東京都は都営住宅をどういうふうに今後やっていこうとしているのか。これは、耐震が終わっているということなので建替えはないにしろ、浴槽がないというところに関しては、これは皆さま、どうされているのですか、皆さま、工夫されているのか。","respondent":"矢木住宅担当課長、藤田都市環境部長","answer":"これは都営住宅のルールと同じです。エレベーター設置につきましても、私どもは鋭意検討して、つけられるところには極力つけてきた経緯があります。それより前に、先ほどのエレベーターの話がありましたけれども、エレベーター、面積算入しないからつくろうと思えばつくれるのではないかという部分もありますけれども、建替え時のコストとあわせて。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区内の都営については、区と協議する形、譲り受けるということって、この一覧にありますけれども、３８戸ですけれども、これは維持されるという形で、話は全くない、今現時点でそういう話はないという認識でよろしいですか。今の話だと、３８戸は維持するということで、区のほうに移管したいとかというのは、申し入れとかそういうのは受けていないという理解でよろしいでしょうか。","respondent":"矢木住宅担当課長","answer":"すみません、訂正します。現時点におきまして、都営住宅移管の打診は継続しています。ただし、先ほど部長より答弁がございましたとおり、既に高度利用を考えて、移管できるものは移管しています。そういった状況の中で、なかなか受けられないというか、打診はされているです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"ありがとうございました。使用料が安いという、これは年収等々によって、収入がかかわってくるのでしょうけれども、それで、広いです、３ＤＫで、そのぐらいの広さで、品川区の中でということだと、やはり結構使用料が安いですから、人気があると思っているので、それらも含めて、空き家もありますから、それも含めての総合的な考え方で進めていただきたいというふうに要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"区営住宅のことで、確認させていただきたいのですけれども、先ほど住宅担当課長からご説明のとおり、西中延が今建替え工事中ということなのですが、あと、中延一丁目、建替え予定と先ほどおっしゃっていましたけれども、あくまでこれは予定、もしくは何年度に建替えをするのか、その辺のところをお聞きしたいと思います。よろしくお願いします。","respondent":"矢木住宅担当課長","answer":"中延一丁目につきましては、こちらの西中延区営住宅に入られていた方が、今、区民住宅、あと、都営住宅等々に移転しておりまして、こちらの方がお戻りになったところに、中延一丁目の方を今度移動させるですので、一定、平成２８年、平成２９年。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"意見","question":"私どもの会派は、結論を出すでお願いいたします。考え方については、今までも区営住宅についていろいろなお話が出ております。その中で、現在の中での区の考え方を支持してまいりますので、この請願に対しましては、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"先ほど、部長のほうからもご答弁があった民間住宅の空き家の活用、これは先ほどの議案でもありましたけれども、例えば、モデル事業である産・学・官の事業を何としても本当に２３区初というふうに冠を打っているわけですから、しっかりとしたもの、まさにモデルとなるような位置づけとなるような活用をしっかりとつくっていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"結論を出すで、採択を主張いたします。私がふだん伺っている声ですとか、あるいは、このマスタープランの中にある今の高齢者の皆さまを中心にした住宅要配慮者の方々の実態、そういった実態に照らして、この請願にあるように、品川に住み続けたいという願いを実現するためには、やはり区営住宅の増設が必要だと思います。そのために税金はあると私は思っておりますので、私は採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"木村副委員長","kind":"質問・要望","question":"結論を出すということにします。それに対して、今使えないというものもお聞きしましたけれども、そういうものに対して、あるものをいかにしてうまく利用していくかということを主張していきたいと思います。いろいろと長く使ってもらうことが可能であれば、そういうことにもしっかりやっていただきたいと思います。それらを考えまして、今回は不採択と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"筒井委員","kind":"意見","question":"この場で結論を出したいと思います。請願に反対なのですけれども、その理由は、空き民間住宅の活用、そして、今の区営住宅が部屋の大きさのわりには格安であるということ、そして、区の維持管理コストも将来かかってくるということ、および新たな建設より家賃助成等、代替案の検討の余地もあるということから、総合的に考慮しまして、先ほど述べましたとおり、請願には反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。空き家対策のほう、今、やっている最中ですので、それを含めて、それと、高齢化も進んでいく中で、どういう視点で住宅の課題について取り組んでいくかということは、総合的に判断をしていく必要があるというふうに思っておりますので、この請願については不採択としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-04","title":"平成２７年請願第１２号 区内特定整備路線の事業計画の中止及び住宅の耐震化と感震ブレーカーの早期普及を求める請願","agenda":"平成２７年請願第１２号 区内特定整備路線の事業計画の中止及び住宅の耐震化と感震ブレーカーの早期普及を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それで、まず、すみません、請願項目６に関連して伺いたいのですが、行政と住民が道路の必要性を含めて意見交換できる説明会ということを求めているわけですが、私は、こういった個人の財産にかかわる問題でもありますので、こうした道路計画というのは、必要性を含めて、住民意見を聞き、判断することが絶対必要だと思います。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"今後の検討の中で決定されていくです。それから、優先整備路線に指定される道路はいずれかです。これもまさに今後検討していく、今検討をこれから始めていくですので、未定です。基本的に、これまでの考え方としては、今後１０年間で着手または完成させるということで、既に着手しているものは基本的には載せないというような、これまでは基本的にそういう考え方でやってきましたので。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"最初に今のところを質問しますけれども、具体的に優先整備路線にどの道路を入れますかという、第４次事業計画に当たっても、意見照会が今、都から区に来ているのかというのを聞いたので、それも答弁漏れがあったので、お伺いします。これ、大臣の考えと違うことをやっているのではないかと思うのです。ここは違うのではないですかと言いたいのですけれども、それに対する意見をお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"今、東京都のほうでも、この事業を進めるに当たりまして、説明会は終了いたしましたけれども、ただ、個別に今度説明に入って、個別具体の、皆様がお持ちの悩みにつきまして聞いて、一つ一つ解決を図っていくという面では、非常に丁寧な対応がなされている、また。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"きちんとここにあるように、改めて事業自体の正当性に対して疑問を感じている方がたくさんいらっしゃるわけですから、説明会を開くべきだと私は思います。これに関してはどうかということが２点目。くどいのですけれども、第４次事業計画のどの路線を優先整備路線に入れますか、入れたいですかという意見照会が来ているのかという質問を先ほどからしているのですが、よくわからないのです。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"その時期につきましては、既に検討していかないと、今年度の策定にはなかなかスケジュール的には難しいですので、東京都のほうに検討の結果、あるいは意見等を申し述べていきたいというふうに感じてあります。最後の第４次路線のところだけ少し補足しますけれども、今まさにパブリックコメントをやっているということで、何をどのように選んでいくかということの指標をまさに決めているところです。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、３番目にかかわってくる地域の実態の問題ですが、やはり事業認可されているわけで、かなりの数の方が私有財産を公共の福祉ということで使うというような事業ですので、認可をされているのに、私は別に難しいことを聞いているわけではなくて、世帯数、どれだけの区民の方に影響があるのかということを聞いているわけなのですから、そこはやはり今の時点で把握していない。","respondent":"中村都市計画課長","answer":"これが、都市計画道路が延焼遮断帯として形成されることにつきましては、例えば、公園、広場、防災広場につきましては、延焼遮断帯の機能としましては矛盾するということでもありませんし、また、区としましても、この計画道路の整備にあわせて。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"それをわざわざ道路で壊して進めようというのは本当に理不尽だと思います。これは意見です。こうした重大な事態になっているわけですけれども、この件は、品川区としては、東京都にきちんと確認して問い合わせたのでしょうかというのをお伺いします。耐震化、そして、請願項目にあります目標年次までに達成するというところにおいての品川区の考え方をもう少しお伺いします。","respondent":"中村都市計画課長、鈴木防災課長","answer":"ただ、区としては、特定整備路線、東京都と連携して進めているということには変更はございませんので、これを国あるいは東京都に問い合わせるという考えはございません。１点目の延焼遮断効果の道路等は最後の手段ということで、後手にあるというようなご指摘がありましたが、防災対策、考え方としましては、事前の備え、発災直後の対応、それから、事後の対応ということで。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"決定手続の問題ですけれども、今のご答弁ですと、やはり思考停止に陥って、東京都ととにかく進めていくのだと。進めていくことになったから、東京都にこういう問題が出ても問い合わせる考えはないと。問い合わせすらしないというのは、これはちょっと乱暴だと思います。ですから、そこはもう一度答弁お願いします。","respondent":"中村都市計画課長、鈴木防災課長","answer":"ただ、その判断が出ただけでは、この特別整備路線の事業がなくなるというわけではなくて、その判断のもとにさらに特定整備路線をどうするかという、こういった国あるいは都の判断に基づくものですので、これに基づいては。ただし、区としても、この重要性は認識をしておりますので、以前から全戸配布している「わが家の防災ハンドブック」での電気火災に関する呼びかけ、注意喚起だとか、それから、今後国の具体的な方向性が見えた段階で。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"この特定整備路線につきましては、この説明会に参加されて、ご意見をいただいて、議論をかなりしているということだと思うのですが、進め方についてですが、用地取得率が今現在、４月の段階でこの形ですけれども、今後どういう流れで、目標数値なんかあるのかというところと、それから、全てにおいて事業認可がおりていますが、どういう強制力を持っているのかというところを教えてください。","respondent":"中村都市計画課長","answer":"この事業に関しての用地取得率ですけれども、こちら、それぞれ事業が認可されて、また用地説明会が終わったのがまだそれほどたっていないところもあります。こんな中で、今後の進め方ですけれども、最終的には用地をお譲りいただくという行為の中で、そのためには契約が必要です。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"要は、例えば、最終的にはおしりが決まっているのです。それと、強制力ということ、最終的に何も応じないといった場合の強制力というのはどういう形でされるのかということなのですが、わりに地区開発とかやっているときはかなり強制力が強いので、最終的には立ち退きとかいろいろ法的な手段を含めてあると思うのですけれども、それはどうなのでしょうか。","respondent":"中村都市計画課長","answer":"そのためにはやはり丁寧な説明と、あと、個別の悩みに親身になってそれを聞いて取り組んでいく姿勢が大切だというのを、説明会の中でも申しております。説明会の中で、用地をどうしても譲れない場合はどうするのだという、こんな質問もありました。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"聞いていると、やはり早くやってほしいという方もいらっしゃるものですから、そこは完璧に、全員で拒否されているのであればまた考えなければいけないことなのでしょうけれども、早くやってほしいという方もいらっしゃることは事実なのです。そうなると、やはりお互いにあまりいい方向ではないので、理解を求めて、だけど、早期にしていただきたいというふうに思っています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"質問","question":"我々としましては、結論を出すということでお願いします。そして、この意見としては、今までも我が会派の考え方としては、この特定整備路線につきましては、防災性の高い道路であり、必要性があるという考え方を持っています。その上で、東京都に対して丁寧な説明をこれからも続けていただくことをお願いして、納得した上で、この請願に対しては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問","question":"公明党としては、本日結論を出すということです。それに資するものであれば、公明党としてはそれを当然推進していくという立場ですし、また、この引き合いに出されている基本計画の中にも、特にこの２つの大きい項目で、事業計画の中止、前半のほうにあることに関して、要は、道路、これについても道路交通の麻痺に関して、その道路の整備の重要性、これも当然明記されているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"安藤委員","kind":"意見","question":"結論を出すということで、採択を主張します。この事業が地域住民の皆さまの生活と環境に与える大きな影響があります。それと、道路整備の理由ですけれども、防災というのもやはり一番大事な住宅の耐震化や初期消火の態勢などが不十分でありますし、シミュレーションなどの問題も出ました。明らかになりました。以上の理由で、私は、これは廃止にすべき事業だと思いますので、本請願に採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"木村副委員長","kind":"質問","question":"本日は結論を出すということでありますが、特定整備路線とかそれ以外、このような状況で、例えば、感震ブレーカーの設置、そして、耐震補強、耐震などを全て行った場合、出火はしないのかどうかということを考えますと、私は、感震ブレーカーをつけても、たとえ耐震化をしても、火は出ると思っています。ですから、これに対しては、不採択としたいと存じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問・要望","question":"我々としてもこの場で結論を出すということにいたします。その理由ですけれども、私としても、住宅耐震化と感震ブレーカーの普及ということには賛同いたします。ただし、今後も住民、区民に対してする説明は、都と連携してしっかり区民に説明していただきたいということをお願い申し上げます。結論としては、今、繰り返しましたけれども、全体として見て、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどもご意見を申し上げましたけれども、ご理解をしていただけますようにということで、ご説明を含めて、頑張っていただきたい、丁寧な説明をお願いしたいというふうに思っています。生活が変わってしまうわけですから、生活を守っていけるのかと非常に不安になっていられると思うのです。不利益にならないように、都のほうとの協力とか、情報交換を含めて進めていただきたいということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"}]},{"id":"topic-05","title":"の専決処分の報告について（報告第１９号）","agenda":"の専決処分の報告について（報告第１９号）","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"事故でしたけれども、人身にならずに、車両ということだったのですけれども、作業の中で事故が起きるのは多少やむを得ないのかというところは理解した上でお聞きしたい。これ、両方とも、清掃事務所の職員が運転していてということになっているのですけれども、報告自体、状況がわからないので、区の直営の車両が事故を起こしたときに、この報告が発生するということでよろしいのですか。","respondent":"小林品川区清掃事務所長","answer":"おっしゃるとおりです。","id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"確認","question":"というのは、雇上車両が事故を起こしたときというのは、こういう報告は出てこないのですか。それも、事故というのはどれぐらい。逆に言うと、区の直営の台数と雇上の台数を考えたときに、事故率というとどうなのかと。今まで確認したことがなかったので、今気になったので。","respondent":"小林品川区清掃事務所長","answer":"こちらはいずれもご指摘のとおり、直営車の事故です。雇上車両につきましては、雇上車の契約案件の中で、車両の事故につきまして全て雇上会社、受託者のほうで対応することになっておりますので、結果的に損害賠償が発生しないため、専決処分の案件にならないという状況です。","id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。やはり一般の方から見ると、この車は直営か雇上かわからない中で、事故は起きてほしくない。ですから、その辺も、雇上会社に対しても、あまり、先ほど言ったように、数が多いから仕事も大変だと思いますけれども、事故のないようにうまくまた指導をしておいていただきたいと思います。これはお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"西本委員","kind":"確認","question":"１つ確認したいのは、さっき２５件あるということなのですが、職員の方々に報告というか、指導も含めての、こういうのがありました、気をつけましょうみたいなのは、隅々まで行っているという認識でよろしいですか。","respondent":"小林品川区清掃事務所長","answer":"あわせて、先ほどご指摘があった点ですけれども、基本的に、委託あるいは直営にかかわらず、全て区の清掃事業というふうに考えておりますので、年に２回ですけれども、雇上車の安全運行管理者を含めて情報交換し、再発を防止するための車両、そして、運転手。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"沢田議員の中でありました、２番目の東京オリンピック・パラリンピック開催の中で、ＪＲの跡地、隣のところですが、跡地にかかわった内容のものがありました。これは今、どういう状況なのかという進捗状況がわかればと思って、ご説明をいただきたいと考えています。説明できる範囲で結構ですので、今の現状をひとつ。それから、これからの予定みたいなものがあれば、お知らせいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/967161?Template=document&Id=4138#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":63254,"voices":198}},{"id":"h27-20150629-9","meetingId":"h27-cm06","date":"2015年6月29日","dateIso":"2015-06-29","committee":"文教委員会","time":"午前１０時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件抜き出しています。","topics":[{"id":"topic-01","title":"第５８号議案、品川区女性福祉資金貸付条例の一部を改正する条例","agenda":"第５８号議案、品川区女性福祉資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"１０.７５％から５％という、なぜ５％なのか伺いたいのと、あと、事務事業概要のほうで、貸付状況を見ますと、そんなに、５件とか、８件とか、６件という話で、あまり多くないとは思うのですけれども、ここの中で返せていない、延滞している方というのは、いるのかどうかお伺いしたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"延滞の人数につきましては、全体で３０数名程度です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、１年間で借りられている方は５名とか８名とか少ないけれども、延滞されている方は想像で３０数名いるということでいいのでしょうか。それとあと、母子・父子の貸付の東京都のほうのものを利用されている方というのは、どれくらい含んでいるかはわかるかどうか。わかれば教えてください。","respondent":"廣田子ども家庭支援課長","answer":"平成２６年度で、母子福祉資金につきましては、種類が多くなっておりますので、就学資金につきましては平成２６年度９０件ということになっております。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問・要望","question":"この貸付の件ですけれども、１０.７５％の基準のものについては、あくまで１０.７５％の利息が継続をするということなのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"現在、滞納している方が３０数名いらっしゃるのですけれども、債権管理のほうが順調に督促はしたり、電話とかはしているのですけれども、実際問題として、分納してほしいとかという交渉については、まだ積極的にはやっておりませんで。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"大変な生活の状況の中で借りられた方も当然おられるかと思うので、やはりそこら辺は、滞納されている方については一人一人やはり丁寧に状況を伺いながら、適切な措置をとっていただければと、そのように思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この新旧対照表のところで、第３条の、新のほうでは「時間外保育」、旧のほうでは「延長夜間保育」、この違いは何か、どう違ってくるのかを教えていただきたいのと、あと、第７条の「保育時間内延長保育」というのはどういうことなのか、基本的なところを教えていただきたいと思います。","respondent":"竹田保育課長","answer":"第３条の違いですけれども、従来は延長夜間保育ということで、６時半以降の延長のみを規定しておりましたが、先ほど申し上げましたとおり、短時間利用の方の認定に伴いまして、開所時間内も時間外保育料を徴収する必要があるため、「時間外保育」という言葉を使いまして。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとあと、階層が第１から第８までつくられたというところで、第３階層から第８階層までの所得割で出ているのですけれども、ちょっとわかりづらいので、この方々の年間所得は大体どれぐらいになるのかということを教えてください。それから、この階層別の人数、割合を教えていただきたいと思います。それとあと、階層の基本的な考え方というのは、第１から第８までにした考え方をお聞かせください。","respondent":"竹田保育課長","answer":"料金改定にあたっての基本的な考え方ですが、第１階層、第２階層は０円としている、あるいは第３階層は国基準額の第２階層と同額の３,０００円としている等、低所得者の方には十分配慮した内容となっております。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"新旧対照表の第６条なのですけれども、旧のほうですと、「保育時間外に特に保育する必要があると認められる乳幼児に対し、延長夜間保育を実施する」とあって、今度新しいほうは、「１日当たり１１時間までに限る」というような数字が出ていて、あと、「保育園の保育時間外に特に保育する必要があると認められる乳幼児に対し、延長夜間保育を実施する」というふうにあるのですけれども。","respondent":"竹田保育課長","answer":"１１時間を２５日利用した場合は、この２７５時間という時間になりまして、各１日当たり１１時間を超える利用分については、延長夜間保育料として徴収するという改正です。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"数字的にはわかるのですけれども、実際に今まで使われていた方に、簡単に言いますと影響があるのかどうか、今までここまでやっていたけれども、今回きつくなったとか、いや、緩くなったから例えばもっとできるのかとか、そういうところをお伺いしたいなと、そのように思うので、こういう方はと質問したのです。","respondent":"竹田保育課長","answer":"今回の改正により、２万３,０００円よりも高額となるのは第８階層のみであるため、指定管理者が保護者から受け取る歳入は年間約３２０万円ほど減収となると予想しております。ただし、区が保護者へ直接助成しておりました補助金約６５０万円は不要となる見込みです。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど、８階層の所得を伺ったのですね。お答えが年収だったので、すみません、年収だと多いですよね。可処分のところの所得を伺ったので、もう一回ここを教えていただきたいと思います。年収だと多くなってしまうので、どのくらいの生活水準かとわかるのはやはり所得だと思うので、すみません、もう一回ここのところを教えてください。","respondent":"竹田保育課長","answer":"申しわけございません。今、所得に関する資料は持ち合わせてございません。申しわけございません。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここすごく、実質の生活がどの程度かと把握するのに、年収ではだめなのですよね。そこが１点です。もう１つ、ぷりすくーるは預かり保育料がかかりますよね。預かり保育料のところと、あと、多分、幼稚園、就学前の施設なので、諸経費がかかると思うのですが、その辺がどの程度かかっているのか、トータルで見たとき、負担がどうなのかというところを教えていただきたいのですが、いかがでしょうか。","respondent":"竹田保育課長","answer":"今お手元の保護者実負担額というのが現行です。現行と比較いたしますと、一部を除いて約１０％増の保育料の改定を想定しているものです。これは私立幼稚園との比較においては、約８割程度ということで、私立よりも低く設定しているものです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"延長保育のところは０歳から２歳の保育園の部分なのですけれども、３歳から５歳のところは、多分、保育園で入っているお子さんが多数なので、幼稚園的な部分の時間よりも朝も夕方もかかる預かり保育を利用されている方が多いので、保育料のところだけで見るのではなく、プラスで預かり保育、何日利用するかによっても違いますけれども、１日単位の金額であると思っていますけれども。","respondent":"竹田保育課長","answer":"預かり保育料につきましては、午前７時半から午後６時半までの利用が時間当たり８００円、それから、午前７時半から午後７時半までの時間帯の利用が９００円、それから午前７時半から午後８時半までの利用については時間１,０００円となっております。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"意見","question":"就学前幼児教育施設ということで、保育園とは違うわけですけれども、やはり保育園と幼稚園、また、ぷりすくーる、ここのところ、幼稚園もかなり預かりをやって就労の支援にもなっているというところにおいては、保育園と幼稚園とぷりすくーるの保育料の違い、どういう考え方でやっているのか。基本のところの、それぞれ応能負担に変えましたというところにおいて、違うわけですよね。","respondent":"竹田保育課長、金子子ども未来部長","answer":"施設の性格上、区立幼稚園、就学前ぷりすくーる、それから私立幼稚園という３つの形態があるのですけれども、区立幼稚園につきましては、私立幼稚園に比べて保育料を低く抑えたもの、それから、ぷりすくーるにつきましては。このたび、子ども・子育て支援新制度で、保育園、幼稚園全体として全て応能負担にしていこうというのが国の基本的な考え方でありますので、今回、改めて全体的な状況に鑑みて改定のお願いをしています。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"今回は国の応能負担の考え方を取り入れていくということなのですが、１つこれから保育需要が高まっていき、保育にかかわるお金全体の金額が増えていくと、今の国の考え方からすると、全体が増えていけば、保育料にはね返っていくという考えを持っているのですが、その点はいかがでしょうか。","respondent":"竹田保育課長","answer":"今までの区立幼稚園、それからぷりすくーるにおきましては、一律の保育料の設定ということで行ってまいりましたが、国の新制度のスタートに伴いまして、国からはそれぞれの所得の能力に応じた応能負担という考え方が示されてきましたので、それに伴って改正するものですが。","id":"exchange-013"},{"speaker":"伊藤副委員長","kind":"確認","question":"何点か確認させてください。先ほど、３２０万円の減収という話を聞きましたけれども、これはつまり、国の方向性が変わったからこういうふうに変えていくと思うのだけれども、そうすると、いわゆる国の補助金であるとか、それから、ほかのところでこれが補填されるのでしょうかというのをお答えください。","respondent":"竹田保育課長","answer":"通常の施設には国からの補助金が出るのですけれども、ぷりすくーるに関しましては、公設民営ということで補助金が出ませんので、今までは保護者に対する補助金は区のほかの施設との整合性を考えて、区で独自に補助金を出していたものです。","id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"意見","question":"そうすると、この利害に関係している方々だけの意見でこれを判断するというよりは、もっと大きな観点、つまり、品川区の子育て全体の観点であるとか、それから品川区内にお住まいであるけれども、こういう施設に預けていない保護者の方々の意見を聞いた上で、総合的な保育システムを展開していかないと、税金の使い方についても、それから投入のしかたについても、さまざまな思いがあると思うのですけれども。","respondent":"竹田保育課長","answer":"今回は、開所以来１０年近く経過しておりますので、一定程度の料金改定をすることによって、区民の方のご理解を得られるものと考えましたので、今回、ご提案させていただいているものです。","id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"意見","question":"公的なサービスを提供するときには必ず税金が投入されているわけであって、それがあるからこそ見かけ上の保育料が少なく抑えられているわけです。だから、今お話しされたように、これからのさまざまな情勢を鑑みながら、品川区全体の保育事業を見つめた上で対処をしていただきますようにお願いをしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"意見","question":"そこがちょっとよくわからなくて、幼稚園でないのに、幼稚園の保育料と同等にするというところが、この施設が一体どういう存在、先ほどちょっとご説明があったのですけれども、そこは少しご説明いただけたらと思います。","respondent":"竹田保育課長","answer":"あるいは、また幼稚園と同等程度の教育をするということで、品川区が独自に多彩なメニューで幼児教育の新しい姿といいますか、そういったものを模索しながら設立した施設だと考えております。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"どういうふうに運営されて、どういう成果が上がったというのはいいのですけれども、平成２８年４月１日からこの保育料でやるということは、その時点でも今の状態の幼稚園でもなく認定こども園でもないというか、そういった形で進んでいくということにつながるのではないかと思います。その点はどうでしょうか。","respondent":"竹田保育課長","answer":"先ほど申し上げたとおり、１０年前に品川区独自の新しい形ということでスタートしたのですけれども、その間、今回、新制度がスタートしたということもありますので、今後同じ形態でいくのか、あるいは新制度の内容を踏まえた施設にしていくのかということは、十分研究して。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、そこでやっていくのですけれども、前にちょっとお聞きしたこともあるのですけれども、名称については、幼保連携認定こども園に類したものを使えるのは、半年間の猶予期間ということなのですが、そこについて今年途中でそういったことが迫ってきていることもあるのですけれども、それも含めて今後のこの施設がどうなるかというのは、保育料をこうしていくということにも絡んでくるので。","respondent":"竹田保育課長","answer":"新制度では、幼保連携型認定こども園の諸条件が示されたところなのですけれども、仮にそういったことを目指すときに、条件面だとか、例えば広さ、敷地の面積等、適合するものなのか、あるいはどうかということも詳細に検討しまして。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すみません、では最後。新制度に向けてどういうふうにこちらを展開していくかということは、十分検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"１つ漏らしてしまったので。延長夜間保育の利用料についてお伺いしたのですけれども、条例によると、延長夜間保育利用料額が、１人１時間４００円で、新旧も同じ。これが実際にどうなのか、これがまたこの改定でどう変わるのかというところを改めて教えてください。","respondent":"竹田保育課長","answer":"従来、６時半、延長夜間保育については、委員おっしゃるとおり４００円ということで決めておりまして、今回、こちらの増額については、検討した結果、今後も引き続き４００円としたいと考えています。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"延長だと１時間で４００円、夜間にかかると２時間で８００円になるということなのですね。はい、わかりました。区立の普通の保育園は、延長夜間保育利用料は段階に分かれていますよね。やっぱりここは違うのだという考え方なのですか。４段階ぐらいに分かれていて、多分、１時間４００円は最高額と思うのですが、では、ぷりすくーるは階層を設けなくて一本でやってきたということでよろしいでしょうか。","respondent":"竹田保育課長","answer":"委員ご指摘のとおり、保育園のほうは細分化されておりますが、ぷりすくーるについては一本化して４００円という形でわかりやすくしています。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"意見","question":"意見を添えて反対をいたします。共産党としては、幼稚園も保育園もどの子も等しくよい環境で育てていきたい。そして、応能負担という国の考えを導入していますけれども、保育にかかる総額が増えていくと、必ず保育料にはね返っていくという意味では、これからやはりとまらず保育料が上がっていく、負担増になっていくという考えに基づいていますので、反対をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この施設が０歳から２歳の保育料が保育園にということで、３歳から５歳が幼稚園にということで、この教育施設の性格が、０歳から５歳を預かっているこの施設の性格がはっきりしていないというか、新制度になったがゆえに、逆にそうでない存在になってしまったということがあるので、その点について、今後、新制度との関係をきちんと危惧して検討して進めていっていただきたいと思います。この議案は賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-02","title":"第６２号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第６２号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、説明していただいたと思うのですけれども、２段階で改正というのがどういうことなのかもう一回、すみません、言っていただきたいのと、これ、変わるのは金額だけの変化なのか伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"それで、４ページなのですけれども、４ページは、一部単価が下がっているものが、例えば、先ほどご説明した学校医、学校歯科医の補償基礎額で、左から３番目の１万１,４２７円というのは、旧が１万１,４３５円だったものが１万１,４２７円と８円安く単価が下がっていたり。","id":"exchange-025"}]},{"id":"topic-03","title":"第６３号議案、品川区立幼稚園条例の一部を改正する条例","agenda":"第６３号議案、品川区立幼稚園条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"さっきのぷりすくーるのほうも階層、先ほど所得を伺ったのですけれども、年収という形で答えられたのですが、それと同じにはなってくると思うのですけれども、割合、人数のところをこちらも聞かせていただきたいと思います。それと、やはり段階をつけた考え方というのは、ぷりすくーると同じになってくるのかを伺いたいと思います。","respondent":"竹田保育課長","answer":"所得階層ですが、割合です。第１階層が０.３％、第２階層が５.９％、第３階層が９.１％、第４階層が３５.９％、第５階層と第６階層が合わせまして８.４％、第７階層が３９.６％となっております。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、階層別の割合をお伺いしたのですけれども、この表でいくと、第４階層が８,４００円に上がるということで、ここからすると、今ちょっと計算したのですけれども、８３.９％の方が現行よりも保育料が上がると、こういった捉え方でまずいいのかどうか、１点です。預かり保育の中身を少し教えていただきたいのと、区立の幼稚園というのは、私立の幼稚園のように諸経費というのはかからないのかどうか。","respondent":"竹田保育課長","answer":"約半分の方が上がるです。それから、今回、保育料を見直ししましたので、預かり保育料についても検討しましたが、ご負担増になることもありますので、基本的には預かり保育料は現行どおりというところで考えているところです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"今、預かり保育は現行どおり変えないといったお答えをいただいたのですが、どのくらいの金額になっているか、ざっと教えていただけますでしょうか。","respondent":"竹田保育課長","answer":"すみません、変えないと申し上げたのではなくて、今回はご提案させていただいておりませんということです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"確認","question":"なので、保育料のところは保育園保育料と比べると比較的低く抑えられてはいますけれども、結局、利用者の立場で１日の保育時間が長くなれば、当然この預かり保育、１日４００円でも、２０日利用するとプラス８,０００円になるし、６００円だったらもっと１万２,０００円になってしまうとか、保育料よりも預かり保育のところのほうが額が多くなってしまう。","respondent":"竹田保育課長","answer":"預かり保育は日額で設定しておりますので、利用日数に応じて、利用日数が多くなれば月単位で利用料は増えるです。それから、諸経費は園服等です。預かり保育については、適正に運営していきたいと考えております。","id":"exchange-029"},{"speaker":"浅野委員","kind":"質問・要望","question":"区立幼稚園で、まず、先ほどのお金の話なのですけれども、保育料の合計です、ぷりすくーるのところでもお伺いしましたけれども、今回の改定によって、歳入というのでしょうか、どのぐらいの変化があるのか、ほとんど変わらないのかというところについて教えていただきたいと思います。","respondent":"竹田保育課長","answer":"区全体の歳入の状況ですが、今現在の保護者の方の所得状況が変わらないと仮定すれば、現在より約４０％の増になると予定しております。ただ、高所得の方々が私立幼稚園等を希望された場合には、想定よりも少なくなることも考えられます。","id":"exchange-030"},{"speaker":"浅野委員","kind":"質問・要望","question":"４０％増になるということで、実際にスタートしてみないと、この変化はなかなかわからないと思うのですけれども、もし余裕があると言ったら怒られてしまいますけれども、区立幼稚園のさらなる質の向上というのでしょうか、そういうことも心がけていただきたいし、また、設備についても、できる限り子どもの環境アップにつながるような、そのような手もできれば分けていっていただきたいと思います。","respondent":"竹田保育課長","answer":"今後も保育の質の向上に向けて全力で取り組んでまいりたいと考えております。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"意見","question":"その中に同じ年齢で保育園に行っている子と、幼稚園に行かれている子がいるということで、幼保一体施設とは言っていますが、この保育料の点で、明らかに新制度のもとでも、ここの体制は幼保一体に対しては異なった形になっているのですが、先ほどのぷりすくーると同じように、区立の幼保一体施設の今後といいますか、これも現行、その中に幼稚園があるということで、どういった展望なのかということと。","respondent":"竹田保育課長","answer":"先ほどのぷりすくーるのほうとの重複になりますけれども、それぞれの施設、幼保一体施設に仮に移行する場合に、条件面等はどうなのかということをしっかり調査しまして、また、保護者の方の幼稚園に預けられる方のお考え、ニーズ。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"私のほうが勉強不足なのかもしれませんけれども、幼保一体に類したというか、そういうものを使えないということですが、正式なこちらの区立の幼保一体施設の名称は、二葉すこやか園だとか、のびっこ台場だとかという形でいくということですか。すみません、もし私が違っていたら……。","respondent":"竹田保育課長","answer":"ご指摘のとおり、幼保一体認定こども園という言葉は使えないわけですけれども、幼保一体施設という名称は使用可能と考えておりますので、現行どおりでいく場合は、こちらの名称を引き続き使っていきたいと考えております。","id":"exchange-033"},{"speaker":"伊藤副委員長","kind":"確認","question":"何点か質問させてください。この幼稚園保育料の改定の中で、消費税が３％上がっていますね、当たり前ですけれども。その３％については改定していなかった、つまり、保育料に上乗せしていなかったのでしょうかという確認と、それから、保育料の減免措置、例えば確か第二子は半額だとか、そんなことがあったと思うのですけれども、その減免の措置を改めて教えてください。その２つ。","respondent":"竹田保育課長","answer":"保育料の減免については、少子化に対応できるように、第二子半額、第三子免除という形をとっております。","id":"exchange-034"},{"speaker":"伊藤副委員長","kind":"確認","question":"その中で改めて決算を勉強すると、平成２５年度の歳入、つまり、保育料等々の総額は約８,９００万円。それから歳出、これは職員の給与費と事業費を合わせて４億６,０００万円というふうに計算したのですけれども、数字が正しいでしょうかという確認と、それから差額が約３億７,０００万円、これがつまり品川区の一般財源から充当されていると思うのですけれども、この数字の確認を改めてお願いします。","respondent":"竹田保育課長","answer":"平成２５年度の決算ベースですが、歳入のほうが、幼稚園保育料、手数料、国庫補助、預かり保育料等を足しまして約８,９００万円。歳出のほうが、職員給与費、あるいは事業費を足しまして約４億６,０００万円。歳入と歳出の差が約３億７,２００万円という形です。","id":"exchange-035"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認ですけれども、歳入の中に国庫補助が入っていると聞いたのですけれども、これは何ですか。その確認と、それから、この３億７,０００万円が一般財源で補填されているからこそ、この保育料で運営されていると思うのだけれども、その確認をお願いします。","respondent":"竹田保育課長","answer":"先ほどの国庫補助につきましては、生活保護や非課税で減免される方の分が補助されておりまして、平成２５年ベースで申し上げますと、１０万４,０００円というふうになっております。","id":"exchange-036"},{"speaker":"伊藤副委員長","kind":"確認","question":"先ほど、この改定で保育料が２,３００万円ぐらいアップすると言っていましたけれども、保育料の改定が２,３００万円増と聞きましたけれども、そうすると、単純に平成２５年のベースで考えますけれども、８,９００万円に２,３００万円の上乗せをされたとしても、つまり、品川区からの一般財源の投入はあるということの確認をお願いしたいと思いますが、その確認と、それから、唐突ですけれども。","respondent":"竹田保育課長","answer":"少子高齢化の社会に適切に対応していけるような保育料を今後も考えていきたいと考えております。","id":"exchange-037"},{"speaker":"伊藤副委員長","kind":"意見","question":"だから、このことについて、私ども反対するわけではないのだけれども、だけれども、税金の投入のバランス、公平性というものについては、まさに皆様方が、理事者の方々がしっかり考えていかないと、さまざまなところで大きな不満が出てくる可能性があるので、そのことには重々注意をしていただいて対処していっていただきますようにお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"意見","question":"意見を添えて反対をいたします。１つには、第３段階が３,０００円ということで下がるということは歓迎いたします。しかし、先ほどのご答弁の中にも、８割強の方が値上げに、負担増になっていくといった中身、そして、大もとにあります応能負担が公平とは考えておりません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"賛成です。今、税金のお話もありましたとおり、やはりかなり保育料が上がる方も中にはいらっしゃるので、十分にご説明していただいて、今、教育内容も充実していると思うのですが、さらに充実した保育をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-04","title":"第５５号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５５号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"医療的なケアを必要とする障害児に対する保育料助成について伺いたいのですけれども、この保育施設というのは、どういう、認可保育園とか幼稚園とかあると思うのですけれども、保育施設というのは何を差しているのかということと、あと、助成の対象者を審査会に基づき開催される特別支援保育利用調整会議においてということですけれども、この会議体はどんなメンバーで構成されているのか伺いたいと思います。","respondent":"竹田保育課長","answer":"会議体ですが、この会議体については、子ども未来部長を筆頭に、保育課長あるいは係長、それから園長等によりまして構成されている要綱に基づく会議体です。それから、助成区分ですが、先行して実施しております杉並区を参考に今回の助成区分を設置したものです。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、区内にはそういう施設がないということですね。それで、杉並区を参考にということで、この杉並区の施設はどういった施設なのか教えていただきたいと思います。それから、そういった医療ケアが必要なお子さんというのは、今現在、どれくらいいるのかお伺いいたします。","respondent":"竹田保育課長","answer":"杉並区で実施されてあります施設は、こういった医療ケアの必要なお子さんに特化した施設と聞いております。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"この中のお一人のお母さんから私も相談を受けたのですけれども、何とかならないかと、区にはお願いしてきて、なかなか保育園も見つからない中で、杉並区のほうで特化した施設というところも見つけたということだったのですけれども、区が把握している範囲で、こういった医療ケアが必要な子を受け入れる保育園というのは、他区ではどれくらいあるのかというのは、区内にないわけですから。","respondent":"竹田保育課長","answer":"周知しているかということなのですけれども、やはり医療的ケアが必要なお子さんは、ご自宅でみていただくことが最善だと考えておりますので、特段の周知はしておりませんが、就労支援の観点から、必要とされる保護者の方には助成をしていきたいと考えております。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、区内にこういった施設がないのであれば、そういった他区に、また他県にあるというのは周知していただきたいと思いますし、このお母さんもおっしゃっていましたけれども、こういった対応がされたのは本当にうれしいと。区内でこういった施設を運営していくということは、検討されたのでしょうか。それで、またどう考えているのかを伺いたいと思います。","respondent":"竹田保育課長","answer":"先ほども申し上げましたけれども、医療的なケアを必要とするお子さんをお預かりするというのは、非常にリスクのある難しいことだと考えておりますので、通常の保育園ですぐに実施するということは難しいと考えています。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当にこういった受入れ先がないというところで、諦める方のほうが多いと思うのです。ですので、この保育料助成は大きな一歩だなと評価したいと思うのですけれども、ぜひ区のほうでもこういったお子さんの対応をできるように、先ほども言いましたけれども、なかなか進まない難しいという状況もありますけれども、他区にあるという点をぜひ周知していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"１９ページの待機児童解消対策の公園のところに保育園をという中身なのですが、６３０万円で委託ということなのですけれども、どういう中身を委託するのかというところと、どのような事業者がこういう委託を受けるのかを教えてください。","respondent":"今井待機児童対策担当課長","answer":"公園の整備にあたりますので、こちらは、例えば公園の地下埋設物ですとか、あとは実際にはどのような広さ、または近隣の状況も踏まえまして調査をしていく予定です。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"続いて質問をしますけれども、オンライン英語レッスンの資料を出していただいたのですけれども、これ、おもしろいというか、あまり普通にはというか、なかなか普通には発想できないような中身なのですけれども、このことで今の現状の子どもたちが英語が好きになるのかどうかというのが一番のポイントだと思うのですが、そこのところと、どこからこのような発想が出てきて、どのような経緯で計画されたのか。","respondent":"今井待機児童対策担当課長、渋谷指導課長","answer":"施設概要としましては、公園ということで、今、実際に国家戦略特区の施設の基準というのですが、そういうふうな緩和の内容がまだ明らかにされておりませんので。現場の意見はですが、実際に導入を検討するにあたって、モデル校の英語の先生等々とも話をさせていただいて、ぜひこれは非常にいい取り組みだというようなことで、現場の先生方のご意見も十分反映させながら。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"英語の教科の先生は十分そのクラス全体を把握しながら授業を進めているわけですけれども、２５分間、タブレットに向かって異国の人とコミュニケーションをとるわけなのですけれども、子どもたちの能力の差というのか、そういうものに十分合わせて行われるのかどうかというのと、その指導員の方の身分とか資格、英語の教師だったら教員としての訓練を十分受けているのですが。","respondent":"渋谷指導課長","answer":"２５分間の使い方ですが、基本的には先ほどもちらっとご説明しましたが、一般のオンライン英会話ですと、新聞記事だったり、雑誌だとかでフリートーク中心に時間を積み重ねていくという形ですが、中学校の授業の中で導入をするですので、教科書を。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１つ、英検のことなのですが、ちょっとだけ具体的に聞きたいのは、英検は結構受けていらっしゃる方が多いのですが、６年生、小学校のところは全国では初めてではないかと、２００人を想定されているのですけれども、実際、中学生のところは中学校のところでやられていると思うのですが、小学校のこの２００人というのがどこで検定を受けるのかというのが１つと。","respondent":"野呂瀬学務課長","answer":"今、区立の６年生は大体２,２００人ぐらいいるのですけれども、昨年受けた１８０人弱の中で、区立の子がどれぐらいいたかは把握していないですけれども、当然今回は区立の子だけという対象ですので、最大でも２００人ほど見込めばという形で算出をしております。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その小学校のところなのですけれども、つかめていないという現状だと思うのですが、中学校の先生に言わせると、どこの学校かわからない子どもが結構中学校で受ける方のつながりで、書類をもらったりとかしながら、小学生が結構来ているのだそうです。現場の負担が非常に、把握していない子どもたちのところが、とまどっても困りますので、丁寧にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今、飯沼委員のほうから大分わからないような話が先走って進んでしまったので、もう一度、先ほどのオンラインのマンツーマン英会話レッスンについてお聞きしたいのですけれども、これを読んだときに、これは非常にいいなと思って質問しようとしたら半分ぐらいされてしまったのでかいつまんでしますけれども、まず第一に、これはさっきのお話だと学研からの持ち込みということだったのですけれども。","respondent":"渋谷指導課長","answer":"フィリピンの現地講師は、基本的にスービックというところと、セブと２地域の方を現地講師として予定をしているです。実際、昨年度２月に学研の編集部の方が現地のほうに視察して、実際の英語能力等々については確認をされてきているということを聞いております。","id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほどのお話だと、例えば受動態の授業のときに、その受動態に沿って会話をするとかというようなお話だったのですけれども、それだったら別に外国人と話などしなくても、日本でネイティブのインストラクターの人とか、英語の先生が話せば十分なことだから、わざわざオンラインで直接生の外国人と話をするせっかくの機会があるのだったら、もう少し発展的な、成果がどうのとか、子どもが個人差があるとか。","respondent":"渋谷指導課長","answer":"その段階でやって、実際にもっともっとコミュニケーションをとりたいという子は、「実は僕、趣味がこうなのだけれども、先生どうなの」と、それは自由にやりとりするという、その部分の発展形がいかようにもつくれるのがこのマンツーマンのまさに醍醐味であるし。","id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それは要望で。スマホのところは、この９００万円というのはアプリの導入で、ランニングというか、それも全部含めての話なのでしょうか。それとも来年度からランニングの面でまた契約してみたいな、ここの業者がそうなのか、そういうことも含めてもうこれでずっといけるのか、そういうことはまずないと思うのですけれども。","respondent":"渋谷指導課長、伊崎子ども育成課長","answer":"基本的に、今、例えば授業でレッスン９をやっていたら、オンラインでやるところはレッスン８までの、基本的に前にやったところの復習ベースで、その前にやったものをベースにしながら。子育てアプリのランニングコストです。今回、計上いたしましたのは、構築費ですので、来年度以降の計上分については、今回の補正予算を可決いただいた後、来年度の予算で計上を考えているところです。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"オンラインのほうは、ある程度、何曜日何時というふうになってしまうのと、今、時間数の話で出たのですけれども、２５分とはいえ、１コマそこに費やすことになります。それから、ランニングのほうは、幾らぐらいなのですか。ほかのところでやっているのを見てみますと、いろいろあるのでしょうけれども、予算の話なのであれですけれども、ほかの自治体は幾らぐらいなのでしょうか。","respondent":"伊崎子ども育成課長","answer":"予算の話ですので、まだはっきりとこちらのほうでの計画はこれからなのですが、世田谷区で似たようなことをやっていまして、そちらの経費は３８０万円ほどがランニング経費で、改善が必要な場合は別途コストがかかるというふうに聞いております。","id":"exchange-054"},{"speaker":"浅野委員","kind":"質問・要望","question":"それと、理科の観察実験支援事業ですけれども、これも理科離れというのが一頃、今もそうなのかちょっと私も認識はしておりませんけれども、言われてから久しいわけですけれども、これは取り組みとしては、理科の先生ですか、実験をする先生を導入するというのでしょうか、呼び寄せる費用なのか、それともまた別に何かプラスアルファで機材をそろえたりとか。","respondent":"竹田保育課長、村尾教育総合支援センター長","answer":"ただ、今回のようなかなり特殊といいますか、難しい問題をはらんでいるお子さんのケースについては、一定程度のノウハウも必要ですし、需要等も考えながら、あるいは。昨年度、平成２６年度は、５校指定をして実施をしております。そして本年度につきましては、小学校、中学校、一貫校も含めて全１１校でこの推進事業を実施しております。","id":"exchange-055"},{"speaker":"浅野委員","kind":"質問・要望","question":"それぞれありがとうございました。このオリンピック・パラリンピック教育推進校ですけれども、これまでですと、全部で１１校になるのですね。そのぐらいの数なのでしょうか。理科のほうについても、補助員という形でアシスタントですか、そういう形で手助けをしてくれるということですので、こちらもぜひ継続した形で進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは本当に子どもたちが話す機会というのは非常に大事だと思いますし、まさにネイティブの方と英語を話しながら、話していく、伝えようとするという会話の仕方というのが、なかなか外国の方とする機会が少ないので、非常にいいことと思っておるのですが、今後、英語の授業として、これだけの成果があったとかという効果の測定の仕方、効果測定をどうやっていくのかと、あと、その後。","respondent":"伊崎子ども育成課長、渋谷指導課長","answer":"対象としましては、妊娠期から就学前、学校入学前までのお子さんをお持ちの保護者の方と考えております。それから３点目、こういった学びをした子どもたちが外国人との交流をですが、これも一昨年度から始めておりますグローバル人材育成塾、放課後の英会話教室に子どもたちが。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"それぞれありがとうございました。アプリについても、ぜひ皆さんが使いやすいようにしていただきたい。区民の方々に伺うと言っていましたけれども、どういった方に伺うのかというところだけ教えていただければと思います。","respondent":"伊崎子ども育成課長","answer":"今現在、子育てガイドの編集にＳＫＩＰという、ＮＰＯではないのですが、子育てをしているお母さんたちの団体と協働でやっております。そういった方を中心にお話をいただいていこうと考えています。","id":"exchange-058"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"１点だけお伺いさせてください。待機児童解消対策費について、この中で、都市公園の中の保育園の話がありました。非常に関心がありますので、プロポーザルされていたのですけれども、例えば、具体的にいつぐらいまでにその回答を求めていく、それからスケジュール、議会への報告等々についてはどうお考えなのでしょうかということだけお答えください。","respondent":"今井待機児童対策担当課長","answer":"これが二、三カ月に１回と聞いておりますので、先ほど申しました施設基準の詳細、緩和策が出てくるのが９月の下旬というふうに聞いておりますので、やはりそこを踏まえませんと、具体的な公園等の調査は難しいかというふうに考えております。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"賛成です。それで一言。医療的なケアの必要な子どもへの施設、本当に品川区内でつくっていただきたいということを最後に強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-05","title":"平成２７年請願第１８号、子育て世代が希望を持って働けるように認可保育園の大幅増設を求める請願","agenda":"平成２７年請願第１８号、子育て世代が希望を持って働けるように認可保育園の大幅増設を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"初めになのですけれども、本日の請願は、認可保育園の大幅増設を求める請願なのですが、このところ毎年、毎議会ごとにこの認可保育園増設を求める請願が出されているわけですけれども、このことに対して、区としてどう受けとめていらっしゃるのかということをまず最初に１点お伺いしたいのと、あと、改めて数字をお伺いしたいのが、今年度の４月１日のところで、認可保育園を希望した人数、入園できた人数。","respondent":"今井待機児童対策担当課長","answer":"初めに、定例会ごとに子育ての方から認可保育園の開設についてのご請願をいただいていることにつきましては、やはり待機児童解消ゼロを求める皆さんの区民の声だというふうに認識しております。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"今出していただいた数字なのですけれども、いわゆる不承諾が、区が算定をする待機児が２１５人ということなのですけれども、この差について、厚生労働省の内容に基づいて算出をしているということなのですけれども、１,０１５人から２１５人に至る引かれた部分、どういう理由で引かれているのかということを改めてお聞きしたいと思います。","respondent":"今井待機児童対策担当課長","answer":"平成２７年度７０９人の受入れ拡大のうち、認可保育園で開設する部分は、今、４８８人を想定しております。０歳から２歳については、今、手元にすぐ資料はございません。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"今お伺いした平成２７年度と平成２８年度のところの受入れ枠、認可保育園に関してお伺いしたので、７０９人と５８０人、合わせると１,２８９人なのですね。０歳から２歳はちょっと数字がわからないということなのですけれども、おおよそ半分ぐらいと考えてもよろしいのでしょうか。０歳から５歳の間で、０歳、１歳、２歳が約半分ぐらいかなと思うのですけれども、その辺の考え方についていかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"先ほど５８８と申し上げたかもしれないです、４８８人です。０歳から２歳につきましては、委員ご指摘のとおり、半数以下の状況になっております。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"母親の希望として、今回の請願も中心的なところは認可保育園の大幅増設というところを願っているわけですけれども、ママやパパたちは、とにかく認可保育園をつくってほしいと言って頑張って、結局は入れなかったというところにおいて、認証に行ったり、小規模保育事業に行ったり、認可外に行ったり、あと預けることができなくて職を辞めたり、いろいろなケースがあると思うのですが、それぞれの立場の中で。","respondent":"今井待機児童対策担当課長","answer":"最初のご質問は、３歳児の受け皿というご質問というふうに理解したのですけれども……。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"そうです。受け皿としながら、認証保育園に入っているお子さん、小規模保育事業に入っているお子さん、あと認可外に入っているお子さん、その人数を教えてください。","respondent":"今井待機児童対策担当課長","answer":"ただし、品川区としましては、認可保育園に入りいたいというふうなご希望を受けまして、なるべく窓口で丁寧にご説明を、近隣の認可保育園だけではなく、地域型保育、そして認証保育の場所等についても丁寧にご説明申し上げ、マッチングを図っているところです。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"認可外のところにもいらっしゃる方がおられるというところにおいては、今の品川区が進めているテンポ、平成２７年度、平成２８年度のところも約５００人ぐらいなので、圧倒的に足りないという認識を私たちは持っていて、毎年毎年待機児がここのところ膨らんでいるという実態から見ても明らかだと思うので、やはり今のテンポでは足りない。","respondent":"今井待機児童対策担当課長","answer":"テンポまたはペースのことですけれども、今回も私ども、待機児童の状況を踏まえまして、５月の臨時会で大規模保育施設の提案をさせていただきましたけれども、今後、人口動態の調査等も出ますので、子ども・子育て計画にのっとって今進めているところですが。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は今いろいろ数字をお伺いしましたけれども、こういった事態を捉えられて、今日、委員の方、各会派の皆さん、多分実態を受けとめておられると思うので、その辺をどのように受けとめていらっしゃるのか、また、この足りない保育園をどう解決していったらいいのかとお考えがありましたら、ぜひ聞かせていただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"浅野委員","kind":"質問","question":"区のほうでは、認証保育所とか、さまざまな形態で受入れ枠等を拡大しつつ進めてきているということですが、今後、品川区の人口動態を調査されるとは聞いておりますけれども、そういうことに照らし合わせると、どのようなカーブと言ったら怒られてしまうのでしょうけれども、今後の見通し、保育園に入りたいという方の見通しというのはどのように考えておられるのか、その点について教えてください。","respondent":"今井待機児童対策担当課長","answer":"一番端的に数字がとれますのは、入園の申込者数、これがどのくらい伸びていくかというところがありますので、人口だけではなく、この入園の申込みの割合、これを見ながら整備を進めていきたいというふうに考えております。","id":"exchange-068"},{"speaker":"浅野委員","kind":"質問・要望","question":"前にも決算で発言させていただきましたけれども、待機児童の偏在というのでしょうか、荏原についてやはり厳しいという話を伺っております。そういう観点も含めて、やはり区が実施している総合的な待機児童対策、さまざまな観点から、ある意味では理解できるような内容で進めていっていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"かなりたくさんいらっしゃるのですけれども、例えば、外国人、中国人などは、今の区の待機児童の予測の数の中に入ってきて、今後ますます増えていきそうな感じがするのですけれども、高どまりしてというそのパラメータの中に入って、当然それも加えた上で計算とか推定とか、外国からいらっしゃる方もたくさんいると思いますけれども、これが入っているかどうかお聞きしたいです。","respondent":"今井待機児童対策担当課長","answer":"青少年人口の推移でもありますけれども、平成２５年１月１日からにつきましては、平成２４年に住民基本台帳法の変更がございましたので、外国人の人口も反映して行っております。","id":"exchange-070"},{"speaker":"鈴木（博）委員","kind":"意見","question":"一応、今現在、外国から来た方も統計の中に含まれているということで、それは理解したのですけれども、ただ、日本人の出産人口の経過と、外国から日本にいらっしゃってこちらで生活、流入してくる方というのは、必ずしもパラレルではないのではないかという気もするのです。その辺の配慮とか、計算とかもされたほうがいいのではないか。当然されているわけですよね。","respondent":"今井待機児童対策担当課長","answer":"ですので、外国人の動向を含めまして、今ご指摘ございましたけれども、日本人の増加の指数だけではなくて、外国人のところに着目した指数もあわせて今後人口動態を捉えていきたいというふうに考えております。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、先ほども補正のところでありましたけれども、９０人規模の１,０００m2という、そういうのは園庭も加味した上で探していくのかを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"大規模保育施設につきましては、敷地内に一定の中庭を設けるというふうなご説明をしたところですが、しながわ中央公園を代替地としておりますし、また、今度の公園における保育園整備に関しましては。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、ぜひ園庭と、そして公園の確保、各保育園は本当に苦労していろいろやられていると思うのですけれども、東大井にある保育園から大井町駅を通って、さらにイトーヨーカドーのほうまで行ってという、公園に向かって歩く子どもたちを見ていますと、本当に保育士の皆さんもご苦労があるなというふうに思うのですけれども、それをやっぱり近くに、本当は身近にあれば、どれだけ安心で。","respondent":"今井待機児童対策担当課長","answer":"私どもの考え方では、敷地内の屋外遊戯場は必置ではございませんので、近隣の公園等を代替にして、そこで十分保育活動をしていただけるよう、今後とも保育園と協議して進めてまいりたいというふうに考えておりますので。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういう手法でやっているということを聞いたので、ぜひ品川区も実態をきちんと把握を、まずされているのかどうかというところと、私は、いつもしつこく０歳は、１歳は、２歳はと聞いているところは、やはり足りないところに手立てをしっかりと立てていくということが大事なので、ぜひその努力をしていただきたいのと、実際にどこまでそういうことをされているのかということを最後にお伺いしたいと思います。","respondent":"今井待機児童対策担当課長","answer":"０歳、１歳、２歳のところで、特に１歳児は今回１２５人ということで待機児童を出しましたので、品川区としましては、０歳、１歳、２歳に効き目のある小規模保育、効果的に開設できる小規模保育も組み合わせて、認証保育所も組み合わせて、これは開設していかないと。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認可保育園も特に品川区は来年３００人の区立の保育園を開設するというところに、私は新たな決断だと思っているのです。幼保一体化はあったけれども、認可保育園を新たに区でつくっていくという、やはりここのところに核心を持って進めていただきたいと強く思うわけですけれども、最後です、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"先ほども平成２８年度の開設の中で、現在、６２０人の受入れ拡大のうち、認可保育園は５８０人ということでご説明いたしました。","id":"exchange-075"},{"speaker":"伊藤副委員長","kind":"確認","question":"いろいろ勉強する中で何点か確認させてください。事務事業概要によれば、平成２７年度予算は、保育園関係に１００億円前後の品川区の税金が投入されています。予算ベース。","respondent":"今井待機児童対策担当課長","answer":"この１１０億円は、開設の経費は例年、今年も５億円余ぐらいの認可保育園の開設経費をつけていただいておりますが、基本的には運営費等を含めまして、子育て施策全般のところがありまして、保育課でもやはり生活支援型のオアシスルームですとか。","id":"exchange-076"},{"speaker":"伊藤副委員長","kind":"質問","question":"利用者の負担率を見ると１４.９％、つまり、全体の運営費の８割以上が税金でまかなわれている現状もその一方である。こういう請願・陳情は、なぜか公立保育園をつくるという請願があるのだけれども、例えば在宅の子育てをしている方々からの請願・陳情はほとんどないし、そういう方々がこういう現状を知ったら、極端なことを言うと、例えば、年間１５万７,０００円ですか、平成２７年の予算ベースで。","respondent":"金子子ども未来部長","answer":"それともう一方考えなければいけないのは、今、委員お話のありましたとおり、在宅で子育てされている方、こちらに対しても子育て支援、なかなか少子化社会、子育てに孤立感、あるいは不安感を抱えている方が非常に増えているという中では、在宅で子育てされている方への支援。","id":"exchange-077"},{"speaker":"伊藤副委員長","kind":"意見","question":"この中で保育園についても、約１００億円前後の品川区の予算が投入されています。これで保護者負担が１０何％、基準のことも考えていかなければいけない。要は、そういうさまざまな観点で待機児童対策をとっていくことのほうが、私は税制も、それから税金の使い方についても、ある程度、重要な担保をとった上で、でも、現実の維持に対処できると思うのだけれども、改めて品川区のお考えをお聞かせください。","respondent":"金子子ども未来部長","answer":"公園もその１つですけれども、そういった１つ１つについて最も効率がよい、あるいは質的にもこれのほうがよいというようなところを、各場面場面で検討して最善の答えを求めながら結論を出していく、こういう姿勢にかわりはないところです。","id":"exchange-078"},{"speaker":"伊藤副委員長","kind":"意見","question":"決して私たちは待機児童対策をやらないということを言っているわけではなくて、進めていくべきだと思っています。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"特にいろいろな、先ほど、伊藤副委員長からもあったように、子育てというのはいろいろなことをやらなければいけないので、その１つに特化してこれだけという形で限定するというところでは逆に区の待機児童対策に縛りをきかせるようなこともあるのではないかというようなことも考えまして、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"浅野委員","kind":"意見","question":"さまざまな施策で総合的に待機児童対策をしていく、これまで区が進めてきて、また、これからも進めていくという、そのような流れかと思います。時により人口の動態も随分変わってくる。変わってくるという将来予測も出てくるかと思います。そういう意味からして、願意に沿いがたいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見をつけて採択を主張いたします。本請願は、認可保育園の増設を求めているわけです。地域の方がどんどん保育園に入ってきて、保育の子育て拠点になっていくと言った意味では、保育園は本当に子育てを支える大事な大事な施設になるといった意味では、この請願が求めております園庭も必要です、公園も必要です、認可保育園の大幅増設、ぜひ応援をしていきたいと思います。採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"大倉委員","kind":"質問・要望","question":"理由としては、今現在、お話をいろいろ伺った中においても、品川区ではさまざまな総合的な視点から施策を展開している中において、私たち、我が会派、民主党・無所属クラブでも、待機児童をできるだけ減らしてゼロを目指していくという中で、この認可保育園に限定して施策展開していくというよりも、総合的な施策で対応していくことのほうが、ゼロを目指していく中において効果的と考えますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"不採択でお願いします。ただ、保育需要の正確な把握、そしてその後の動向や、それからさらに、今回の３００人の大規模ではないですけれども、スピード感というのでしょうか、それをもって総合的に進めていっていただきたいというところで、こちらの題にあるような形での限定という形ではなくて、総合的に進めていっている点で、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"}]},{"id":"topic-06","title":"を行います。 (1)専決処分の報告","agenda":"を行います。 (1)専決処分の報告","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"Ａ４のところの２の訪問督促のところですけれども、シルバー人材センターに委託ということと、訪問督促と書いてあるのですけれども、どういう中身で委託をして、実際にどんな中身で、なかなかデリケートな中身なので、どういうふうな督促をしているのか教えてください。","respondent":"廣田子ども家庭支援課長","answer":"仕様といいますか、２人専従で、かつてこういう仕事をしたことがある方ということで、平成１４年から同じ方だったかと思いますけれども、督促を区から出しましてお返事がない方で、区内に住んでいる方に訪問をして事情を聞いていただくという形をしておりまして。","id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問","question":"和解のところを見ると、具体的には１万円とか、１万５,０００円とか、払えるところで分納しているということですけれども、この辺は、早くたどり着けば、もっと気が楽というか、結構支払いできていないいろいろな事情はあるかとは思うのですけれども、期間が長ければ長いほどやっぱり負担になってしまったり、金額が膨らんだりというところにおいては。","respondent":"廣田子ども家庭支援課長","answer":"訪問督促につきましても、書類は来ていたけれどもというところで、シルバー人材センターのスタッフがいるところで、払いますということも来ていますが、弁護士による督促で、弁護士に７４件委任しているのですけれども、訴えの提起に至ったのが１３件ということは。","id":"exchange-086"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"勉強不足なので教えていただきたいのですが、こうした債権は時効がどれぐらいで回収できなくなるのか。あるいは、できないのでしょうか。その辺がわからないので。そういうことが何かトータルでその方がどれだけの状況だということを把握することにつながらないというか、債権回収の優先順位というか、そういうふうにつながっていくと思うのですが、その辺はどうなのでしょうか。教えてください。","respondent":"廣田子ども家庭支援課長","answer":"直接強制権は持っておりませんので、こちらで強制的にお調べするということはできない状況なので、ご本人に確認をして、自己破産をしていたりとかということですと、あちらの弁護士であったりとか、公式な書類をというところで確認をするというところで。","id":"exchange-087"},{"speaker":"石田（ち）委員","kind":"質問","question":"どういう形で和解などが進んだのかを伺いたいと思うのですけれども、例えば、報告第１７号ですと、こういう形で進みましたということは書いてあるのですけれども、この方の実態、分納不履行になっていたということなので、話し合いになったりとか、あとは生活実態だったりとかを、どう把握して進めていったのかということをお聞きしたいのですけれども。","respondent":"廣田子ども家庭支援課長","answer":"この３件につきましては、ご本人から幾らぐらいとかに関しましては、１回月幾らぐらいだったら払えますという申し入れをいただいているのですけれども、それで本当に無理がないかどうかをこちらでも収入と支出を確認しまして。","id":"exchange-088"}]},{"id":"topic-07","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それともう１つ、飯沼議員のところの保育園増設、待機児ゼロへさらなる増設をのところで、待機児ゼロは区の政策目標ですという答弁があったのですけれども、政策目標というのは具体的に何なのかを伺いたいのと、あと、１,０００人を超える子どもの、先ほどの請願のところでも人数を出されましたけれども、不承諾の１,０１５人の年齢別、そして親の就労状況も聞いたのに、そこへの答弁がなかったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"今の前段のところの安藤区議のところの質問なんですけれども、明確なご答弁がなかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問","question":"なかったです。質問に対してのご答弁がなかったのですね。教育委員長はなぜ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は１,０００人を超える子ども、だから、そちらが待機児と勝手にとったわけですが、私は間違わないように１,０００人を超える子どもたちの年齢の別と親の状況と、委員会で出なかった数字を事前に本会議で質問を事前に知らせて中身を教えてほしいという質問をしたにもかかわらず、委員会と同じ、だから２１５人ではないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、答弁がされていないというところで、教えていただきたいのです。","respondent":"塚本委員長","answer":"されていないという認識はおそらく私としてもないので、それはちょっと取り上げられないです。","id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問","question":"そうですか。本当に理由をお伺いしたのだけれども、答弁は話されたけれども、的が全然合っていなかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、ちゃんと答えなくてもいいということになるではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/111718?Template=document&Id=4856#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":63581,"voices":281}},{"id":"h27-20150629-5","meetingId":"h27-cm06","date":"2015年6月29日","dateIso":"2015-06-29","committee":"総務委員会","time":"午前１０時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","topics":[{"id":"topic-01","title":"６号議案からの審査ではありますが、会議の運営上、審査の順番を入れ替えまして、(3)第６５号議案および(4)第６６号議案を先に行います。 まず","agenda":"６号議案からの審査ではありますが、会議の運営上、審査の順番を入れ替えまして、(3)第６５号議案および(4)第６６号議案を先に行います。 まず","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"契約案件ということではあるんですけれども、この工事を請け負う会社と、あと実際に公園を管理運営する運営者と言ったらいいんでしょうか、そこはどういうふうに調整というか連携を図っているのか、ここを伺いたいと思ったんです。ここをご説明いただきたいと思います。","respondent":"立川経理課長","answer":"いわゆる工事業者と運営事業者につきましては、別の契約になりますので、連携というのは主管課のほうで調整していただくというふうに伺っているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"契約としては別々だということですけれども、例えば特養ホームをつくるときは、実際の指定管理者予定者としてこういう契約というか図面を引く段階から実際の運営がしやすいことも見通していろいろ調整・連絡をしていると思うんですよね。特に、安全対策ですよね。事故はあってはならないと思いますので、そこを伺いたいんです。","respondent":"立川経理課長、多並公園課長","answer":"すみません、ちょっと今訂正させていただきたいんですけれども、実際に工事が終わった時点で所管課のほうで十分な調整を実施するです。公園の管理とスポーツの観点、両方含めながら、今回設計する際もスポーツ振興の観点も含めて所管課とよく調整し、現在の設計の仕様に至っているものです。すみません、先ほどの私の発言なんですけれども、第６６号議案の内容を言ってしまいましたので、訂正いたします。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川ではありませんけれども、プールの事故の原因を見ると、やはり指定管理者制度であったり、品川では厳しくやっているということですけれども、再委託の問題だったり、やっぱり安全上これで担保できるのかということがこの間、少し前に議論になりましたので、まず現状がどういう、管理委託なのか、この工事の後はどういうふうになっていくのか、運営についてご説明いただきたいと思います。","respondent":"多並公園課長","answer":"今後についても、今はプロポーザルで平成２４年度に選定をされてありますので、このような経緯を踏まえて、今度新しいプールにつきましても管理を進めていくということを聞いているところです。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"それって、運営の安全性確保だけじゃなくて、やはり設計のときからだんだんまた劣化していくわけですから、排水溝の仕様というんですか、形といいますか、やっぱりあれは劣化したときに、できた当初はきちんとしていても、ネットがずれていたりとかそういうことがあるように聞きますので、その辺の設計上の点検といいますか、その辺がどうなっているのかちょっと伺いたい。","respondent":"多並公園課長","answer":"今回、そこにつきましては、新たにＦＲＰ製ということで、そういうメンテナンスをなるべくなくして、安全面に気をつけた形で今度の仕様については考えている。総合的にそういうような観点で、安全面については気をつけて設計しています。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"プールの施工というのは、普通に建物を建築する会社にとっては、これはよく施工をする経験というものはあるものなんでしょうか。実際に、それぞれの会社について調べたりということはされているのか教えてください。","respondent":"小林施設整備課長","answer":"委員おっしゃるとおり、建築が元請になりますけれども、その下に専門のプール業者が入ってきます。今回この工法を採用していますので、そちらのほうをできる業者を選定してまいります。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、実際に施工するのはここに出てきている会社ではなくて、プールの専門業者がプールをつくるということでいいですか。ごめんなさいね、ちょっとどこら辺まで分割してやっていくのかわからないんですけれども、だったらもうプールの専門業者につくってもらえばいいんじゃないかという発想も出てくるんですが、そこはやっぱりそれ以外のものとかいろいろなものがあるんでしょうか。","respondent":"小林施設整備課長","answer":"それとあと、こちらにも書いてありますが、あずまやというかテントだとか日よけ関係はまた別の業者、それとあと甲羅干し、プールサイド関係は塗装屋にまた違う業者が入ってきますので、そちらのほう全部の業種を総合的に管理するのがゼネコンでありまして。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"ありがとうございました。ということは、それを一般競争入札でやっているということは、どこのゼネコンがしても、この工事のある意味核となるプール事業者は同じところがやるというイメージなんでしょうかね。そういったことがある程度、何と言ったらいいんですかね、何をやるかが決まってから工事しなくても大丈夫なんでしょうか。その辺の経過を見るといかがでしょうか。あわせて教えてください。","respondent":"小林施設整備課長、多並公園課長","answer":"１点目のご質問なんですが、これはプール業者はいろいろいますので、それは心配ないと思います。今後につきましては、もう少しファミリー向けというのもありましたけれども、あと水族館がある公園ということもありますので、もう少しそこら辺のシーズンオフの利用ができないかということで。","id":"exchange-007"},{"speaker":"本多委員","kind":"確認","question":"より良いものができることを願います。１点だけ確認なんですけれども、支出科目で土木費、都市計画費、公園新設改良費、工事請負費ということなので、大規模な電気工事はないとは思うんですが、例えば既存の照明がありましたけれども、あれなんかはもうそのまま既存のものを使うのか。電気工事についてはどういうふうなお考えなのか、それだけ１点だけ確認させてください。","respondent":"多並公園課長","answer":"照明については、今もナイターで夜でも使える形になっていますので、あれも当初からできているもので、非常に見た目は何となく新しそうに見えるんですけれども、実はかなり劣化しているところもありますので、今回取替えで工事に入ることになります。","id":"exchange-008"},{"speaker":"あくつ副委員長","kind":"確認","question":"１点だけ確認をさせてください。工期が来年の３月３１日ということになっていますけれども、工事の日程、今回これが決まったとして、先ほどオフシーズンが１０月から５月だという話がありましたけれども、今年の夏はこれは使えないということだと思うんですが、今後の工期はどのような形になっているのか教えていただければと思います。","respondent":"多並公園課長","answer":"その夏が終わった後のオフシーズンということで、今そこで何かできないかということで、最終的な調整を今やっているところです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"安全面については十分注意を払っていただきたいという意見を申し上げて、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"第６６号議案、東品川公園土壌改良工事請負契約","agenda":"第６６号議案、東品川公園土壌改良工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません、こういう工事のことが全然わからないのですけれども、汚染された土壌をまず掘り起こして、それを処理するというところまでがこの契約に入っているのでしょうか。","respondent":"立川経理課長","answer":"空いたところには良質の土を持ってくるという、そういった一連の流れがこの工事の内容となっております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"汚染物質の除去とそのまた戻ってくる一連のものがこの工事に含まれているということですけれども、公園利用者やまた周辺の方々への説明会や、またこの案内は今後どんなふうに進められていくのか、ここを伺いたいのと、あと、資料には鉛と水銀での汚染とありますけれども、実際見つかった汚染物質の種類は何だったのか、一通りというか発見された物質を説明していただきたいと思います。","respondent":"多並公園課長","answer":"説明会の件ですが、今年の３月に一度説明会を開いてあります。地元の方にはこのような汚染があったということで、今後の詳細が決まり次第、要するにこの議決後、工事の契約が決まり次第またご説明しますということでお話ししています。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"この議決をされたのちには７月に説明会を行うということですけれども、周辺の方からご意見として伺うのは、特に子どもたちが一体この公園はいつから使えるのかと非常に思っているという話をよく伺うんですよね。工事の種類が違うからあれなんでしょうけれども、そういう意味では、経過についても丁寧に説明をすることが大切かなと思いますけれども、あわせて伺いたいと思います。","respondent":"多並公園課長","answer":"これについても、今回の工事を進めながら、弓道場のほうはどちらかというと汚染されたところが少なかったこともありますので、連携しながら、より早期に完成できるような形で進めていきたいと考えているところです。","id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"土壌汚染の場外処分ということなんですけれども、場内処分は検討されなかったのかお聞きします。２,１１５m3がダンプ何台分ぐらいになるのか。その辺、場内処分と場外処分の検討がどうだったのかをお聞かせください。","respondent":"多並公園課長","answer":"特に、搬入・搬出する際も、要するに土を引っ張ってトラックが出ていくと外に汚染されたものが出ていってしまう可能性もありますので、そこら辺もちゃんと水を払って丁寧に除去しながらやるということで、そういうのも含めながら対応したいと、そういった考えです。","id":"exchange-014"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"建設委員会で昨年度かなり何度もこの問題は報告もありまして、質疑もさせていただきました。今回随意契約ということになっていまして、ほかのが入札になっているんですが、先ほど課長のほうから工法をできるだけ早くというようなお話があったんですが、そういう関係で随意契約なのかなと思うんですけれども、何で随意契約になったのかというところの経緯を教えてください。","respondent":"立川経理課長","answer":"契約の相手方が現在改良工事を請け負っている業者です。改修の本工事の工期というのが来年の３月３１日までであります。これに間に合わせるということが第１の理由です。","id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"質問","question":"考え方としてはいいのかなと思うんですけれども、その以前に、発覚する前に契約をされていた弓道場、テニス場、ばらばらかどうかわかりませんけれども、土壌のこと、あとは電気設備、さまざまな業者が契約をされていたと思うんですけれども、実質１年以上待たされて契約解除になったところがあるのかどうか。補償とかそういうのはどうなっているのか、そこら辺について教えてください。","respondent":"小林施設整備課長","answer":"東品川公園の弓道場のほうの工事で、建築・電気・機械、３つの業者の契約がありましたけれども、途中で土壌汚染が発覚したということで、機械業者が契約の取り消しを行っております。","id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"質問","question":"契約を取り消された業者がいらっしゃるということですけれども、それは何か補償というか、そういうのは最初の契約のときに入っているということ、何か補償をするということになるんでしょうか。","respondent":"小林施設整備課長","answer":"補償というものではなくて、今まで使った分を出来高関係を整理をしまして、業者と話し合いを持ちまして、そこの時点で決めました。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"意見","question":"わかりました。今のご答弁で特に不利益を被ってはいないのかなとは思います。私も説明会に出させていただきましたけれども、そのようなご意見もありましたので、丁寧な説明を、今までのところは、皆さん割と納得されていらっしゃると思うんですが、引き続き丁寧な説明をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"先ほどから並行して工事ということで伺って、まさにいろいろ大変でしょうけれども、並行して工事をされるのだと思うんですが、公園の完成というか竣工も３月３１日で、これも３月３１日。","respondent":"多並公園課長","answer":"次に公園の工事に移っていくのが基本的かと思いますけれども、なぜ３月までになっているかと申しますと、一部最後復旧等、要するにテニスコートなどもともとの予定に入っていなかった、工事では手を入れる予定はなかったところから出てきていたり。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問・要望","question":"１点だけ、これはちょっと要望に近いんですけれども、先ほどご説明をいただいた現地のところで、公園の工事を知らせる看板がまだ平成２７年３月までという表記が残っていて、ほかに延長しますというちょっと小さい看板も出ていたんですけれども、あれはやっぱり大きい文字のほうを皆さん読まれると思うので、これからこれが終わったら説明会もあるということですから。","respondent":"多並公園課長","answer":"委員の今のご指摘のとおり、よりよく区民の方にわかりやすい周知に努めてまいります。今回、修正します。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"随意契約なんですけれども、専門的な技術が必要とされる土壌改良ですけれども、共同企業体というのをとっていて、日比谷・大森建設共同という。主に土壌改良をやるノウハウ、技術を持っている日比谷アメニスがやる、それとも両方が両方で技術をしっかりと持っているのか。そこのところを教えていただきたい。","respondent":"多並公園課長","answer":"そういう対策工事を含めて、全体的に都との調整が出てきますので、ここは今言いました下請業者をもちろんアドバイスしながら、工事については実際にはそこの業者ができるわけではございませんので、ここの造園業者がトラックに積んだり、ここのノウハウを持ちながら工事を行って。","id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"今、造園業者という、この日比谷アメニスというのは造園業者なんですか。","respondent":"多並公園課長","answer":"日比谷アメニスおよび大森建設は造園業者です。ここの東品川公園をもともと管理している業者自体が、この日比谷アメニスという会社です。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"必要な工事だと思いますけれども、経過を見るといろいろ工期がずれてきておりますので、説明会等丁寧に行っていただきたいと、意見をつけての賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"第５６号議案、品川区特別区税条例の一部を改正する条例","agenda":"第５６号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"品川区はその点どう思っているのかということと、今後検討していきたいというのはどんな中身を、方法を考えているのか、そこもあわせて伺いたいと思います。紙たばこまでお聞きしますけれども、紙たばこのほうですけれども、今までなぜ税率に差をつけてきたのか、それをなぜ今回段階的に引き上げるのか、その理由を伺いたいと思います。","respondent":"黒田税務課長","answer":"ただ、急激に上げますと、たばこの販売事業者等に影響が大きいということもありますので、４段階で引上げを行うというものだと認識をしているものです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"確認","question":"あわせて聞いてしまいますけれども、住宅ローンの延長ということですけれども、延長したほうがいいとはもちろん思いますけれども、延長をする理由は、法律が変わったからではなくて、区として主体的にどう判断されたのかそこを伺いたいのと、あと５つ目の減免に係る申請期限の見直しということですけれども、具体的にどういう方が対象になって、どういう手間が省略されるのか。","respondent":"黒田税務課長","answer":"たばこ税の税収への影響ですが、旧３級品のたばこの販売本数については、今区のほうで全体のたばこの中の２.６％の販売本数という、２.６％の割合ですので、ここで税率が変わって旧３級品の販売本数が減った分、例えば一般品のたばこを買われるのか。","id":"exchange-025"},{"speaker":"あべ委員","kind":"確認","question":"すみません、確認なんですけれども、この５本というのは、それぞれ国の制度に合わせて区のほうでも関連条例の一部改正を行うという理解でよろしいんでしょうか。それをちょっと教えてください。","respondent":"黒田税務課長","answer":"ただ、ぎりぎりのご相談につきましては、特に障害者減免ということについては、手帳を持っているということが確認できれば減免対象ですので、そこは事務上で対応しているというものです。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問","question":"５番の減免の期限なんですけれども、ここでは区民税、軽自動車税、身体障害者等に対する軽自動車税とありますけれども、ほかの税金、あるいはその他の区に対する払い込みが必要なものなどについて、この期限と申請期限がずれているものはほかにもあるんでしょうか。ちょっと税の話だけじゃなくなってしまうと、もしわからなければ税の関係だけで結構です。","respondent":"黒田税務課長","answer":"基本的に、納期限を過ぎますと延滞金が発生するということですので、納期限までにお納めいただくというのが税の大原則の中で、従前ですとそういった事務手続も含めて７日前までというのがそもそもの考え方だったんですが、規定されたときと、いわゆるコンピューター処理等々。","id":"exchange-027"},{"speaker":"大沢委員","kind":"質問・要望","question":"ふるさと納税ワンストップ特例ということで、先ほど課長から減収幅が増加をするということで、これは公布の日からということですけれども、減収幅の増加についてどのように見積もりをされているのかということと、もう一つ、区がふるさと納税を奨励をしていくということ、この条例改正になって、減収幅を予想されるということであれば、それなりの。","respondent":"黒田税務課長","answer":"ただ、今回、ワンストップ特例ができたということと、税額控除の上限額が住民税の所得割の１割から２割に２倍になったということで、さらに現行制度でも件数は拡大していると認識しておりまして、そもそも手続の簡素化と上限額が上がるということでさらに寄附額。","id":"exchange-028"},{"speaker":"大沢委員","kind":"意見","question":"今、マックスでということで、理論上ということで、往々にしてこういうものというのは理論が現実になってしまうことがありますから、ならないようにするために、いろいろな奨励策ということなんでしょうけれども、奨励策がちょっとむやむやとよくわからなかったんですけれども、具体的な案というのはお持ちじゃなくて、いろいろな今後の推移を見ながら奨励策をとっていかれるということでいいんですね。","respondent":"黒田税務課長","answer":"奨励策と申しますか、先ほどの繰り返しになりますが、なかなか出ていく額に見合う収入というのは難しいところがありますので、品川区から転出された方ですとか、かつて品川区に住んでいらっしゃった方等々に何かアプローチできないかというところで。","id":"exchange-029"},{"speaker":"大沢委員","kind":"意見","question":"減収をするということは、ただ制度上そうだから減収をしてしまうというのはしょうがないということで片づけるやにちょっと聞こえる部分があるんですけれども、そこのところどういうふうにお考えになりますか。","respondent":"黒田税務課長","answer":"ただ、繰り返しになりますが、出ていく分に見合う収入をそれだけ補填するというのはなかなか難しいことであろうというところでありますが、その中でも何か品川区をぜひこれからも応援していただく。","id":"exchange-030"},{"speaker":"大沢委員","kind":"質問・要望","question":"では税収確保に向けてしっかりといろいろな策を講じていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、５つの改正ということですけれども、１、２、４、５については、改正の内容そのものは手続きだったり、政策的に必要な対応だったりはしますけれども、ふるさと納税については、やはり私はギフト化している、これはやっぱり問題だと思いますので、区の対応等は返礼品も検討するというふうにありましたけれども、よく検討していただきたいと思います。全体の評価としては、賛成で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"吉田委員","kind":"意見","question":"やっぱり何か予算を考えるときにはある程度見込みというのを立てて、じゃあそれに対する補填はどうやってまた見込むのかということを考えて立てるべきなんじゃないかなと思いましたので、その辺のことはしっかり考えていただくことを前提として、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-04","title":"第６４号議案、本庁舎屋上防水改修その他工事請負契約","agenda":"第６４号議案、本庁舎屋上防水改修その他工事請負契約","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"それで、今も屋上が緑化という形でいろいろタイルを敷いたり、いろいろな工作物がありますけれども、もしあれが普通の屋上のように何もなくてただ防水処理をしてあるだけのものを防水工事するだけであれば、あの面積だとどのくらいのものなのでしょうか。いろいろな撤去工事などが全くなくて、ただ防水だけをするとすると幾らくらいになるんでしょうか。ざっくりでいいので、教えてください。","respondent":"立川経理課長","answer":"前回の工事というのを平成３年度に実施いたしまして、今回２０年以上が経過しているというものです。実際の防水保証期間というのは、通常１０年間ということになっております。それから防水部分だけの金額につきましては、手持ちがございませんので、割愛します。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"ああいう形で一般の方々にも使っていただけるようにいろいろ工夫をされているわけですけれども、年間の一般の方々、職員の方々がお昼休みにごはんを食べているというのはそれはそれで使われ方として悪くないと思うんですけれども、一般の方々の利用人数は年間を通してどのくらいなんでしょうか。","respondent":"立川経理課長","answer":"実際に屋上を訪問されている方々の人数の把握が正確にはできていないところです。ただ、職員対一般の方の利用比率というのは、大体一般の方は１割以下ということで把握しているところです。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"それで大勢の方に利用されていれば、それはそれで私は大いに結構だと思うのですが、人数が多い少ない以前に把握もされていないという状態の中で、また２億円かけていいのかなという気もちょっとしているんです。その辺は区としてはどのようにお考えなんでしょうか。つくることが目的ではなくて、利用されて初めてお金をかける理由があると思うんですけれども、そこら辺の検討はなされたんでしょうか。","respondent":"立川経理課長","answer":"それで今回、防水工事といっしょにやるということで、やはり防水性能というのがある一定年限に限られておりますので、今回の工事につきましては屋上緑化部分についてと通常の防水工事という部分について。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"何に対して影響が出ないということですか。詳しく教えてください。ちょっと言葉がきつくて申し訳ないんですけれども、やっぱりただの防水ではないだけの工事をしたのであれば、それに対する評価は当然計ろうという流れがあってこの２０年間然るべきだったと思うんですが、何もしてこなかったということなんですか、人数がわからないということは。","respondent":"立川経理課長","answer":"実は、屋上緑化に関しましては平成１４年から実施しまして、もともとあちらの屋上についてはネットとかを張っておりまして、軽いキャッチボールができるような、こういった環境でございまして、後づけの工事として緑化をしたということがあります。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"そのことを考えると、ホームページに載せるとかそういうことではなくて、庁舎に来た方にビジュアル的にわかるように、上ってからこういうのがありますとわかるのではなくて、最初の入り口に入ったときから、ここは屋上があってこんなに素敵なところなのねとわかるのが一番のＰＲだと思いますので、そういったことも含めてこの２億５,０００万円をきちんと元が取れるといいますか。","respondent":"立川経理課長","answer":"最後にご指摘いただきましたとおり、積極的なＰＲに努めてまいりたいと思います。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"私もちょっと最初に単純な質問をしたいんですけれども、今、改修が予定されているということで先ほど見せていただいたあの状況なんでしょうか。それとも、普段からああいう状況なんでしょうか。ちょっと教えてください。","respondent":"立川経理課長","answer":"普段は、いわゆる職員のボランティアによって現在屋上については維持管理をしていますので、今日の姿というのは経年的にああなってきたということです。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"やっぱり土のないところに土を盛り、水のないところに水をやって緑を豊かにしておくというのには、結構なメンテナンスの技術とか費用とかがかかると思うんですが、この契約とかその後のことについてはまだ何も考えられていなくて、とりあえずこの改修とその他工事ということだけなんでしょうか。この後どういうふうに状況を維持するというか、考えていらっしゃるのか教えてください。","respondent":"立川経理課長","answer":"維持管理についてどうするのかですけれども、現在関係所管とも相談しながら、維持管理の方法については検討しています。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"資料そのものは結構古かったなと思いましたけれども。そういう意味で、今回の工事の中で防水だったり、その後上に緑化をすること、それぞれの技術的な改良点というのは何かあるのでしょうか。","respondent":"立川経理課長、小林施設整備課長","answer":"防水の部分に関しましては、これまでのウレタン塗膜防水というものを施工する予定でございまして、こちらはいわゆる液体状のウレタン樹脂を塗布した材料なんですね。通常でいきますとやり替えは、撤去して、その部分を処分してから防水をやるというのがありますけれども、今回のウレタン塗膜防水を使用したのは、そういう既存を活かしながら。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、今回の工事を機にいろいろな改善や工夫や、また改良がされたところは、ぜひまたこの屋上庭園がオープンしたときに普及のためのＰＲにつなげていくと、協力や普及を広げていくと、そういうことが大切ではないかなと思うんですけれども、ＰＲや普及を今後どのようにお考えなのかを伺いたいと思います。","respondent":"立川経理課長","answer":"緑化と防水という観点で、どのようにＰＲが可能かということについては、今後検討していきたいという考えております。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"必要な工事ですので賛成しますが、ぜひその屋上防水やまた屋上緑化のＰＲや普及は今後強めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"防水工事そのものは必要な工事だと考えています。それ以上の部分については、きちんと効果が得られるようにしていただきたいと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問・要望","question":"一言だけ。本当に眼下にはしながわ中央公園という立派な公園があって、この屋上もこのようにきちっと改修していくんでしょうが、やはり先ほどほかの委員も述べたように、やっぱり人数の把握をして、利用されている人がどれぐらいいるのか、それから改修工事もしやすいようなそういう工夫を、やはり今後私は要望しておきたいと思います。今回の件に関しては、屋上防水改修ということで、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"ネットは防水工事については賛成です。要望ですが、健康器具のことについては、皆さんほかもおっしゃっていますが、これからどんな人が来るかによって、その方たちが使うものでないとあまり意味がないような気がしますので、もし後から設置できるということであれば、何かそういうニーズの把握とかをしてからでも遅くはないんじゃないかなということを、意見として要望としてつけ加えて、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味では、この２つの請願に私は全ての委員に賛成していただきたいとまず思いますけれども、いずれの請願の紹介議員になっていない会派で言えば、自民党や公明党や、それぞれ請願についてどのようにお考えなのか、ぜひお考えをお聞かせいただいて、議論を深めることが、総務委員会に付託された意味なのかなと思いますので、初めにご意見を伺えたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"本多委員","kind":"質問","question":"ただいまのご意見に対しまして意見を述べたいと思います。この法案につきましては、やはり重要な法案ですから、国民の誰もがやはり関心を持つことは大事なことだと思います。この法案につきましては、現在衆議院でやっていることですから、国民から付託を受けた国会議員が審議をしているんですから、今まさにやっているところですから、それを注視する必要があると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"今回は慎重審議を求める意見書の提出を求めるということと、集団的自衛権行使容認の閣議決定を撤回することを求める、またその法制化に反対する意見書を提出することを求める２つの内容で出ておりますけれども、先ほどほかの委員からもありましたけれども、現にいま国会において慎重審議が尽くされているところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問・要望","question":"しかし、この安全保障に関するものというのは、非常に特にこの６月４日以降ですか、国民の皆さんの、あるいは区民の皆さんの関心が非常に強くなっていること、それから、先ほどまだ審議中だからということもございましたけれども、特に慎重審議を求める意見書に関しては、まさに審議の仕方であるので、審議が終わってから慎重審議を求める意見書というのは出せないわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、今まで憲法９条に関しては集団的自衛権を、政権を持っていた自民党も反対されていたのが急遽変わってしまった。ですから、今回のような、こういう請願に関しては、私は国、国民もそうですが、その中にいる都民、区民の命にかかわることがあるんですから、慎重に審議して、事を進めるように国に求めることは私は何も間違っていることではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"憲法に関しては、ちゃんと憲法の中にそれを改正するときには国民の投票が必要という、また別の権利がきちんと設けられているにもかかわらず、それが侵害されようとしているということについては、私たち品川区議会も区民の皆さんから付託を受けた議員なわけですから、より身近な付託を受けたというところでは、品川区議会としての意見書提出というのはまさに必要なときじゃないかなと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"大沢委員","kind":"質問","question":"ゆえに、やはり私たちは信託を受けた国のあり方、外交、防衛、経済をつかさどる国で審議をされるのが然るべきであって、その国も延長の国会を開いて今後十分に審議を尽くすと言っているわけですから、先ほど私どもの別の委員が言ったように、これはまさに国のほうで論じてもらうわけであって、私たちはそこのところで国の議員との普段の交流の中でそこの意思疎通をしているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"私も率直に言って、やっぱり今の意見が出るとかっと来ちゃうときもあるんだけれども、そこはやっぱり議論ですから、事実と道理に則っていい議論ができたらなと、そういう思いで少し議論したいと思います。それだけに、ぜひこの場でも活発な議論ができることが必要ではないのかなと思いますので、その辺ちょっと伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"一通り意見が出て、ここから議論が始まるところだと思いますので、まだ採決をする前に、もちろん委員会運営はわかりますけれども、議論を踏まえて尽くされたら採決をすると。ここから議論だと思いますので、先ほど端的に伺ったんですけれども、ぜひ少し議論するべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"あべ委員","kind":"質問・要望","question":"皆さんのご意見を伺った上で私の感じたことも申し上げたいと思います。国で議論しているというのはわかります。あくまでも議論の場は国です。これはわかっております。これは私どもの考え方です。そういった意味では、今この中で区民の方々から慎重審議を求める意見書というのが出てきたときに、これはぜひ品川区議会としても国会に出していけたらいいなと、私たちの会派の中では考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"本多委員","kind":"質問","question":"そのことについて、この請願につきましては慎重審議を出してくださいということですから、先ほど述べたように、今慎重審議をやっているところで、国民が選挙で選んだ、国民主権ですよね、国会議員が審議をしているんですから、それを注視するべきだと言っているんです。この請願については意見書を出してくださいということですから、出す必要はないという意見です。よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"今回は、集団的自衛権ですから、海外での武力行使なわけですよね。国際法上は武力行使をするためには兵たん活動がなければ、補給部隊がなければできませんし、自衛隊の方にお話を伺っても、自衛隊の訓練の中でも物資を運んだり燃料を送ったり、また兵士をヘリコプターで送ったり、そういう補給部隊が必要だし、危険が伴うからそれを想定して訓練をしているんだと。安全な戦地など私はないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"須貝委員","kind":"質問","question":"だけれども、多くの方が疑問に思って心配しているんですから、慎重審議の上に進めてくださいと。それで、ちゃんとした法に則って物事が進んでいったなら、それは仕方がないかもしれないですけれども、やっぱり何か間違っているんじゃないですかということを多くの国民の方が疑問に思っているなら、私はこの意見書を出して何も問題がないんじゃないかなと思うんですが、どうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"その慎重審議をちゃんと尽くしてもらいたい、それを注視しているよということを表明するためにも、この慎重審議を尽くしてほしいという意見書というのを出すことは、何も注視すべきというご意見と矛盾しないんじゃないかなと思います。ぜひやっぱり品川区民もこれだけ注視しているよということを表明するためにも、慎重審議を求める意見書の提出はしたらいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ誤解のないようにお願いしたいんですけれども、例えばこれをもって自民党が戦争をしたがっているとか平和を求めていないとかそんなことを言うつもりは一切ありません。戦争というのは国民にとって最大の不幸ですし、国民にとって最大の不幸というのは国にとって最大の不幸ですから、責任ある政党がよもやそんな平和を求めていないということを前提に話しているわけではありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"やっぱり慎重審議を求める背景には、聞けば聞くほど危ういというか、きな臭いというか、そういう不安がやっぱり広がっているという今の世論の表われなのかなと思います。一つの物差しとして、この間の、いわゆる賛成・反対、また今国会では成立させるべきでない、いろいろな世論調査を見ても、急速にこの１週間、２週間で増えている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"中塚委員","kind":"意見","question":"最終的には少し議論できたことは本当に委員長のおかげですけれども、今後もそういう総務委員会になりたいなと思います。その上で、第１３号も第１７号も今日結論を出すということと、両方とも採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"第１３号についてですが、本日結論を出したいと思います。第１７号のほうなんですが、第１７号については、これも結論としては本日出すということで、内容的には、何といいましょうか、表現的に私どもが考えるところよりもちょっときついなといいますか、これは違うなという部分が幾つかあるものですから、第１７号については不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"須貝委員","kind":"意見","question":"私は、結論を出すということで、本日両方ともです。第１３号に関しては、採択としてください。それから、第１７号に関しては、文面がちょっときついんですね。ちょっと私もうん、というところはあるんですが、そういう不安なお気持ちがここまで言葉として出てしまったのかなと思っているわけで、理解を十分できるので、今回これに対しても採択ということにしてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"}]},{"id":"topic-05","title":"平成２６年度品川区一般会計予算繰越明許費繰越計算書","agenda":"平成２６年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"ちょっと私の理解を深めたいということで、正直この繰越明細を私はよくわかっていないんですね。端的に言うと、繰り越すものと繰り越さないものというのがどう違うのかがわからなくて。ごめんなさいね、勉強不足で、正直わからないんですけれども。ちょっと、今ご説明の中で触れられて今は十分差はわかっているんですけれども、それでもわからなかったんで、ちょっとご説明していただけますか。","respondent":"秋山財政課長","answer":"繰越明許ですけれども、地方自治法に書かれたうちに予算成立後の事由に基づいて、その年度内に支出が終わらない見込みのあるものについては、支出の見込みのないものについては、予算の定めるところにより翌年度に繰り越して使用することができるというのが規定です。","id":"exchange-066"},{"speaker":"中塚委員","kind":"意見","question":"ということは、補正予算と繰越明細書というのは、どう違って、またどう重なる部分があるのか。どう違うのか、そういう角度でご説明いただけますか。","respondent":"秋山財政課長","answer":"地方自治法の施行令の第１４６条第２項というところに繰越明許に関する手続きのことが書かれているんですが、ここには繰越明許費に係る歳出予算の経費を翌年度に繰り越したときは、５月３１日までに繰越計算書を調製し議会に報告しなくてはならないという規定がありますので。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332522?Template=document&Id=2018#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":46912,"voices":176}},{"id":"h27-20150630-6","meetingId":"h27-cm06","date":"2015年6月30日","dateIso":"2015-06-30","committee":"区民委員会","time":"午前１０時００分～午前１１時５６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"区立総合区民会館の指定管理者候補者の公募","agenda":"区立総合区民会館の指定管理者候補者の公募","exchanges":[{"speaker":"南委員","kind":"質問","question":"一つは、選定委員会の委員の構成は、どういうメンバーなのかを伺いたいと思います。そのあたりを教えてください。","respondent":"間部文化観光課長","answer":"委員の皆様も既にご承知だと思いますけれども、公的分野の民間開放ということで、民間事業者により、よりきめ細やかなサービス、柔軟な対応をしていただけるということと、行政においては経費の縮減ということで行ってまいりました。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"その辺が全然つかめていないので、いいところはもちろんいいということで、つかむ必要はないと私は思っているので聞かないですけれど、もし改善を求める必要があるみたいな、そういうご意見が利用者の区民の中から出ていればどんな内容であるのか、どういうふうに改善しようとしているのか、そのあたりを、それこそ透明性という点でつまびらかにしていただきたいと思って、質問したいと思います。","respondent":"間部文化観光課長","answer":"きゅりあんにおけるクレームですけれども、私も４月に着任しまして３カ月ほどたっていますけれども、今のところ私まで上がってくるクレームというのはほとんどございません。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それで一般論というか、品川全体の指定管理者制度のことを、私も事前にしっかり調査しないで臨んでしまったのですが、品川区の指定管理者制度ということに対する捉え方という点では、法令遵守はもちろんですけれども、なかなか働いている職員の方々、正規ならともかくそうでない雇用の方たちに対する処遇というのが、なかなか私たちとしては目に見えないところなので、その辺について。","respondent":"間部文化観光課長","answer":"今回の応募につきましても、詳細な募集要項でも関係法令の遵守ということで、特に地方自治法初め労働関係法については遵守をしてほしいということで、その中には労働基準法や債権賃金法や労働安全衛生法ですね。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"今日はちょっと不十分な準備のまま臨んでしまったので申し訳なかったのですけれど、次回また、いろいろな機会があったらそういうことで質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"メンバーについては先ほど伺ったのですけれど、そのメンバーには外部の人が入って審議を公開するということを、ずっと品川・生活者ネットワークとして求めてきているのですが、それは検討はされていますか。","respondent":"間部文化観光課長","answer":"選定委員会の件ですけれども、メンバーについては先ほどお答えした庁内のメンバーで構成されています。今回につきましては、基本的に初めての公募ですので、外部からの登用等につきましては今後の課題だと考えています。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"このきゅりあんに関しては初めて公募ということで、指定管理者の導入に当たって、公募という方法をとるという面では評価したいと思います。ただ、公募に当たって期間が１週間ですよね。せっかく公募したはいいけれど、結局来たのは文化振興事業団だけだったと、それはそれでいいかもしれないけれど、せっかくの趣旨が期待できないのではないかというところについて、考え方を教えてください。","respondent":"間部文化観光課長","answer":"この考え方としましては、当然、文化観光課の窓口に来た場合については、募集要項一式をお渡しして、ご説明いたします。明日から１週間、ちょうどホームページにも載りまして、そこから申請書類についてはダウンロードが可能になってあります。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"提案","question":"この期間のところで、先ほど来これまでの経緯で、例えば文化振興ビジョンができたときにそれが一つの案件であると。この中で選定基準のところですが、ここは基本的なことでいいと思うんですが、最初のプロポーザルの提案だけではなく、今後のやりとりの中で、区としてどんなオーダーを出していくのかという視点というのは、どんなふうに加味されるのかというのを、現時点で聞ければと思います。","respondent":"間部文化観光課長","answer":"確かに稼働率は９０％を超えておりますけれど、９５％、１００％を目指してさらなる稼働率アップ、そういう点について少し具体的に聞いてみたいと考えております。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"今回から指定管理者の公募という形なんですけれども、改めてお伺いしたいのですけれども、公募するわけですから、まだどこが指定管理者になるというのは決まってないのですよね。","respondent":"間部文化観光課長","answer":"これから、明日から公募に入りますので、これから審査が始まりますので、現時点では指定予定候補者については決定してございません。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"この４番の理由の中で「より透明性、公平性を重視し」となっていますので、なぜそういうふうに改めて聞いたかというと、そこを重視してほしいという思いもある一方、私はこの今までの方式もよかったのかなという思いがすごくあるから、こういう質問をしているのです。それで伺いたいのですが、この財団法人品川文化振興事業団というのは、いわゆる品川区のＯＢは行かれているのでしょうか。","respondent":"間部文化観光課長","answer":"透明性、公平性を重視ということで補足説明になりますけれども、言ってみれば特命随契でやってきたということでありまして、随意契約が続いたという形になっておりました。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"それで多分委員会のほうからは質問が、なぜ、公募にエントリーしたところがあればですけれども、なぜこういう結果になったのですかというのは、私も必ず質問しますし、そのときに、これから始まるわけですが、ちゃんとした答弁ができるように透明性、公平性をもってちゃんと審査してくださることを、心より願っております。この点、いかがでしょうか。","respondent":"間部文化観光課長","answer":"当然、今、委員ご指摘がありましたように、私たち初めての公募ということもありますけれども、選定理由については、第４回定例会で指定議決をお願いする際にはきちんと説明できるように、対応してまいりたいと思います。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"さっき質問すればよかったのですが、すみません。先ほど、いわゆる区のＯＢが４人とおっしゃったのですけれども、あえてどこの職にいるかということをちょっと教えていただきたいと思います。","respondent":"間部文化観光課長","answer":"ＯＢにつきましては、現在、理事長と常務理事、管理課長、文化振興課長と４名になっております。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"もう一人出向されている課長がいらっしゃいますよね。それはそういう関係の中で、応援部隊といいますか、そういうふうになっているのかなと理解するのですけれど。それは一般論です。したがって、今いろいろな社会情勢の中で、いわゆるそういう職を品川区が提供するということについての認識、それはどうなのかなというのを改めて、いつか伺っておきたいと思っていたものですから、伺いたいと思います。","respondent":"間部文化観光課長","answer":"文化振興事業団全般的なお尋ねだと捉えましたけれども、文化振興事業団につきましては特に公益財団法人になったときの定款に書いてあるのは、「品川区における文化芸術、生涯学習の振興を図り、活力とにぎわいのある魅力的なまちづくりに供することを目的に設立」ということで。","id":"exchange-012"}]},{"id":"topic-02","title":"区立体育館の指定管理者候補者の公募","agenda":"区立体育館の指定管理者候補者の公募","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"同じことですけれども、選定委員の構成メンバーをまず伺いたいと思います。は先ほどと同じことだと思いますけれど、体育館について品川区から出向している人数と、いわゆる品川区を退職されたＯＢの方々がどういう職についているのか、それを教えていただきたい思います。","respondent":"池田スポーツ推進課長","answer":"もう一つ、今、品川区スポーツ協会のほうに出向している者ですけれども、まず事務局次長に１人、事務局職員として主査が１人、ＯＢとしまして事務局長が１人です。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"品川区の組織の中で、私、今日組織図を持ってこなかったのですけれど、商業・ものづくり課は地域振興部として入っているということで、こういう職の課長の皆さんが選定委員をやるのだろうと理解するのですけれども、文化スポーツというところと商業・ものづくり、ここが何となくぴったりしないというか、そういう感じがするのですが。","respondent":"池田スポーツ推進課長","answer":"委員の構成につきましては、私どものところで、まず平成２２年に品川区立体育館指定管理者候補者選定委員会設置要綱というものができまして、その際に、現在でいうところの文化スポーツ振興部長、スポーツ推進課長、文化観光課長、商業・ものづくり課長。","id":"exchange-014"}]},{"id":"topic-03","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"石田（し）委員長","kind":"質問・要望","question":"次に(3)、その他です。では、私から１件。昨日の委員会におきまして、視察日程について２名の委員から、１泊でもいいのではないかというようなご意見をいただきまして、その後正副で話をし、ほかの委員からもぜひこの件について、ご意見を頂戴できればという運びになりました。よって、この場でほかの委員からも、視察日程についてご意見がありましたら、ご発言いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"渡辺委員","kind":"意見","question":"具体的な視察先等は例年どおりを想定しながら、我が会派で６日の締め切りに合わせて、希望先は出そうと思っています。やはり委員会で視察は、昨日も発言があったので重複しますが、意義はあると。方法論のところでまず宿泊日数。これ、案外、私たちの会派の中でも、結構なボリューム、候補先が出てくるのですね。そして２泊３日が適切ではないかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"意見","question":"現に私、前々回の、２年前は厚生委員会だったのですが、松澤委員長のもと行ってきて、大分市のほうだったのですけれど、そこで障害者のいろいろつくったりしたものを展示するというのが、品川区はそれが一部になっていて、なかなか区役所の中で、障害者が一生懸命つくったものを一般の方が見てくれるというケースがなかったのを、その大分市のほうは、ど真ん中でやっている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"南委員","kind":"提案","question":"いろいろな意見があっていいと思うのですけれども、まず日程があってというふうな決め方でなくて、この委員会としては昨日提案されたような２つの項目で所管事務でやろうと。かといって、じゃあ今、これがありますよとか、こういうのを見たいですという提案できるようなものはないのですけれども、日程を先に決めてというのは、何か非常に違和感を感じるのですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"松永委員","kind":"意見","question":"まだ視察は一回も行ったことはありませんが、やはりそうした中で、金沢市とかいろいろありましたけれども、見てみたいところ、現地に行って視察したいところというのは多くありますので、その中での２泊３日という、先ほど南委員からもありましたけれども、先に数字を出すというのはもしかしたら違和感があるかもしれないけれども、やはり２泊３日というのはちょうどいい期間だと、私は思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"田中委員","kind":"意見","question":"私も行ったことがないのであれですけれど、ただ先輩たちのお話を聞いていたとき、同じ財政状況のまちに行かないと、あまり意味はなかったという話も聞きました。個人的なあれですけれど、２泊３日でも全然いいのですけれども、でも私、個人的に子どもを育てているので、２泊３日外泊するのはちょっと、というのがあります。そういう事情も。","respondent":"石田（し）委員長","answer":"視察先に関しては、７月６日までに皆さんから、ここがいいというものがあればいただければと思いますので、よろしくお願いいたします。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/719578?Template=document&Id=2726#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":15404,"voices":57}},{"id":"h27-20150630-7","meetingId":"h27-cm06","date":"2015年6月30日","dateIso":"2015-06-30","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)、平成２６年度介護保険制度の運営状況","agenda":"はじめに、(1)、平成２６年度介護保険制度の運営状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、１ページの、６５歳以上の高齢者の平成２７年４月の人数が７万８,０００人ということで、下のところの被保険者総数が７万９,０００人ということで、この数字の違いはどういうことかお聞かせ願いたいということ。それから、認定率ですね、全国の比率がわかったら教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"全国の平均の認定者率は１７.９％になっております。次に、３ページの各施設別のところです。こちらにつきましては、縦の数字が正しくなっております、申しわけありませんでした。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"３ページのところで、訪問介護、通所介護の予防のところがあると思うのですけれども、今回、ここのところが総合事業に移行される対象者ということで、よろしいでしょうか。","respondent":"永尾高齢者福祉課長","answer":"対象者予防給付のところが対象者になっておりますけれども、もうほとんど９９％以上移行されているのですけれども、区外の事業所を利用されている方はそのまま予防給付に残っております。それはただ、数字としては非常に少ない数字になっております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"意見","question":"特別養護老人ホームの２月締め切り時点の申し込み者の数を、わかれば介護度別にお知らせください。それから、今後、介護度３以上の方が入っていくと思うのですけれども、２月時点でもうそうなっているのかということも、お聞かせください。","respondent":"永尾高齢者福祉課長","answer":"介護度別の人数になりますけれども、要介護１が１２人、要介護２が３４人、要介護３が１７９人、要介護４が１７２人、要介護５が１０３人となっております。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"１０ページですけれども、徴収率のところで７８.６％ということで、ほかのところの方が徴収できているかと思うのですけれども、朝日新聞に介護給付のペナルティの記事がありまして、それで品川区が載っていたのですけれども、１年以上滞納している方は１,５００人いるけれども、２年以上滞納してペナルティになっている方はいないということだったのですけれども、そこら辺も。","respondent":"永尾高齢者福祉課長","answer":"そこで話をじっくり聞いて、まずは分納、少しでも払うというところから始め、それでも払えないということになってくれば、家族状況とか、そういうところも、ケアプラン等から全てわかりますので、そういうところも見ながら丁寧に対応しております。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"人数は月別しかわからないということだったのですけれども、もし全体で、平成２６年度の未徴収者の人数がわかれば教えていただきたい。後日で構いませんので、１年以上の方の人数も教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"やはり正確な数字にしたほうがいいですので、また後日、ご報告をします。","id":"exchange-005"},{"speaker":"のだて委員","kind":"確認","question":"ペナルティを受けている方はいないということだったのですけれども、これまで生活保護につなげていった方も何人かいるということでしょうか。その確認をお願いします。それから、ペナルティは出ていないというのは、取り立てを強くやってペナルティにならないようにしているということが懸念されるのですけれども、そういった徴収の仕方もお聞かせいただけたらと思います。","respondent":"永尾高齢者福祉課長","answer":"取り立てということではなくて、サービスを利用する段階になると、必ずご相談に来ますので、そのときに具体的に話を進めていくのですけれども、そのときに、一対一で話をするだけではなくて、区のほうで情報を持っていますので、その情報を使いながら。","id":"exchange-006"},{"speaker":"のだて委員","kind":"意見","question":"１１ページに移りまして、歳入のほうの繰越金というのが、どういったものになるのか、お聞かせ願いたい。計画上は、国が２５％、都が１２.５％、区が１２.５％で、保険者が５０％を１号、２号被保険者で負担しているということなのですけれども、その数が微妙に違うのですけれども、この理由もお聞かせ願いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"ですので、繰越金の金額は、毎年そんなに大きな差にはなっていない、清算行為をした結果、繰り越しになったというような内容になっております。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"今のご説明ですと、繰越金というのは、次年度に持ち越すお金ということでよろしいのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"次年度に繰り越すお金ということになっております。給付の額が２カ月遅れて来ますので、最終補正をご審議いただくときとのタイムラグがありますので、どうしても繰越金は出てくるものです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"意見","question":"歳出のほうに移らせていただきまして、地域支援事業のところが、今回、総合事業になると思うのですけれども、これによりどう変わるのか。具体的に、地域支援事業というのはどの事業になるのか、身近でトレーニングですとか、こういったところで何に当たるのか、ちょっとお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"今度、平成２７年度からは、通所と予防の訪問についても地域支援事業に移っていきます。地域支援事業につきましては、同じ介護保険の枠組みの中で行い、財源も介護保険料を使うのですけれども、各自治体の地域に合わせた独自性の中で決められるというところが違うところです。","id":"exchange-009"},{"speaker":"のだて委員","kind":"意見","question":"１１ページのところで、２割負担の方が８月から出ると思うのですけれども、その人数と、２割負担にしたことによって、増収が幾らくらいになるのかお知らせください。それから、最後のページの、品川区介護保険制度推進委員会、今年の日程がわかりましたら、お知らせください。","respondent":"永尾高齢者福祉課長","answer":"第六期の事業計画上の数字しか、今、出せないのですけれども、事業計画上でいきますと、４億２,７００万円くらいが引き下げられるかと見込んでいるところです。ただ、計画上の話なので、実際のところはまだわからないということです。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この市町村特別給付の中では、身近でリハビリだけなのか、そしてまた、なぜそれだけが地域支援事業のほうに行くという判断になったのか、そこのところを１点、教えていただきたい。それから、１２、１３ページのところの介護予防事業ですけれども、これは、１２ページ、１３ページ全て地域支援事業の介護財政でやっていたということなのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"一般財源の場合は、東京都の補助金２分の１を活用しながら実施しています。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私たちは、市町村特別給付というのは６５歳以上の人だけの保険料でやることなので、ここのところは一般財源でやるべきだとずっと主張してきたものですけれども、そういうところでは、市町村特別給付から介護財政のほうに行くということは、それはそういう方向でいいかなと思っているのです。こういうところは、ほんとうに格差をさらに助長するという中身になっていると思うのです。","respondent":"永尾高齢者福祉課長","answer":"今、もう一つ整備の予定は考えておりますけれども、その後につきましては、現在のところはまだ未定という状況になっております。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"地域支援事業は３％までということでしたけれども、今度、総合事業が入って、デイサービスとヘルパーが地域支援事業の中に入ってくるわけですよね。区としてはやはり、ほんとうにお金のある人もない人もきちんと対応がされる特別養護老人ホームの増設に、ぜひこれからも力を入れていっていただきたいという要望をさせていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"その後のことにつきましては、もう少し慎重に状況を把握しながら検討していきたいと考えています。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"高齢の方が、今、介護保険が始まって１５年目ですけれども、ほんとうに介護保険がどんどん使いにくくなっているという状況で、改悪されている状況があると思うのですけれども、そういう中で、必要な人が必要なサービスが受けられるというところで、ぜひ、こちらもチェックもしていきたいと思いますし、区としても取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは運営状況なので、そこの部分だけ少しお伺いしたい。生活保護だったら住宅型有料老人ホームも地方につくるということはあると思うのですけれども、そういうところの考え方と、先ほど、鈴木ひろ子委員もおっしゃったけれども、４カ所目の特別養護老人ホームとか、これから慎重に物事を運んでかいないと、最終的な地域包括ケアの住まいの部分をどうしていくのかということになる。","respondent":"永尾高齢者福祉課長","answer":"特別養護老人ホームの関係ですけれども、今現在、建設費助成をしているところが７５床あるのですけれども、三多摩のほうの特別養護老人ホームになりますけれども、そこを幾つか回ってご意見を聞いたりしているのですけれども、個人的に見れば、静かで。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々だって、相談を受けて、医療機関に相談をして、医療機関は３カ月で退院をすると、行くところがない。変な話、紹介されて、知っているところがあって、そこというだけの話になってしまうではないですか。ずっとあるのだけれども、そういうものを転換していく部分が、私は今がちょうどチャンスかと思っているところがありますので、ぜひ、お考えいただきたいと思います。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"品川区介護予防・日常生活支援総合事業の実施","agenda":"品川区介護予防・日常生活支援総合事業の実施","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"１ページのところでお聞かせ願いたいのですけれども、新しくチェックリストを使ってやるということですけれども、チェックリストというは、どういう方がやるのかということをお聞かせください。それによって分けるということになると思うのですけれども、資格とかがある方がやるのか、在宅支援センターでしかできないのかというところを、ちょっとお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"チェックリストを実際に取る方ですが、ご本人記入の質問表ですので、在宅介護支援センターのケアマネージャーが、ご本人と話しながら取ったり、あるいはこのチェックリストは、日常生活の、例えば社会参加、うつ状態、例えば外出の頻度、食事の状態などを。","id":"exchange-017"},{"speaker":"のだて委員","kind":"意見","question":"本人がチェックリストをやるということですけれども、そうなると、自覚のない方で、ほんとうはできないけれども、自分はできると思って丸をしてしまうということもあると思うのです。そういったことで、サービスに差が出たりしてしまうと思うのですけれども、その辺の担保の仕方をお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"そちらを通じて必ずアセスメントを行い、リスクの高い人を、ケアマネージャーの視点から抽出することが大事になってくると思います。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、本人がやると抜けるところもありますので、しっかりと見れる方に見ていただかないと抜け落ちてしまうということになりますので、ケアマネージャーにきちんとやっていただきたいと思います。それから、1)と2)の違いが、先ほどの説明ではよくわからなかったのですけれども、緩和した基準によってサービスを行うということでしたけれども、もう少し具体的にご説明いただければと思います。","respondent":"松山高齢者地域支援課長","answer":"1)の訪問介護と2)の訪問型サービス（緩和した基準によるサービス）との違いですが、1)の訪問介護と申しますのは、平成２６年度まで国が全国一律で決めておりました訪問介護です。ですから、区の裁量はなかなか入らなかったというものです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、1)から5)まで全部合わせた中で振り分けた数ということなのですか。それとも、今までの方は全部1)訪問介護に入っているのかというところを、ちょっとお聞かせください。水色のところの振り分けです。今まで受けていた方が1)から5)までのところで。","respondent":"松山高齢者地域支援課長","answer":"水色のところにつきましては、国があくまでも参考例で挙げた1)から5)でございまして、実際に品川区の総合事業としてこれまで実施してきたものを円滑に移行するということを踏まえまして、2)が予防訪問事業と、生活機能向上支援事業になっております。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"品川区としては、今、2)、3)ということでやっているということですけれども、私がお聞きしたいのは、今まで受けていた方が移行された中で、どこのサービスを受けているかということをお聞かせ願います。","respondent":"松山高齢者地域支援課長","answer":"これまで受けていた方は、全てそのままそれぞれの事業のほうに移行しております。","id":"exchange-021"},{"speaker":"のだて委員","kind":"意見","question":"今後、例えば訪問介護でいくと、3)、5)は検討して、構築していくということですけれども、どういった形でやるのか、シルバー人材センターとか、ＮＰＯを活用していくとか、現段階で答えられることがあったら、お願いします。","respondent":"松山高齢者地域支援課長","answer":"現段階では、3)、訪問型サービスＢ（住民主体による支援）をまずは行っていきたいのですけれども、ただ、品川区ではまだこれが構築されておりませんので、地域にある既存の資源、そういったものを分析しまして、意見交換をしながら進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"意見","question":"計画の見込みの段階でも構いませんので、もしわかったら、お聞かせください。それから、２ページのところで、介護予防ケアマネジメントがありますけれども、ここで、これができるのが在宅介護支援センターのみになるのか、それともほかの民間のケアマネージャーでもできるのか、聞かせください。","respondent":"松山高齢者地域支援課長","answer":"１点目、見込みですけれども、介護報酬が確定するのが６月末以降になりますので、正確な数字はこちらでは控えします。それからもう１点、介護予防ケアマネジメントにつきましては、まず、区内の在宅介護支援センターに２回ほど研修をしたところです。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"３ページのところで、先ほどの説明ですと、区の総合事業になって、上の１、訪問介護のところですけれども、単価端数処理によって整理して設定したということなのですけれども、ただでさえ、第六期のところで介護報酬を下げられているわけで、そういった端数処理で整理ということで下げられてしまっては、事業者としては、事業を運営するにあたってなかなか大変だと思うのですけれども。","respondent":"松山高齢者地域支援課長","answer":"先ほども説明の中でお伝えしましたとおり、国が定める介護報酬の単価以下の単価を各自治体が設定するように、という前提があります。この費用を決めるときにも、かなり事業者と複数回話し合いを持ちまして、このように決定させていただきました。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"設定基準額以下ということなのですけれども、端数整理をせずに、国の設定のままでもできたのではないかと、私は思うのですけれども、事業者からは、端数処理の整理でいいということだったのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"保険者としても、今後の高齢化をにらんだ給付の適正化の必要もございましたので、そこら辺も含めて、事業者との話し合いはずっと継続しております。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"通所介護のほうですけれども、送迎が８回、入浴４回ということになっているのですけれども、月によっては５週目があると思うのです。それはやはり、５回目はそんなにあるわけではないですし、ぜひ、ここの部分も出せるようにしていただきたいと思いますが、区の考えをお聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"事業者のほうで、先ほどもありました介護ケアマネジメントによって、まず一つは、１回の必要性があるかどうかというアセスメントをそこでしていただくというのが、まず前提になっております。それを踏まえて、実際問題加算をつけるかどうかという話にはなってくるかと考えます。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"今の答弁ですと、事業者が必要であると判断すれば、５回目も受けられるということでよろしいのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"もう一度、繰り返しになってしまいますが、在宅介護支援センターのケアマネージャーの判断によるものです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"意見","question":"ケアマネージャーが、５回目も必要だということであれば、いいということだと解釈いたしました。いきいき活動支援プログラム、これがどういったものが実際にあるのか、やっているところがあるのかということもお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"こちらも、事業者の届け出により、実施したいという事業者提案というものです。例えば、利用者がサービスの受け手から担い手に変わるメニューを考えていただいたり、あるいは、要支援の方でも利用者の特技、趣味を活かして、ご自分が講師になって教室を開く。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"実際に現在やっているところがあるかということもお聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"これをきっかけに、一定の目的を持って、一定期間において評価を行うような、介護予防を一度見直してみましょうということで、事業者からも声が挙がりまして、こちらのほうのいきいき活動支援プログラムというような実施になったものです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"事業者とご相談して、この要望が出たということですので、実際にやってもプラスにならないという声もありますので、そういった声も聞いてつくっていっていただきたいと思います。最後に、答えられたらで構いませんが、実際にやっている箇所数がわかったらお知らせください。","respondent":"松山高齢者地域支援課長","answer":"今現在の数字ではないのですが、品川区のホームページにもアップしているのですが、届出の書式がございまして、私が見たのは、４月の当初に３９事業所がございました。今はもっと増えているかと思います。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"緑の点線のところだけ伺います。そういう考え方ではなくて、ちょっと民生委員の場合微妙ですけれども、今動き出している、そういう実態も調べていただいて、そういう方々がもっと増えて、地域で高齢者をもっと支えていけるような形の部分を、ここは構築していただきたいと思うのですけれども、今まだ決まっていないということだったのだけれども、その考え方を改めて伺いたいと思います。","respondent":"松山高齢者地域支援課長","answer":"は民生委員とか、地域の見守りについては、一般のほうになるかと思います。いずれにせよ、介護保険会計を使っておりますので、何を分類するか、何を整理していくかということをきちんと分析して、これから意見交換してまいりたいと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今までデイサービスと訪問介護を受けてきた方は、ほとんど１００％こちらに移行したということですけれども、そこで一つお聞きしたいのが、３ページの訪問介護ですけれども、訪問介護の予防訪問と生活機能向上というのは、今まで受けていた人のそれぞれの割合がどれくらいになっているのか、ひとつ教えていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"と申しますのは、先ほど申しましたように、今後、介護保険の要支援者が増加するにつれ、介護報酬の適正化などがかなり厳しくなってくるだろうということが想定されるというのが、まず１点目です。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、予防訪問事業のところが、ほとんどの方が移行したということですけれども、生活機能というのは、家事援助だけの方ですよね。身体介護が加わるものが予防訪問事業になるのかと思っていたのですが、そういうことからすると、ほとんどが家事援助の方が多いのかなと思っていたのですが、身体介護も含んでの介護が要支援の方でも多いという、そういう捉え方でいいのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"今後、予防訪問事業のうち、きちんと介護予防ケアマネジメントによってアセスメントをしてもらって、必要のない方、あるいは生活援助に特化したほうがいい方につきましては、生活機能向上支援訪問事業に移っていただくようになります。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そういうことから考えると、要支援の場合は、今までは家事、身体ということでなく丸めてやっていたわけですから、報酬が下がったうえにさらに２０％ということで、ここで減額１,９１５円、そして週２回の方は３,８１９円ということで、かなりの引き下げになるということなので、ここのところは私は少し再考が必要なのではないかと思いますけれども、いかがでしょうか、ということが一つです。","respondent":"松山高齢者地域支援課長","answer":"最後に、地域包括支援センターは、総合相談の支援も行っておりますし、在宅介護支援センターへの支援も行っておりますので、総合相談窓口ということで、在宅介護支援センターが地域包括支援センターの役割も担っているです。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"また高齢者に対して見なければいけないものも変わらないというところで、家事援助のところは、今までは要支援で同じだったわけですから、そこのところを引き下げるというのは、しかも２０％引き下げて、これだけ大幅に引き下げるのは、国の基準以下ということなので、以下ということは、同等ということも入りますので、そこのところはぜひこれだけ引き下げるのはやめていただきたいということが一つです。","respondent":"松山高齢者地域支援課長","answer":"地域包括支援センターと同じ体制がつくられている在宅介護支援センターが何カ所あるかというお尋ねですが、少し数字はお待ちいただいて、品川区独自の高齢者在宅生活を支えるための仕組みとして、在宅介護システムというものがあるのですが。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでは、ブランチということであれば、保健師に準ずる看護師でもいいとか、そういう中身があると思いますので、そういうところも含めて、在宅介護支援センターの中にそういう体制をしっかりととっていただきたいと思うのですけれども、そこのところはいかがでしょうか。そこのところがどう担保されるのかというところが見えないので、ちょっと教えていただきたい。","respondent":"松山高齢者地域支援課長","answer":"これまでのアセスメントにつきましても、同じように、要介護、要支援の認定の仕組み、それからアセスメントにつきましても、きちんと担保されることを、こちらのほうで説明させていただきましたので、例えば情報公開ということであれば。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで、保険料に連動しないための処遇改善の交付金とか、国の負担割合を広げるというところでは、これは全国市長会議でもずっと要望しているところですから、そういう方向で介護保険は改善を求めていくべきですし、高齢者にサービスが行き届かないことのない仕組みとして、ぜひともお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"(3)、南品川シルバーセンターの浴室等整備","agenda":"(3)、南品川シルバーセンターの浴室等整備","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"お近くの住民の方にとって、とてもいいことだと思うので、ぜひやっていただきたいと思います。時間帯とか、何時から何時まで入れるのかということがわかったら、お知らせください。","respondent":"松山高齢者地域支援課長","answer":"東品川シルバーセンターを除き、ほかのシルバーセンターと同様に、正午から午後４時までを予定しています。","id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけ。私の感覚だけだと、工期が長過ぎるのではないかと思うのです。これくらいの改修をふつうに請け負って、半年かかるというのは、私にとってはびっくりしたので、何でこんなにかかるのか。ここで聞いても、多分施設整備だからわからないと思いますが、それだけを言っておきます。","respondent":"松山高齢者地域支援課長","answer":"１カ月間はどうしてもコンクリートの破砕ということで、大きな音がするということですが、１１月からは改修場所を除きながら、利用者団体、グループ等のいながらの工事になりますので、何とか工夫して使っていただくということで、少し長引いております。","id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"質問","question":"なぜそういうことを言うかというと、コンクリートを破砕しようが、解体しようが、３８m2くらいだったら、特に間仕切りは大した構造ではないと思っているので、全体の構造上の問題があるわけではないと思うので、そんなにかかる話ではない。どうしてこういうことを言うかというと、シルバーセンターを使いながらやるというのであれば、短いほうがいいわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-04","title":"品川区障害者福祉手当（二種難病）の対象疾病の拡大","agenda":"品川区障害者福祉手当（二種難病）の対象疾病の拡大","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今後、わかった段階で教えていただけたらと思います。それから、地域の方にお話を聞くと、難病手当が拡大されたのはよかったのですけれども、自己負担が増えているという話を聞いているのですけれども、その辺を区でつかんでいたら、お聞かせください。","respondent":"舟木保健予防課長","answer":"平成２７年１月から新たな難病医療費助成が実施されることに伴いまして、対象疾病が拡大されました。それに伴いまして、医療費助成の内容も変更となっております。世帯の範囲について変更があり、自己負担額についても変更となっております。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"枠が広がったのはいいのですけれども、実際にほかの方の負担が増えているということなので、今後もし、同じ助成額でできるならばその検討をしていただきたいと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"いながわ委員","kind":"質問","question":"ここにきて、１２９疾病から３２５疾病になった大きな要因、理由はあるのですか。ただきて、はい、ここに書いてくださいだけではなくて、懇切丁寧にいろいろご指導していただくのがいいと思うのですけれども、その辺はどういう取り組みをされるのか、教えてください。","respondent":"中山障害者福祉課長","answer":"あわせまして、更新時の手続につきましても、そういったチラシを今年度から作成しまして、漏れがないような決定というところで、保健センターと連携して行っているところです。","id":"exchange-043"}]},{"id":"topic-05","title":"保健施設利用助成事業等の見直し","agenda":"保健施設利用助成事業等の見直し","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"今後、見直して契約料金での利用になるということですけれども、これについて、区の助成があるのか、ないのかということ。本来の金額から幾らくらい割引になるのか。それからもう一つ、人間ドックの受診助成事業本格実施ということですけれども、つまりこれまでは本格ではなかったということだと思うのですが、それはどういったことなのかを、お聞かせください。","respondent":"高森国保医療年金課長","answer":"人間ドックのほうですが、平成２６年度から助成事業の実施を開始しておりますが、実はこれは６月１日から開始しておりまして、平成２６年度の動向等が、平成２７年度予算編成時、去年１０月ごろですけれども、その段階では。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、これから検討していくということでしたけれども、ぜひ多くの方が受けやすいようにしていっていただきたいと思います。契約料金のことですけれども、今のご答弁ですと、区の料金は入っていないのかということを確認させてください。","respondent":"高森国保医療年金課長","answer":"一般料金２,４５０円で、法人契約料金が２,０００円程度ですから、平成２７年度はたしか１,６５０円ということですから、区の補助金は、そこには３５０円ほど、２００万円がそこに戻っているという形で入っております。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"利用者数が少なかったということですけれども、どの程度の利用者だったのか。それから、これらの費用が、全体で幾らくらいかかっていたのかということ。そして、これは保険料の賦課総額の中には入らないということで考えていいのか、この点についてもお聞かせください。","respondent":"高森国保医療年金課長","answer":"利用率ですが、(1)の保養施設につきましては、国民健康保険加入者で割り返しますと０.８％、後期高齢者については０.０１％、交流施設につきましては、国民健康保険加入者０.６％、後期高齢者が０.０６％という状況です。","id":"exchange-046"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"別府は、別にほかでも行きたいと思っていて、先ほど言った障害者計画の部分もあって、障害者計画とか、障害のある人もない人も安心して安全に暮らせる条例を制定したりしている部分があって、これは議会提案でそういうことをしてもいいのだけれども、そういう部分もあるのであれば、これは行きたい。そういうのも一つの提案型になるのかと思っていまして、そういうところがいいのかと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"若林委員","kind":"質問・要望","question":"所管事務調査が固まりまして、これを基本に、ぜひ、いい事例を、また参考になる事例をお願いしたいと思います。私も、先日、会派で西宮市に行ってきましたけれども、兵庫県とか、明石市とか、神戸市とか、こういう関西方面に先進事例があるということをお聞きしていますので、ぜひ、参考にしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"きのうも議題になりました認知症ケアパスのところで、どこがどう進んでいるのかというのが、自分としてもまだ把握し切れていないのですけれども、そういうところで、先進的に進んでいるところがありましたら、そういうところをぜひ視察の中に入れていただけたらと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/866699?Template=document&Id=3420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":54100,"voices":146}},{"id":"h27-20150630-8","meetingId":"h27-cm06","date":"2015年6月30日","dateIso":"2015-06-30","committee":"建設委員会","time":"午前１０時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"説明があったのですけれども、少し教えていただきたいのですが、北品川駅より以北というのですか、南が高架化されたのですけれども、確かに、事実、どんどんあそこが下がっていって、フラットに地面の高さがあって、以北は高架化されないで踏切が残ったのですが、その理由というのは何だったのかというのを改めてお伺いしたいのと、それと、今回、事業に着手するということなのですが。","respondent":"中村都市計画課長","answer":"それで、費用負担の割合ですけれども、こちらのほうは今後、東京都、また国と協議をしていく中で、実際に調査、今年度着手する調査を踏まえて、その計画の中で検討がなされて決定していくものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"費用負担の協議はこれからということなのですが、こういうのは特に基本的なルールみたいなものはないのか、もしあるとしたら、ルールの中身を教えていただいて、それをある程度ベースにして協議していくということなのか、そこもお伺いしたいと思います。それと、今回、動き出した理由ということでお伺いしたいのですけれども、動きが活発になってきたと。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"費用の負担割合ですけれども、これは東京都施行、あるいは区施行といった事業主体の違い、あるいは踏切改善の必要性、こういったもの、さまざまな条件の中から割合が決まってくるということで。あわせまして、周辺のまちづくりも進めることによって、よりよい品川駅周辺または旧東海道の玄関口にふさわしいまちづくりが進めていけると考えておりますので、今回の京浜急行線の立体化にあわせて。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"今回、高架化ということは踏切解消ということもありますから非常に大切なことだと思うのですけれども、まちに住んでいる方々の利便性を向上させる問題と、安易に超高層のビルをどんどん建てていくという再開発は、私はリンクさせるべきではないと思いますし、今の時点では直接リンクしているわけではないと思うのですけれども、そこら辺について、今回の踏切解消の高架化というのがいわゆる。","respondent":"溝口都市開発課長、藤田都市環境部長","answer":"ですから、決して超高層のビルだけを建てるという思いではなくて、地域の方たちとともにこの地域にふさわしい公共空間を含めながら、まちづくりを進めていきたいと考えているものです。品川駅からその先の泉岳寺までの間、あの間は結構急な坂になっているのですが、その間とのすり合わせも含めて検討した結果、なかなかすりつけが難しいと。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認だけさせてください。先ほどあったように、北品川駅の南側は立体が続いていて、ちょうど八ツ山橋陸橋の辺りは、大体あの辺の高さのイメージでいいのですか。どのぐらいに高さがなってくるのか、その辺の確認です。","respondent":"中村都市計画課長","answer":"しかしながら、既存で高架化してあるところもありますので、それ以上高くなってまたおりてくるというようなことは、設計としては考えにくいと思います。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"品川駅を地平化していく中で、ホームはずっと田町寄りに伸びるという話を聞いているのですが、どの辺まで伸びていくかというのは大体わかりますか。その辺はまだ正確には聞いていないのか。それと、完成はいつごろのめどなのか、聞き損なってしまったので、それがどのぐらいになるのかというのを確認をさせて下さい。","respondent":"中村都市計画課長","answer":"しかしながら、総合的な観点から行きますと、中央リニア新幹線が品川駅を発着場所とするというところから考えますと、本来、中央リニア新幹線の開業にあわせてその工事が完成されることが好ましいと、区としては考えておりますけれども、ただ。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"車の動線の関係ですけれども、今、八ツ山橋踏切があって、あのレベルはそのまま。そこの坂に行くときに急な坂になりますが、もう一つは、アンダーパスがあるから両方、今後の車の流れはどうなるのかというのが気になった。まだ先のことなので、先々検討して報告いただくことになると思うのですけれども、その辺も流れをいろいろ考えておいていただきたい。これは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"の中央新幹線整備に伴う物件（井戸等）調査の実施","agenda":"の中央新幹線整備に伴う物件（井戸等）調査の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"調査の方法について少しわからない点があったのですが、添付のポスティングという資料の裏に、「井戸の有無」、「あり、なし」ということで、返信をということであるようなのですが、これは全部を調査するというよりも、ここに井戸がありますという自己申告があったところについてのみ訪問するという形なのか、そこら辺がわからなかったのでお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"この調査の正確性を期すために、こういった事前のお知らせの中で回答をいただくということと、また、ＪＲ東海の資料の、今回提出させていただいているのは資料の１ページ目、各戸を訪問し、対面による有無の調査ということですので、全戸を調査すると聞いております。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"事業自体は私は必要ないと思うのですけれども、こういったことで進められてしまうという中で、事業の進捗ですけれども、特に影響が大きい北品川駅の非常口の部分、変電施設の部分ですけれども、これはたしか財産上の敷地だったと思うのですが、それは今、進捗状況はどうなっているのかということと、それと、品川区長がリニア絡みで。","respondent":"中村都市計画課長","answer":"品川駅のリニア新幹線の発着地点におけます出入口を南側にですけれども、こちらのほうはなかなか技術的、また現在のまちの状況、そういった総合的な観点から難しいということは聞いております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"すみません、肝心なことを聞くのを忘れたのですが、今回調査対象となるお宅の件数、それが何件なのかということをお伺いします。ですから、そこら辺のＪＲ東海との情報共有といいますか、区としてどこまでつかんでいるのか、つかもうとしているのか、そこら辺の考え方、ぜひ私はつかむべきだと、地元の自治体としてもっとつかむ必要があるのではないかと思うのですが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"ＪＲ東海から現在この事業に向けた設計、あるいはさまざまな手続、こういったものを行っているというところで、鉄道が通ります線形そのものについてはおよそ決定しているですけれども、それ以降の情報につきましては品川区も情報提供。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"地下に事業地区に直接支障を来す井戸等の物件があるかどうかの調査ということなのですけれども、着工自体、地下を掘り進むというような工事なのかどうかということを１つお聞きしたいのと、工事の規模はどの程度になるのかということ、わかる範囲でお教えください。","respondent":"中村都市計画課長","answer":"工事の方法ですけれども、今、委員がご指摘のとおり、地下４０ｍよりも深いところ、場所によっては深さはさまざまですけれども、こういったところを掘っていくには技術的にはシールドマシーンという地下のトンネルを掘る大きなドリル状の機械。","id":"exchange-010"},{"speaker":"筒井委員","kind":"意見","question":"この地図を見ますと、三ッ木保育園や源氏前保育園など、あと荏原第五中学校等がありますので、その辺の教育上支障が出ないよう、区としてもご配慮をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-03","title":"の区営住宅入居者の募集","agenda":"の区営住宅入居者の募集","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、募集期間は、年に２回に応募というか、募集になっていますので、半年あるわけですが、そのうちのわずか１週間というのはあまりに短すぎると思うので、ぜひ改善をしていく必要があるのではないかと思うのですけれども、どうかということと、あと、お知らせのことに関しては、これ以外にお知らせしていないのかということもあわせて、ぜひ積極的に区営住宅。","respondent":"矢木住宅担当課長","answer":"３点目に、意外に都営住宅、区営住宅等の入居募集をしていること自体を知らない、ＰＲ方法はどうかですが、こちらにつきましては１週間という申込期間でございまして、おそらくはこうやってきた理由があると思いますので、その理由を確認した上で改善できる方法があれば。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"対象、選定された６カ所ということなのですけれども、４３カ所都指定の危険箇所があるということなのですが、選定の基準といいますか、都内には結構あちこちに崖があると思うのですけれども、選定の基準と、選定したのはどなたなのか、区なのかということをお伺いいたします。","respondent":"鈴木建築課長","answer":"この４３カ所につきましては、平成２９年度からまた東京都がさらに調査を進めまして、平成３１年度までに土砂災害防止法による警戒区域の指定に向けた取り組みを進めていくという予定になっておりまして、区としてはそれに先立ちまして。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一つ要望なのですが、情報・意見交換会、今夜含めて２回ということですけれども、いざというときの発令時にどうやって逃げるかという、情報伝達ということだけでなくて、情報・意見交換ということなので、実際に今の崖を所有している方々ですとか、近隣の方々が来るわけですから、そこで悩んでいる方がたくさん来ると思うので、ぜひ率直な住民の悩みですとかご意見を聞いていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"今回は事前周知ということなのですけれども、１つは、多分２００世帯の方々がまず自覚があるのですか。２点目は、指定避難所というところがあると思うのですけれども、その指定避難所への行き方とか、何かあったときには避難しなければいけないのですから、その行き方、例えば避難所訓練というのをやっていますが、防災関係で、ああいう形でそういうことも考えられているのか。","respondent":"鈴木建築課長、松代防災まちづくり部長","answer":"あと、３点目の所有者等々に対する今回の周知あるいは説明会についての、さらに今後の話ですけれども、避難基準、行動基準を策定しましたので、これについてのご理解をまず深めていただきたいということとともに。これは、区の姿勢でありますけれども、津波被害が起こるということで、先般の東日本大震災が起こったときに東京都が出した被害想定の中で、品川区は津波被害２.６７ということで一番高いということで出されたときに。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"今回は６カ所。４３カ所も品川区内に崖がある。確かに民地ですから、品川区が助けるということはなかなか難しいというのはあると思うのです。ただ、努力はしてほしいと思うのです。民地なので。それが先だと思うので、そういうきっかけづくりになっていただきたいと、４３カ所ありますので。６カ所いい事例という形でしていただいて、今後進めていっていただきたいという要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"すみません、すごく不勉強で、過去の質疑の中でもあったかもしれませんけれども、基本的なことを教えていただきたいのですが、こうした準備情報、避難勧告などで、実際に災害が起こってしまったときに、きちんと行政として事前の、今回の周知もそうなのですが、集中豪雨等のときに勧告指示をして、それが当然届いてはいるのだけれども、いろいろな状況の中で自宅にとどまるとかいう判断をして。","respondent":"鈴木防災課長","answer":"しかしながら、区としてはそういうケースも含めて、ご自分の判断ではありますが、できるだけ早い避難、また安全行動がとれるということで、知識や情報提供を行うということで取り組んでおります。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"だから、今回はポスティングと意見交換会があると思うのですけれども、そうしたときにその部分を強調して、見捨てるとかそういう視点では当然ないのだけれども、あくまでもきちんと自分自身で自覚をしていかないといけないのだということを今一度確認、こういう機会を通じてやっていただいたほうがいいのではないかと思いますので、これは要望ですけれども、ぜひその点の確認もお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"本当に危ないと思うのですが、１４番のところでは違反になることがあるということなので、ストレートになるわけではないのだということを改めて思ったのですけれども、ここら辺はもう少し説明、自転車に乗りながらの携帯電話の操作等についてもう少しご説明いただきたいと思ったのと、それと、若い方々がスマートフォンを利用している方が多いので、そうしたことが多いのですが。","respondent":"田口交通安全担当課長","answer":"ここには多くのサラリーマン層の方も来たのですが、実際の年代別の事故件数を見ますと３０代、４０代が一番多いと、働き盛りの方が一番多いですので、やはり企業に対して、また、前回やったように公道、ちょうどお昼の時間帯だったのですが。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"私も入っているのですけれども、区内で、わかればいいのですけれども、大体自転車利用者の方で、区内でなくてもいいのですけれども、保険に加入している方というのはどれぐらいの割合なのかというのを把握していれば、一般的な数字でもいいのですけれども、伺いたいのと、品川区としても保険加入のお勧めというか、そういった啓発みたいなことはしているのか。","respondent":"田口交通安全担当課長","answer":"それと、区として保険加入について周知徹底をしているかですが、警察と連携していろいろな安全教育等を行っておりますが、その際に保険加入というのはもちろん勧めるのですが、本日お話ししたように高額賠償事例ですが、こうした事案があった場合に。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"最終的には個人の判断になると思うのですけれども、自転車保険というのがありましてということを、加入しておくと安心といいますか、そういったことの啓発ですとか、広報ですとかを継続して進めていただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"前回の委員会のときに、詳しい説明をということで、ありがとうございました。わかりやすい文が入って、非常にいいと思いました。難しいです。なので、これをどう啓発していくかということなのですけれども、今の学校ではある程度自転車教室をやっていると思うのです。警察の方々はどういう啓発活動をしようとしているのか、もしわかれば教えていただきたいと思います。","respondent":"田口交通安全担当課長","answer":"それと、あと、取締りの関係ですけれども、実際まだ警察署から２回やって講習対象になったとかいう話は来ていないのですけれども、ただ、今委員がおっしゃったように非常に難しいということで。","id":"exchange-022"},{"speaker":"西本委員","kind":"提案","question":"周知というのは非常に難しいと思うのですけれども、今おっしゃったように何か簡単な冊子があるといいかもしれないです。それを全戸まで行くかどうか、費用の関係もあると思うのですが、一度こういう形になりますみたいなのは、違うかもしれないですけれども、それは提案という形で一緒にいろいろ、全庁挙げてしていただく方向で検討していただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"私、この１４類型のうち、一番後半で抽象的な類型が１１番だと私個人は思ったのです。警察官の方の現場での判断、裁量に委ねられると思うのですけれども、この点、具体的な事例とかをもう少しわかりやすく警察署のほうで解説してくれればいいかと思いましたので、ぜひ区としてもその点の要望を警察署のほうにお伝えいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"資料いただいて、ありがとうあります。予算で考えたときに、どこが予算を組んでいるかというのは、その辺を踏み越えてしまうと違うのではないかと思うのですが、その辺、全体のことを教えてください。","respondent":"松代防災まちづくり部長","answer":"そういったことを例にとりながら、ソフトでの対応というのが我々の仕事ではないかと考えています。予算面で言いますと、今言いました交通安全対策の事業を展開する費用、また学校等での周知などに要する費用、そういったものを行政が負担しております。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"連携をとっていただいて、進めていただきたい。警察からも来ていただいて、また区民の安全ということでは消防の方も入っていただいたり、自衛隊も入っていただいた。区民の安全ということで非常に連携をとってやっていただているのは十分わかっております。ただ、あくまでも安全は守ってもらいたいというのは、連携をとってやってくださいというのはお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"確認なのですけれども、２段階右折というのがありますが、それについて今回、自転車の場合、車道の車線の数とか、そういうことに関係してくると思うのですけれども、今回のこの１４類型の中に入っていないのですが、改めて自転車の場合はどの場所だったらどういうふうに右折するのだというのを教えていただければと思います。","respondent":"田口交通安全担当課長","answer":"今回の１４類型には入ってございませんが、例えばそういう方法であると非常に危険性があるということになりますと、例えば１４番にあります安全運転義務違反、これはまさに他人に危害を及ぼすような速度や方法ですので、こういった部分にも絡んでくるのかと思います。","id":"exchange-027"},{"speaker":"つる委員","kind":"確認","question":"私は免許を持っているのですけれども、すみません、確認で、ここしばらく原動機付自転車に乗らないものですから、どういう車線の形状の交差点であれば、自転車も原動機自転車と同じように２段階右折をするとなるのか。すみません、確認。","respondent":"田口交通安全担当課長","answer":"例えば何車線かある道路でございましたら、原動機自転車と同じように第１通行帯ですが、一番端の通行帯をまず交差点を通りすぎて、また次の信号でと……。","id":"exchange-028"},{"speaker":"つる委員","kind":"確認","question":"ごめんなさい。２段階右折の方法はわかるのですが、本当に基礎的な、個人で勉強しろという世界かもしれませんけれども、確認しろという世界かもしれませんけれども、複数車線のところですが、そこだけもう一回お願いします。","respondent":"田口交通安全担当課長","answer":"ただ、単路で交差点が例えば信号がないとかいう場合は通常に、そのまま右折はできますけれども、今言いました複数で信号機があるような大きな交差点の場合は、原動機付自転車と同じような方法で２段階右折をしないといけないです。","id":"exchange-029"},{"speaker":"つる委員","kind":"確認","question":"言うほどでもないのですが、結構私ハンドルを握っていて、スポーツタイプの自転車というのでしょうか、この方が、右折誘導体というのでしょうか、あそこで待機している方が多いのです。それはどうなのだろうと思ったものですから、確認も含めてさせていただきました。","respondent":"松代防災まちづくり部長","answer":"そういったものがどういうものかというのはこれからどんどん詳しく説明されていくことだと思いますし、また、もし仮に摘発された場合、もしくは注意された場合は、どういうところがというのをぜひ聞いていただく、またそういったことも一つのあれなのかと思っています。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"複数車線という話が出たので、教えてもらいたい。複数車線というのは、左折のレーンがありますが、その場合、自転車はどうしたらいいのですか。いつも悩むのだけれども。","respondent":"田口交通安全担当課長","answer":"左折のレーンに自転車は入ります。そこに。","id":"exchange-031"},{"speaker":"木村副委員長","kind":"質問","question":"僕も一般質問でこの前させていただいたのですが、この１４類型についても理解に苦しむところもあるのですが、今、８番の場合ですと、２段階というのですか、向きを変えてということで信号待ちをして、でも、今ほとんどの人たちを見ていると、自分もこういう形でこういう案件にかかわっているものですから、やはり自転車に乗るときに大変意識をして乗るわけですけれども。","respondent":"田口交通安全担当課長","answer":"ただ、委員がおっしゃったように、例えばその行為だけでもって非常に危険性があるという場合であれば取締りは可能ですが、ただ、最終的には現場の状況を踏まえて警察官が判断すべきものですので、その辺は私もよくわかりません。","id":"exchange-032"},{"speaker":"木村副委員長","kind":"意見","question":"確かに現行犯でなければ今回はだめだろうと思っていますので。しかし、僕は自転車に乗る距離というのは短いわけですが、その間に警察官がまちに出てやっている、６月１日以降あまり見たことがないのです。そういう意味では、どういうふうに取締りをするのか、しているのかどうか、よくわからないのです。わかる範囲で結構なのですが、警察の考えというものをもう一度お聞かせ願えればと思います。","respondent":"田口交通安全担当課長","answer":"今後ですが、我々も警察と連携を図るために警察署等に赴くケースが多くありますので、その中でまた警察のほうに取締り状況を聞くというのは何ですけれども、今後どのような方針でやっていくのかとか、そういった情報も得ながら我々。","id":"exchange-033"},{"speaker":"木村副委員長","kind":"意見","question":"自分も注意をしながら乗っているわけでありますけれども、ちょっと何かのときにはさっと、この１４類型の何かに引っかかるようなことをやっているのをよく見るのですが、一人ひとりがしっかりとやっていかなければいかんと思っていますが、そして、裏面の一番下にあります今回、自転車のひき逃げの免許停止処分ですが、車でも同じことをやるであろうから１８０日ということになっていますけれども。","respondent":"田口交通安全担当課長","answer":"現在までの事例ですと、１８０日処分のみとなります。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"それと、計画の内容ですけれども、改訂版の１枚ですとわからない点があると思ったのですが、１つは、橋梁の架替や撤去を含めた計画とあるのですけれども、架替とか撤去するような橋というのは予定があるのか、そこがよくわからなかったので、どういった計画なのかというのをもう一度お伺いしたいのと、それと、現状の調査でもIIIのところが２８もあるということなのですが。","respondent":"稲田道路課長","answer":"職員も含めた体制についてです。職員は橋梁関係の職員、係長入れまして全員で４名で対応しています。実際の点検や修繕計画や詳細の設計というものに関しましては、専門のコンサルタンツに委託して実施してきているところです。次に、架替について今回盛り込んだです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"かなり経費のかかる事業だと思いますけれども、区民の命に直結する大事な事業だと思いますので、ぜひ、点検体制のお話を伺いましたけれども、実際の具体的な点検などは専門コンサルタンツに委託ということでしたが、４人ということなので、実際の区の職員の方。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この黄色の３の、区分の３段階ですが、今回２８橋になって、前回の計画のときにはこの２８橋は３にはなっていなかったのか、それとも、そのときも３が入っていたのかどうか。それが１点です。それから、修繕計画の対象が品川区の全橋梁７０橋となっていますけれども、全橋梁というのは歩道橋も含めてということでいいのですか。","respondent":"稲田道路課長","answer":"前回の点検、修繕計画、それから今回の修繕計画とありますが、前回立てたものをまた５年たって見直したというところで、含まれている橋梁等もあります。それと、この計画は７０橋、横断歩道橋も含めた計画です。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"確認","question":"前回３で、今回、この５年間で３を全部やりますというと、前のときに５年間でやる予定だったのではないのかという意味の確認。それから、歩道橋というのは区が全部管理しているのですか。それとも、都とか国が管理している部分があるのかという、そこら辺を。","respondent":"稲田道路課長","answer":"品川区の国道と都道、区道も歩道橋で分けているのですが、国道が１６橋、都道が１０橋、品川区は２０橋、歩道橋、横断歩道橋ではなくて人道橋とか、そういうものも含みます。地域によっては非常に複雑なのですが、一般的な人道歩道橋というのは２２橋あります。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"なぜ歩道橋を聞いたかというと、撤去も含めて、先ほど話があった中で、具体的にあまり必要のないような歩道橋も今ありますが、よく言われるのが三ツ又歩道橋。ほとんどあれ、区でないからしようがないと思うけれども、そういうのも逆に言うと検討を区のほうから挙げられないのかというのが質問の内容。","respondent":"稲田道路課長","answer":"東京都も同じような東京都の基準でやっておりまして、三ツ又の歩道橋、以前から言われているというところで、東京都には区としてそういう意見は伝えているところではありますが、今後、状況を見ながらまた。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"単純に言うと、大体６本ずつとか、５本とかいう数字で、この数年から見ると結構増えると思うのですが、修繕計画の中に入っているかもしれませんけれども、何本ずつぐらいという、均等割りではないと思うのですが、状況によるのでしょうけれども、どんな計画で、概略で結構なのですが、お答えできる範囲で教えてください。","respondent":"稲田道路課長","answer":"そういうところで、本数的に言いますと、工事で言いますと、今年度、桜橋等の耐震補強等も含めまして４橋を実施する。それから、２０１６年度には１橋、それから、２０１７年度には６橋、そのような形で年度によっては大小、大きさの違うものがありますのでばらつきがあります。","id":"exchange-040"},{"speaker":"つる委員","kind":"質問","question":"それと、あと、区で管理はしているのだけれども、すみません、これ、読み方が「トウセンキョウ」ですか。鉄道管理者。「コセンキョウ」か。跨線橋とかいうものの中で、予算、お金の出し合いというのか、区が全部を全部出さなければいけないというものでないのもあるのかと思って、そうしたところからお金というのは出してもらったり、その辺はどうなっているのかと。","respondent":"稲田道路課長","answer":"鉄道をまたぐ橋梁です。これは区道として鉄道をまたいでおりますので、費用としましては道路側、区側が全部もっていくです。国庫補助金等は活用しながらやっていくという状況です。","id":"exchange-041"}]},{"id":"topic-04","title":"のみどりの実態調査の結果","agenda":"のみどりの実態調査の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"中身についてまず２つほどお伺いしたいのですが、みどり率のところで、公園以外の樹木被覆地が減少しているというのは何か原因があるのでしょうか。その原因を知りたいのと、それと、あと、最後、緑視率というところが紹介されたのですけれども、これは計測している場所といいますか、箇所といいますか、どんな基準でこれは計測ポイントを定めているのか、実際どこを定めているかを伺えればと思います。","respondent":"多並公園課長","answer":"今回、その代表例ということで、ここに書かせていただいていますけれども、ほぼこの中の２２カ所がこのような大規模、もしくは個別の開発でも建替えて見えるみどりを増やしていっていただいている部分が多かったり、あとは街路樹についても。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"この調査なのですが、基礎資料として今後の施策に活かしていくという話があったのですけれども、品川区としては緑被率ですとか、みどりについてを向上させていこうというお考えだとは思うのですけれども、目標みたいなものを持っているのか、それと、どういう方法で緑被率ですとかみどり率を増やそうと考えているのでしょうか、お伺いします。","respondent":"多並公園課長","answer":"目標ですけれども、品川区は平成２４年に水とみどりの基本計画・行動計画という計画を策定しています。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"私は、地域ごとに、丁目ごとにきちんと公園の整備目標というのですか、それをもって同時に、あわせてみどり率や緑被率を上げていくということが区民の、生活している者からの、住民からの感覚からいってもすごく大事なことなのではないかと思うのですけれども、そこら辺のお考えといいますか、どういうところにどれだけの公園をつくるかという目標、そういうのは区として持って。","respondent":"多並公園課長","answer":"今後もこのようなことで進めていきたいと区としては考えているところです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりこういったみどりを増やしていこうという施策を持っておりますので、ぜひ地元からのそういった強い要請ですとか、思いがありましたら、それを積極的にやはり受けとめていただいて、必要なものはしっかりと整備するという立場で取り組んでいただきたいと思うのですけれども、それは私の要望と同時に、ちょっとお考えなどがあればぜひ、今のみどりを進めていくという立場からのお考えがありましたら。","respondent":"多並公園課長","answer":"こういう観点であったり、あとは公園にしてほしいところであれば、そこは、どこの地区かというのもありますけれども、先ほどのような観点で、区としては今、木造密集地域を含めた、そちらのほうを重点的に進めながら整備を進めているところですので、そのような総合的な観点で。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"そこら辺のご理解を進めていくのは何か並行してやっているのかと。緑視率の例があります北品川六丁目の、これを見ると、お掃除をする側からすると、緑地、木がないほうが助かるのです。変な言い方ですけれども。そこら辺のご理解をどういうふうに進められようとしているのか、お聞きしたいのですけれども。","respondent":"多並公園課長","answer":"最初の屋上の件ですが、屋上の傾向といたしましては、先ほどの荏原地区で増えているという件で、もう少し細かい、宅地の敷地の平米で見てみますと、大崎とか品川はどちらかというと開発系の、大きい開発の３００m2が開発の一つの要件になるのですけれども。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"屋上緑地の結果を見ると、それなりに皆さま考えて寄与しているというのがよくわかりました。結構、業者もいろいろ含めて整備は、公園も含めてよく整備されていると思うのです。なので、品川区という中でも、清潔感とかいうのが品川区の一つの大きな特徴にもなっていると思うので、今後、理解を求めながら進めていかれるようよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"屋上緑地の件なのですけれども、私もまだすみません、知識不足で教えていただきたいのですが、小中一貫学校の整備された、新築された学校の中には屋上緑地もありますけれども、それは当然屋上緑地の部分で含まれるということでよろしいのでしょうか、よろしくお願いします。","respondent":"多並公園課長","answer":"今、委員のご指摘のとおり、そういう部分もこの中に入っているものです。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"荏原地区なのですけれども、まさに私が今居住している地域でございまして、今いろいろ要望があるのですけれども、これは私からの要望なのですけれども、立会川にかかわるふたをしてある遊歩道の公園の整備、それは今後整備していくということは考えているのでしょうか。","respondent":"稲田道路課長","answer":"立会川の上にふたをして、今、緑道形式になっているところの整備ですか。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"先ほど、冒頭の質疑の中で目標とかはわかったのですが、まず、都心部におけるみどり、まさに緑被率の目安というのでしょうか、そういうものというのはあるのでしょうか。そこを教えてください。","respondent":"多並公園課長","answer":"これが平成２５年度実施しています。この中では、都全体では、先ほど申しましたみどり率が品川区は２１.４％でしたけれども、都全体では５０.５％という実績があります。ただ、これも都下と都心で分かれていまして、区部、区の中では１９.８％というのが今の実態です。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"いろいろな形で個人の方への啓発、ご協力いただく部分と、あと大きい開発に伴うみどりの充実とか、いろいろなやり方があると思うのですが、その辺の方法のそれぞれの目安みたいなものはあるのでしょうか。では、街路樹をどうこうしていくとか、公園を増やしていくとかあると思うのですが、そういう個別の目安みたいなものはあるのでしょうか。","respondent":"多並公園課長","answer":"先ほどの基本計画というところでお話ししたところですけれども、その中で内訳で今後できるところということでいろいろ算出していますけれども、それについては基本的には全体的な数字で目標としているところであって。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"いずれにしても、方向性としては、個人的にもみどりの品川というところはこれからも一生懸命頑張って、２５％という一つの目標を目指してやっていただきたいですし、先ほどのお掃除とかという部分、具体的な話もありましたけれども、都心部におけるみどりを感じられる環境というのでしょうか、緑視率ということになってくるのでしょうけれども、都会の中における森林力というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"意見","question":"先ほどの土砂もそうなのですけれども、今度サイレンが鳴るということの通知を出したときの、直接ではないのだけれども、デジタル化ということで、この前新聞に出ていたのだけれども、品川区はデジタル化していないけれども、これはどういうふうに考えたらいいのかと思いまして。","respondent":"鈴木防災課長","answer":"この後、平成３４年までに旧規格が一切使えなくなるという期限がまた別にまいりますので、それまでの間に機器の部品を交換して対応するのか、もしくは機器を改めて更新するのか、その辺のところをこれから、費用とか、それから周りの現状を確認しながら検討するという段階です。","id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"質問","question":"要するに今のが可能ということは、かえる範囲になっていないということですか、品川区はかえないでいいという。新聞だと品川区はかえていないからというふうに見えたので。わかりました。もう一回、では。","respondent":"鈴木防災課長","answer":"今、確認のご質問いただきましたように、変更が必要な周波数は国から指定されておりますが、品川区はそれには該当はしておりません。先日、新聞の報道で出されたときには、該当するかどうかは関係なく、今後検討するというくくりの中で品川区の名前が出されたものです。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の名称等の変更で、一区民の立場で考えると、何が実際に具体的に変わるのかというか、そこら辺がよくわからなかったといいますか、どういう心構えを変えなくてはいけないのかわからなかったので、もう一度、今回の変更によっての区民への影響といいますか、もう一度説明していただきたいのですけれども。具体的にはどういうところにあるのでしょうか。","respondent":"和田河川下水道課長","answer":"変更の経緯につきましては、先ほど答弁の中で、国の変更に伴うものとざっくりとした答弁をさせていただきましたけれども、国は平成２５年に避難の位置づけについて曖昧だということは国自身が問題意識を持っているというところでございまして。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"「ちょっと雨が降ってきたな。大丈夫かな」と気にしていると思いますので、場合によっては平素のときから広報などで知らせて、事前に知らせておくこということが大事なのかと思うのですが、今回そういったことは必要ないという判断なのでしょうか。","respondent":"和田河川下水道課長","answer":"現在、年度内をめどにこの辺の整理をする予定です。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"東京都へ氾濫危険情報の発信表現についての申し入れということなのですけれども、今、現時点で東京都の態度はどうなっているのかということと、結局これ、氾濫発生水位とか、氾濫危険水位、東京都の発令が出されたらより区民にとって危険ということですが、品川区の基準より東京都の氾濫危険水位のほうが危険ですから。","respondent":"和田河川下水道課長","answer":"１つ目、東京都の態度ですけれども、申し入れを続けておりますが、システムの変更が必要だとか、そのような理由をもってすぐに対応できないという回答です。これについては、引き続き申し入れの声を強めて、早く対応していただくように申し入れを続けていっているところです。","id":"exchange-057"},{"speaker":"筒井委員","kind":"意見","question":"今年の夏、あと秋の始めあたりに台風とか、ゲリラ豪雨とかの危険の発生もあり得ますので、一刻も早い対処をお願いしたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"今も質問あったのですけれども、東京都へ目黒区という位置をきちんと表現してほしいという申し入れで、なかなか難しいところがあるかと思うのですが、強さというとテロップがテレビにばんと出てしまえば、そちらのほうを区民の皆さまが見るケースが多いものですから、多分動揺してしまう。ホームページ、ケーブルテレビもつけないとわからないという形なので、ここはもう少し工夫がないかと思うのです。","respondent":"松代防災まちづくり部長、和田河川下水道課長、鈴木防災課長","answer":"これまでのことでまずご理解いただきたいのは、資料のＡ４の縦のほうですけれども、見ていただいてわかるように。今回の説明内容の周知の方法につきましては、１２月までにわが家の防災ハンドブックの改訂版を出す予定です。その中に今回の情報を入れる予定です。区民の方のボランティアや町会の参加も一部ですが入っておりますので、今後訓練の中で啓発するのか、もしくはそれをきっかけとして各防災組織の本部長。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"大分、水対策というのはできてきたのかと。以前は目黒川はよく氾濫して、警告が出されましたけれども、大分少なくなってきたと思うのですけれども、被害があるところについては多分、自分たちも「ここは危ないんだ、水が出るんだ」というのはかなり周知されていると思うのですが、その周知と、あとは防災訓練ですか。","respondent":"鈴木防災課長","answer":"水防訓練。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"各会派からの調査事項の要望、項目を見させていただいたのですけれども、最終的にこの調査項目で、正副委員長で調整した理由みたいなものをお伺いしたいのと、それとあと、私どものほうで出させていただいた住宅の耐震化と感震ブレーカー普及の推進ということを挙げさせていただいたのですが、あと、先日、請願の審議もありましたが、特定整備路線に対してもきちんとした、品川区内の事業ですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２件、調査項目、これで了解いたしました。リサイクルの状況もいろいろなことをどんどん進めていただいている状況も少し意識しておいていただきたいということもあって、その辺を入れたのです。調査しなくてもいいですけれども、何かのときに報告事項の中で入れてもらえれば。これをちょっと頭に入れておいて、委員長のほうで諮ってもらえればということでお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"それと、公営住宅の問題でいいますと、昨日も議論がありましたけれども、全国では民間賃貸住宅の家賃補助をしているところがあります。いっぱいあってすみません。その一方で、防災という機能と必ずしも相反しないと思っていまして、そういったところを同時に、路地を活かして防災に強いまちづくりを進めている自治体がありますので、そういったところをぜひ視察に行けないかと私の提案をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"鈴木（真）委員","kind":"質問","question":"日程を見ると、１０月下旬ということで考えているわけですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"鈴木（真）委員","kind":"質問","question":"日にちとしては２６日、２７日、２８日の３日間しかないという前提でいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その面で、品川区と、区の職員の方も行っていらっしゃる宮古市の津波、この前の委員会の中でも、昨日の委員会でも津波という言葉が出たのですけれども、私ども自民党は行ってはいるのですけれども、品川区の津波と宮古市の津波、違いが大きいところもあるのですけれども、状況と、できれば復興状況等も確認できればということで、それと水害も含めて防災ということでは東北方面に行ってみたいというのが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"品川区もある程度先進的なまちだと考えています。ですから、せっかく行政視察に行くということでしたら、品川区より先進的なまちづくりをやっているところ、もしくは似たような環境のところがいいと考えております。ですから、東京都の湾岸区部でもあるお隣の港区とかでもいいかと思いますし、また、ある程度の名古屋とか、大阪とか、神戸とか、水に接したまち、そういったところでもいいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"つる委員","kind":"意見","question":"大きくは防災対策という考え方になると思いますが、先ほど報告事項の中に集中豪雨に関連する文書の中でも、昨年の広島の土砂災害とか、あとは、先ほども申し上げました平成２５年の大島の大規模な土砂災害、現地を見て、当然品川区、都心部におけるそうした、先ほど崖の報告がありましたけれども、被害が想定されるものというのは全然想定が違うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"西本委員","kind":"意見","question":"せっかく自衛隊からということで担当部長に来ていただいたこともあるので、例えば宮城とか、松島とか、あちらのほうを経由して上に上がっていくのか下に下がるのかよくわかりませんけれども、ああいう形であると全体的な、今つる委員からもいろいろな部署との関連性を含めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"}]},{"id":"topic-06","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これは理事者のほうの答弁ではなくて、議員からの質問の中で入っていた内容ではあるのですけれども、今実際どういうところまで来ているのかというスケジュール的なところですが、それと、ＪＲとの話し合いというのがどういう形でもたれていて、どういう感じなのかと、うまくいっているのか、ＪＲの考え方もあるでしょうし、品川区としての考え方もあるでしょうし。","respondent":"溝口都市開発課長","answer":"解体するに当たっては、一番の課題としては、解体した資材とか廃材をどのような形で搬出するのか、また、社宅の下にはりんかい線が通っておりますので、その上を慎重に解体しないといけませんのでその辺の方法、そういったものについて鋭意検討を進めていると聞いているものです。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"２年間ということは、平成２７年途中に何とか解体を始めたいということだということなのですが、そうすると、これは相手様の話なので、こちらの要望というのはあまり言えない話なのかと思うのですけれども、大型保育園の建設もある中で、そこら辺の協議も、同じ敷地内だと思うので、そこら辺も含めた形で安全性とか、そういうことも考えて進めていっていただけるのかというところと、それから。","respondent":"溝口都市開発課長","answer":"ただ、私ども、品川区が持っている区有地もありますので、企画調整課を中心にまたそういったところも含めて、全庁的にそういったものも検討をしている段階ではありますが、一義的な窓口としては都市開発課で、協議会につきましては一番トップを副区長がやっておりますので、要所。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"副区長はどちらの副区長ですか。それと、あともう一つ、最後に、品川区のマスタープランがあると思うのです。それと、ＪＲの描いているのがあると思うのですけれども、そこの乖離というのはかなりあるものなのか、そこら辺だけ教えてください。","respondent":"溝口都市開発課長","answer":"当敷地、区の中心である大井町のまちづくりになりますので、当然行政としても私どもの課、１課だけで考えられるような話ではありませんので、さまざまな今後のにぎわいをつくっていきたいという観点でいきますと、それぞれ所管課が変わってきますので。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"これ、ＪＲのもともと社宅だったのをＪＲの意思で廃止にしようと自社で決めて、自社が活用するということなのですけれども、そこに品川区も近隣に種地があるということでかかわっていこうということだと思うのですが、最後のほうの質問に対する説明、もう一度お伺いしたいのですけれども、基本的には大きな土地を持っているＪＲが中心に進めていく計画なのかと思うのですけれども。","respondent":"溝口都市開発課長","answer":"品川区といたしましては、大井町駅周辺というのは品川区の中心でありますし、今後のにぎわいづくりですとか、そういった上位計画で位置づけたものを実現していくために非常に重要なところだと考えていますので、そういったところで基本のところとしましては。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/967161?Template=document&Id=4140#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":67601,"voices":218}},{"id":"h27-20150630-9","meetingId":"h27-cm06","date":"2015年6月30日","dateIso":"2015-06-30","committee":"文教委員会","time":"午前１０時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","topics":[{"id":"topic-01","title":"平成２７年度新入学学校別増減要因一覧","agenda":"平成２７年度新入学学校別増減要因一覧","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この一覧は毎年出されているのですけれど、これって、すみません、そもそも何のために出されて、ここから何を見るものなのかをちょっと伺いたいのですが。","respondent":"野呂瀬学務課長","answer":"委員もご承知のとおり、プラン２１が始まってから、学校選択制というのが一つの大きな柱ということでやっております。各学校の傾向をずっと出しておりまして、前年度に比べてどういう傾向であったかというのを、統計をとっております。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうするとこれは各学校も、これを参考にというか、こういったデータで準備を始めたりするというものにもなっていくのでしょうか。教育委員会だけでなく、学校自体にもこれはデータとしてあるのでしょうか。","respondent":"野呂瀬学務課長","answer":"校長連絡会等で同じ資料を出して、お知らせしています。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"小学校、中学校ともに昨年並みで、大きな変化はなかったという評価をされていますけれども、中学校のところで私立学校が若干減っているということですけれども、６２６人の方が私立に行かれていますが、この評価を改めてお伺いしたいのと、小学校、中学校は今、まちづくりで大幅に増えているようなところがあるのかどうか、そういった面でインフラが足りているか。","respondent":"野呂瀬学務課長","answer":"ただ、明らかに数年先に何人入ってくるというのは、住民基本台帳でわかるのですけれども、例えば再開発の説明会等で入ったとしても、この地域には何百戸の大型マンションが建つといっても、その中に就学されるお子さんがどれぐらい入ってくるか、その時点ではまだわからないと。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お隣の学校と比べたら本当に外見からも、中でいくら努力しても、やはり見た目は大きいよねというところにおいては、ぜひ格差をなくしていく方向で、改築というのはもちろんお金はかかりますけれども、どの学校も快適な環境にしてほしいと、そういう声はしっかりと受けとめていただきたいと思っています。それが一つです。なかなかこの表からはわからないので、ぜひ教えてください。","respondent":"野呂瀬学務課長","answer":"必ずしも校舎だけではないというふうに捉えております。もう一つ、今言った数字なのですけれども、ちょっと手元に今ないので、今はお答えできないので、申しわけございません。","id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"質問","question":"もう一つは、学校によって規模があるので、例えば住民基本台帳でこのぐらいの人数がいる、私も知らないのですけれど、幾つかの小学校で、もともと学級があまり多くない学校で当然人数は少ないだろうなとか、大きいから人数は多いだろうなとか、キャパシティーが多くてたくさん入れるのにあまり入らないとか、あるいはもともと小規模校なのに人気があっていっぱいだとか。","respondent":"野呂瀬学務課長","answer":"この表はそれでなくてもダーッと数字がありますし、一覧表にした増減要因があって、最終的に入学者数が幾らかという結果、それと各学校というのは、もちろん自分の学校を見ていただくとき、各学校の校長先生はそれで把握しているということで、あくまでもそれが見やすいか。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これ、スケールというか、例えば担任とかクラスの数とか、多少調整するということは可能だと思うのですけれど、もともとキャパシティーとして３クラスつくれそうなところとか、もともと１クラスしかつくれないところとか、そういう規模、スケールみたいなものをある程度、それはこの登録者数で見るというか、これで判断するということなのでしょうか。","respondent":"野呂瀬学務課長","answer":"この表は増減要因の一覧ということですので、各学校の規模とかはまた別にありまして、親御さんたちには学校案内等で周知しています。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"毎年この表を拝見すると、気になるところが荏原平塚学園なのですけれども、前に文教委員会で質問させていただきましたけれども、小学校は増のほうが多いということで、中学校のほうは格段に減っていて、私も荏原平塚学園の前の学校の出身で、当時の状況から、いろいろな確執があったというのは存じ上げているのですけれども、この傾向というのはまだ。","respondent":"野呂瀬学務課長、渋谷指導課長","answer":"そういう取り組みはやっておりますので、委員おっしゃるとおり、前からこういう傾向でという、徐々に徐々に今後上がっていくことは、教育委員会としてもいろいろな方策で支援していきたいと考えております。その学区域、１小２中が一貫校になっているほかの６校とは違う特殊なところが、かなり影響していると考えております。","id":"exchange-007"},{"speaker":"浅野委員","kind":"意見","question":"せっかくのいい施設でありますので、何とかいい意味で生徒数が増やせるような努力を、これからも続けていっていただければと思います。あそこの施設は、いろいろな場面で区民の皆様の憩いの場としても使われておりますので、そういう意味では皆さんに愛される学校に、これからもよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"学級増にするか、それとも教員を加配するかという判断を、小学校、中学校されていると思うのですが、この質問をしていいかどうかもちょっとわかりませんけれど、分類が違うとあれなのですけれど、加配を選択するなどの小学校なり、中学校なりの事情と、この数字からそういったクラス数が出てくるので、クラス数に関係があると思って質問するのですけれど、加配をすることの学校の判断の基準。","respondent":"野呂瀬学務課長、村尾教育総合支援センター長","answer":"中学校の場合は、集団でやるといいますか、いわゆる各組対抗となりますと、今まで３クラスだったのが４クラスになるとか、２クラス、２クラス、２クラスだったのが１学年だけ３クラスになると。３クラスが４クラスになった場合、教室が３つしかなくて階が上になったとき、学年経営としては難しいということで３クラスにするとか、また先ほども言いましたように、運動会でほかの学年が全部３クラスでそこだけ４クラスになると。","id":"exchange-009"}]},{"id":"topic-02","title":"平成２８年度新入学者の取扱い","agenda":"平成２８年度新入学者の取扱い","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"それはいいのですけれど、そうできないところが出てきているわけで、それを保護者の方にこのまま出すのではなくて、クラスが減って１クラスの人数が多くなってしまうじゃないですか、そういうふうになることもありますよというのを、何らかの機会に説明をして、おそらくご存じない方が多いと思うので、それで学習環境が悪くなるとかという意味ではなくて、そういうふうになる可能性もあるということも。","respondent":"渋谷指導課長","answer":"基本的に、最終的に入学者数が確定した段階で、そのボーダーラインの学校は、２学級になるのか、３学級になるのか非常に微妙なところについては、最初に入学をした段階で保護者の方に、こういう事情で学級数をこういうふうにしています。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"今のところで似通った質問なのですけれども、小学校は平成２７年から２８年で２,４９７人から２,８７０人に増える見込み、中学校は１,５５０人から２,１７５人ということで増の傾向が、今後についてどうなのかなと思うのですが、そういった中でこの表によると、第三日野小学校は４クラスから可能数は３クラスに減っていたり、延山小学校も３クラスから２クラスに減っている。","respondent":"野呂瀬学務課長","answer":"いずれにしましても、就学人口のシミュレーションとか通学区域の予定者数というのは、こちらとしても細かく把握して、対応するような形でやっております。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"今、延山小学校と第三日野小学校は、当初の予定よりも通学区域内の子どもが増えたので増やさざるを得ないですよね。そういった意味においては、キャパ的には可能性はあるという、予定は立てていても可能性はあるということで、受けとめてよろしいでしょうか。通学区域の子どもが増えたら、この予定のクラス数よりも増えることは可能なのかどうか。","respondent":"野呂瀬学務課長","answer":"通学区域の子どもでそこの学校に行きたいという方は、全員入れなければいけないと。それでクラス数が増えるのであれば、増やしていくような形で。","id":"exchange-012"}]},{"id":"topic-03","title":"体力向上推進事業","agenda":"体力向上推進事業","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"その点、非常に東京都の中学生の体力がないというのはよくわかるのですけれど、例えば東京都の中で、２３区で、区によって違いがあるとかいう資料があるかどうかということと、あと同じ最下位グループで、ほかにはどんな都道府県があるのか、その２点をお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"具体的に公表はされていないのですが、２３区内でいうと、小学校でいうと現在８位程度、中学校では１５位、この結果がひとり歩きするとまずいのであれなのですけれども、この辺に位置づいているということでした。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校ごとの、全部がというのでなくて、かなり頑張っている学校をホームページとかで公表して励みにするみたいなことについて、お考えかということと、ワンミニッツエクササイズもそうですけれど、スポーツトライアルとともに保護者に伝えると、ご家庭でも簡単にできることだと思うのですが、先ほど協力してもらうというお話がありましたけれども、具体的に保護者の方へどのように説明していくのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"品川スポーツトライアルですけれども、いろいろ難しい種目をやっても、なかなか子どもたちは、もともと体育というか運動が嫌いな子にどうやって休み時間とかを使って運動させるかということで、本当に簡単なスポーツ等をやりながら。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう一つは、本当に父母の皆さんの協力、一緒になって小さいときからの体づくりが一生にどれだけ大事なのかというところ、食生活も含めてですけれどもやはり一緒に考えていただく、押しつけるのでなくて一緒に考えていただくというところへ、ぜひ力を入れていっていただきたいと思いますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"それは子どもたちにとってすごく大切になりますし、現在運動不足や生活習慣病とかいろいろな問題が絡んでくる中で、この運動また意欲や気力の低下といった精神的な部分についてもやはり体力というのはとても大切だということを含めて。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"各学校で取り組みながら、記録を学校や個人間で競うというところで、子どもたちに運動をいかに好きになってもらうかという部分では、できる子たちはじゃあ、もうちょっと頑張ってもっといい記録を目指そうとか、表彰されるようにと思うのですけれど、先ほどもちょっとお話があった、あまり運動が得意でない子たちが、その記録や個人賞を目指そうというふうにはなかなかならない中で。","respondent":"村尾教育総合支援センター長","answer":"委員おっしゃったことはまさに体力向上検討委員会でも、やはり結局、体育が上手な子が記録をとっていくのではないかということで、危惧されていました。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"フラフープやってもそうだし、竹馬やってもそうだし、何やってもできちゃう子はできちゃって、やっぱり何もできない、どれも得意じゃないという子たちをどうするかというところは、非常に考えなければいけないかなと思っているのですけれど、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"そのために一つの手だてというのが、２人組とか３人組で何か種目を考えてみて、できる子が誘って一緒にやって、達成感を味わうとか、そういう方法も今検討しているところではあります。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"別なのですけれど、例えば先ほどもほかの委員から、休み時間での運動というのは、今の子どもたちがどういう運動をしているかわからないですが、どういったことがよく学校で、運動として子どもたちがやっているのか、何か例があったら教えていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"ただ学校によっては、縦割り班活動を入れてみたりということで、例えば鬼ごっこをやってみるとか、ケイドロとか、各学校でさまざまな取り組みはしていますけれど、実際にそれは遊びの中で、なかなか入っていけない子どもが見られるというのが現状だと考えています。","id":"exchange-018"},{"speaker":"大倉委員","kind":"意見","question":"先ほども、できる子たちはそうやってできる子たちで集まって、いろいろな運動をしていくという中で、今おっしゃったようにそこになかなか入れない、そういう子たちが割と運動が苦手だということを考えると、一緒にやりましょうねというところをぜひ、やっていっていただければ、みんな一緒になって遊べるようになっていくのがいいのかなと思うので、ぜひよろしくお願いします。","respondent":"村尾教育総合支援センター長","answer":"まさに学校というか区全体で、とにかく子どもたちの体力をというのが一つの目的でもありますし、やはり体育、運動が苦手といっても実は達成感であったり、自分はこれはできないけど、これだったらどうにかできそうだというものについては、まさに委員おっしゃるとおり。","id":"exchange-019"},{"speaker":"浅野委員","kind":"質問・要望","question":"モデル校１０校、テクニカルアドバイザーを配置する学校ということで指定されていますけれども、小学校、中学校ともありますけれども、これらの学校については何か意図というとおかしいですけれども、基準が何かあって決められたのか、それとも抽選か何かで決めたのか、何か思いがあって、またデータとかそういうことを比べるとか、そういうことを考えた上でやるのか、そこら辺の意図がもしあれば。","respondent":"村尾教育総合支援センター長","answer":"モデル校の選定につきましては、基本的に校長または副校長が体育の専門であるというところが一つ、それからそれ以外に学校のほうで、体力づくりで先進的な取り組みをしているという学校を選定し、この１０校ということで決定いたしました。","id":"exchange-020"},{"speaker":"浅野委員","kind":"質問","question":"選定の仕方もいろいろあるかと思いますけれども、この１０校の結果をもって、ほかの学校にも展開されていくかと思います。そういう意味では体育が専門でない校長、副校長のところも選んだほうがよかったのではないかと実は今、話を伺って思って、そこに差があるのかどうかということを見られれば、またそういう学校に指導ができるのかなと、ふと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"２番の現状と主な要因のところで、運動する機会の減少だったり、指導者の指導内容の差とか、１日の運動量の低下ということが出されているのですけれども、区としては、これは何でこうなっているのかというのをどう考えているのか、伺いたいのと、体力向上検討委員会は、説明の中で聞き逃していたら申しわけないのですけれど、これはどこがつくっていて、メンバーはどんな方で。","respondent":"村尾教育総合支援センター長","answer":"１日の運動量が低下していて、子どもたちは特に中学校に上がると、なかなか運動しないというようなこと、まさにここに書かれている要因以外にも、出されたものとしては、運動の二極化ということで運動する子としない子がはっきり分かれ始めているとか。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区独自でプロジェクトをつくったということで、学校の中でもそうですけれど、外でも子どもたちが運動やスポーツに親しめる場というものを増やしていくべきかなと、これを見て思いますし、自分たち自身、大人たちもなかなか忙しい中で、スポーツに親しむ時間も場所もないということでは一緒かなと思うので、ぜひこういったプロジェクトをはじめ。","respondent":"村尾教育総合支援センター長","answer":"今、委員ご指摘のとおり、時間とか場がないという、これはすぐに解決するような問題ではなかなかなくて、まずは喫緊の課題として、やはり学校の中で、それも体育の授業また休み時間と放課後を使って、どうやってまず子どもたちにこの取り組みができるかということを。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"健康プランとの絡みはないということですけれども、やはり区民の健康や体力向上を進めていくというところでは、やはり連携していくといいのではないかと思いましたので、ぜひ区全体で進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"確認","question":"何点か質問させてください。予算が幾らかということと、東京都の補助なりがあるのかということとその場合の金額の確認。","respondent":"村尾教育総合支援センター長","answer":"予算的には今年度、モデル実施ということもありますけれども、総予算でいうと７８０万円の予算計上をしております。具体的には、大まかには報償費ということで、特にテクニカルアドバイザーを各モデル校に配置していることで、お金を組んでおります。","id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問","question":"おそらく今年度の７８０万円というのは、このモデル校の金額だと思うので、そうすると来年度以降は当然これが増えていくわけでしょうから、そうすると今お話しされた最後の検証結果は非常に、議会としても注目していくので、しっかり対処してくださいということでお願いをしておきます。その辺の整合性をどういうふうにとっていかれるのでしょうか、ということをお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"そこに整合性を踏まえながら、教員１人で３０何名の体育の授業をやってきたものを２人で、特に跳び箱であったり、鉄棒であったりというのは模範的なものを見せられるので、その辺について教員が個別で対応できるような、そういう仕掛けを今考えているところです。","id":"exchange-026"}]},{"id":"topic-04","title":"荏原図書館の開館","agenda":"荏原図書館の開館","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"蔵書ですけれども、今までと同じといってはおかしいですが、同じような形でまたこちらのほうに持ってこられるのかなと考えていますけれども、そこら辺の変更があれば教えていただきたいのと、またほかにも新しい取り組み、何か工夫をされたところとかあれば教えてください。","respondent":"木村品川図書館長","answer":"工夫につきましては、レイアウトそのものも本当に一新いたしますので、見やすく、それから品川図書館で今導入している、本の消毒器ですね、それも入れる予定をしております。工夫と言えばそういうところになります。","id":"exchange-027"},{"speaker":"浅野委員","kind":"質問・要望","question":"これからも地域の方々に愛される図書館を目指していただければと、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-05","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと聞き漏らしてしまって、開設の予定日が遅れたというのは、土中に何かあったという話ですが、ちょっとそこをもう一回お話しいただきたい。契約が国から区の契約をして、また区があざみ会と契約、この契約の中身をもうちょっとわかりやすく教えてください。","respondent":"今井待機児童対策担当課長","answer":"２点目の定期借地契約ですが、定期借地契約ということで財務省になりますけれども、関東財務局と区の間でまず定期借地契約を結んだ後に、今度は区とあざみ会との間で定期借地契約を結ぶという形の、２段階の転貸ということになりますけれども、こういう形での契約です。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"この開設準備経費助成は中身的には、どういった中身なのかもう少し詳しく教えてください。","respondent":"今井待機児童対策担当課長","answer":"くりのき保育園に係る施設整備費は、２億円余という形になっております。ただ平成２６年度と２７年度に分けて工事を行っておりますので、平成２７年度につきましては、現在６,０００万円の予算ということで計上しています。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"保育園建設の工事期間はどれぐらいかかっているのかと、８３２.３６平方メートルなのですが、園庭の大きさはどのぐらいあるか、わかったら教えてください。","respondent":"今井待機児童対策担当課長","answer":"工事自体は１０月中旬までには完了するということで、予定しています。大体７カ月ほどということになっております。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"工期が大体、実質的には７カ月と、このぐらいあったら９０名規模の保育園は大体、このぐらいの工期でできるのでしょうか。","respondent":"今井待機児童対策担当課長","answer":"これはあくまでも着工からでございまして、着工の前に建設ですとか施設計画が、大体今でも３カ月から４カ月ぐらいは協議を進めておりますので、着工からの期間ですと、今、７カ月ぐらいで予定はしています。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問・要望","question":"非常に感慨深いものがあるのですけれども、やはり長い時間がかかるものだということを改めて感じております。面しているところはかなり太い道路もあるのですけれども、裏側の道というと怒られるのでしょうけれど、ゼームス坂通りのほうから来る道はかなり狭いと思いますので、安全対策のほうは考えられていると思いますけれども、そこら辺の考え方をちょっと教えていただきたいと思います。","respondent":"今井待機児童対策担当課長","answer":"どうしても自転車で来られる方が多いということがありますので、必ず園庭も含めて敷地内に自転車を引き込みまして、そこで乗り降りができるような工夫をきちんとしています。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"今の質問と関連してですけれど、そうすると入り口は長い辺の右側のほうになるのでしょうか。言われたとおり細い道で、しかも車の通りが多い道路なので、歩いてくるのも、自転車に乗ってくるのも結構大変な道なので、そこら辺が心配だなというのは感じていたのですが、自転車等も引き込めるようにというふうにおっしゃっていましたけれども、園の中にそういった空間があるということでしょうか。","respondent":"今井待機児童対策担当課長","answer":"予定地のところの、委員ご指摘のとおり長い辺の、この地図でいけばちょっと後ろの、南品川の「品」が隠れているのですが、この字の上のところ、上から３分の１程度のところに入り口を設けております。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"意見","question":"この地域は、そこまで保育園が少ない地域ではないのですけれど、やはり国有地が保育園になるということは、私たちも歓迎しています。ぜひほかの国有地も購入していただきまして、増設していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"待機児童対策の中に含めていただきたいというか、ぜひ認可や認証、小規模保育所、それから事業所とかいろいろ出てきますけれども、ぜひ認可外の保育施設、品川区内の子どもたちにかかわっている保育施設というところをぜひ入れていただきたいし、待機児童対策として現状においてお力をいただいているところも含めて、どの施設でも子どもたちの格差がなくなる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"特に保育園の待機児童問題に関しては、区内で頑張ってくださっているさまざまな事業者、社会福祉法人もありますけれども、事業者の方々の意見もお伺いしたいし、実際に足を運んで現場を見せていただきたいというのもありますし、ぜひ保護者の方々との懇談会というのも実施できたらと考えておりますので、そういったことも新たに試みてはどうかなと考えております。ご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"浅野委員","kind":"提案","question":"きれいな日本語だったらいいのですけれども、やはり大分崩れてきているところもありながら、きちんとした日本語、ことわざも含めてやっていっているという、また小中一貫教育の柱としても位置づけていますので、こちらのほうはどうかなと考えています。場所は離れていますけれども、どうかなと思って提案だけします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"伊藤副委員長","kind":"提案","question":"そんなことを勉強したらどうなのかなという提案をするのと。やはり南三陸町は多いですね。被害も大きかったのでしょうけれど。そのようなことを、私たちとしては提案させていただきたいと思います。福岡市の道徳教育推進事業です。これは非常に、私としては勉強していきたいという思いがあって、提案させていただきました。北と南で随分方向違いですけれど、提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"意見","question":"小中一貫教育と絡めて、コミュニティースクール学校支援体制というので、出雲市が進めているというのがあったので、所管事務調査と直接かどうかあれですけれども、参考になるかと思いました。公立保育園、幼稚園等の民営化を進めているところが幾つか、札幌、千歳、広島、仙台、京都、岡山、それぞれいろいろな状況や背景とかあるのですけれど、どういう状況かというのを研究するのはと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"日程というか、視察というと２泊３日ということなのですけれども、内容によって、無理をしてというわけではないですけれども、２泊する必要もなく１泊で帰ってきてもいいかなと。場所と内容によるかと思いますので、皆さんの予定があるので２泊３日で確保しておくのは構わないと思いますが、内容が固まり次第、その辺も議論にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"飯沼委員の質問内容への、政策目標という答弁の具体的な意味合いを知りたいと思います。それと、１,０１５人の内訳ですね。年齢と親の就労、そこを具体的にしっかり捉えていきたいと、教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"意見","question":"政策目標というのは何なのか。意味合いを、政策の目標とおっしゃったので、それは単純にどういう意味なのかということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうです。そこも、２１５人の内訳を話されたので、１,０１５人の年齢別、そして親の就労状況というのを聞いたので、そこの答弁がなかったので教えてくださいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"提案","question":"今の後のほうなのですけれども、区としては待機児童のところで、２１５人の中で把握している、私は保育園を希望して入れなかった１,０１５人について伺ったのですけれども、なぜここを伺った理由と、質問の趣旨が、やはり今までどおりの政策目標を掲げていますけれども、今までの計画、対策では足りないので、新たに提案という意味も含めて、港区で行っているように申請の書類の中から。","respondent":"今井待機児童対策担当課長","answer":"ご本人による所管質問ですので、それにつきましてはやはり、確認をさせていただきたいと考えていますけれども、まず第１番目に、本会議のところですけれども、待機児童の解消は政策目標であり、現行の子ども・子育て計画におきまして。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２８年度末というのはこの間ずっとお答えいただいているところですけれども、これでいいのですかという質問なのです。答えていますというのでなく、もう再三、平成２８年度というのはいただいていて、それで解決するのですかという質問であって、共産党としてはこの間、認可を求めていますけれども、総合的な施策の中に認可保育園も入っている。２１５人。改めてそこの点を聞かせてください。","respondent":"今井待機児童対策担当課長","answer":"昨日ご答弁申し上げたとおり、平成２８年度につきましても、今予定している６２０のうち、認可保育園での開設につきましては５８０という形で、目指しております。認可保育園というものをある意味ここは柱として、開設を進めているというのはご理解いただければと思います。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だからそこをどうするのですかというのが再三の質問なので、決して満足していませんよね、でも努力の文字だけでは解決しないと思っているので、共産党としてはこの間、今までやっている施策にプラスして、認可保育園の増設のところに力を入れてほしいと言っているわけですけれど、この間、共産党は２０園の増設をという数字も出しておりますので、ぜひ今よりも、努力はもちろん認めます、でも足りない部分。","respondent":"今井待機児童対策担当課長","answer":"先ほどご報告いたしました旧国家公務員宿舎の跡地を初め、今回の区有地を活用しての開設など、これまで取り組んでまいりました定員の拡大も含めて、政策を緊急にここ一、二年で打ってきたところです。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/111718?Template=document&Id=4858#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":37065,"voices":138}},{"id":"h27-20150630-5","meetingId":"h27-cm06","date":"2015年6月30日","dateIso":"2015-06-30","committee":"総務委員会","time":"午前１０時００分～午後 ３時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","topics":[{"id":"topic-01","title":"第５５号議案 平成２７年度品川区一般会計補正予算","agenda":"第５５号議案 平成２７年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"冒頭に、緊急かつ対応と、あと新しい課題や追加の事業についてというご説明がありましたけれども、この間の第２回定例会での補正とは何が違うのか、その性質の違いも伺いたいと思ったのです。なので、今回の補正の性格の違いは何か、こういう補正を組んだ事情だったり背景だったり、その意図は何かをまずご説明いただけますでしょうか。","respondent":"秋山財政課長","answer":"先ほど冒頭にもご説明させていただきましたように、例年、第２回定例会では、ここ何年かは緊急で、それこそ３.１１に対応して震災対策を行ったりとか、景気対策であるとか、そういう緊急の事態を受けて補正を組んできたという例年ではございました。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは今後よく検討していただきたいと要望しておきます。たくさん事業がありますので、全部とは言いませんけれども、とりわけスピード感を持ってやりたい、品川区のプラスをさらに伸ばしたいという区長の思いには、補正予算のどの事業がその特徴として表われているのかを伺いたいと思います。","respondent":"秋山財政課長","answer":"あの場所をどうやって使っていくかということで、一定の講習の場所というのができますので、そこの部分を使って、より効果的に地域の防災リーダーを育てるための教室ができるというような形がとれるということがわかりましたので、防災学校の開校に合わせて。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"本題の補正について伺いますけれども、まず、総務委員会所管分としては、おそらくＷｉ－Ｆｉスポットと新公会計制度導入経費の２つなのかとは思うのですが、Ｗｉ－Ｆｉスポットで６公園に広げる主な理由と、新公会計制度導入というのはどういう事情が生じたのか、その概要を伺いたいと思います。","respondent":"秋山財政課長、仁平情報推進課長、福島会計管理者","answer":"最初に、「ふれあい」で未来事業という話があって、それに対してコメントですけれども、新しい事業ですとか課題に対応するためというのは。国のほうは、２０２０年の東京オリンピック・パラリンピックに向けまして、Ｗｉ－Ｆｉの整備を進めていくとされております。それに応えるために、今回、品川区が対応しようということで、この検討経費を計上したものです。私のほうから、天王洲の検討の経費についてご説明します。天王洲については、いろいろ課題はありました。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"初めに、当初予算とともにスピード感ということですけれども、このスピード感がいわゆるトップダウンにならないように、議会には丁寧に説明と資料を要望しておきたいというふうに思います。番号法のことですけれども、現時点では、結局、情報がなぜ漏れたのか、それに必要な対策がどうあるべきなのかが示されていない以上、住民の不安が払拭されないのも当然だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"幾つかお伺いしたいと思います。そうすると、１００％自腹ですぐにやるのがいいのか、ちょっと待って国から支援策が出てきてからやってもいいのではないか。出るかどうかわからないのですけれども、その辺のご判断、あるいは、なぜこれが１００％なのかということをお伺いしたいと思います。","respondent":"福島会計管理者","answer":"検討を始めている区もほとんどでありますので、決して品川区が早いということではないのですけれども、このタイミングでやらないと平成２９年に間に合わなくなってしまうということもありまして、今回、補正をさせていただいたというものです。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"今のご説明だと、補正でというよりも、当初予算に乗せても全然おかしくないようなタイミングに、品川区の立ち位置としてはあると思います。もし間違っていれば、ご指摘ください。理由はともかく、これは特殊な判断、あるいは今回限りの判断なのか、今後もどんどん、こういう細かいものまで補正でつけていくという考え、ある意味、方針を少し変えていくということなのか、そのお考えを教えてください。","respondent":"桑村副区長","answer":"なかなか難しい答弁になると思うのですけれども、一つは、予算というのは、今まで年度予算ということで、これはこれまでご説明したように、年度間のものを当初予算で設定するということで、やはり補正というのはある程度、例外措置といいましょうか、国からお金が来るとか。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"ご答弁ありがとうあります。道路維持費１０億円の中で１００万円は、本当に補正で組むものなのかというのはちょっと、とすると、補正で上げることと、流用で対応していくこととの、境目というか基準というものは何かあるのでしょうか。金額的なことを言えば、ステッカー一つつくるのに補正でなくてもいいではないかと考えるのですけれども、何かそこに本質的な切り分けがあるのであれば教えてください。","respondent":"桑村副区長","answer":"今回は、なるべく入れて、逆にご判断をしていただいて、こういう事業をこれからやらせていただきたいということを明らかにして進めするというような内容になっているので、ちょっと毛色が変わっているといいますか。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"額が少額であっても、新しい事業を始めるというアピールのために、あえて補正にしているというふうに受けとめましたが、それでよろしいでしょうか。それと、最後、先ほどのご答弁の中で、区長選があって間に合わなくて、積み残しでというお話もありました。区長選に区役所の力を割き過ぎている部分がないでしょうか、これは感覚的な質問ですけれども。","respondent":"桑村副区長","answer":"実際、作業的には８月ぐらいから予算編成を始めるわけですけれども、区長選が１０月になりますと、新しいものというのは、それまではほとんど対応できないというのが実際のところでありまして、決まってから初めて、どう組んでいくかということになりますので。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"一発目に、当初予算ができたから、もう当面、この１年間、動かないというのはおかしな話で、民間の企業でも刻々と毎月毎月、議論しながら予算をそこへつけたり、いろいろ政策的に対応していると思いますので、今後もこれはやらなければいけない、またアピールするものがあったら積極的にやっていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"私も、新公会計制度のところで伺いたいのですけれども、先ほどもご答弁の中にありましたが、複式簿記を導入するということで、私は新人議員研修のときに、区民向けのざっくりとしたものですけれども、バランスシートが出て、見せていただいて、複式簿記を導入しないでどうやって今までバランスシートをつくっていたのですかと伺ってしまったのですが、複式簿記を導入されることは結構だと思いますが。","respondent":"福島会計管理者","answer":"こちらにつきましては、妥当な経費だと考えていますし、これほど大きく公会計制度を変えていくということになると、多分、システムをつくるとなるとさらにもう少し大きな金額がかかると思いますけれども、それを変えていくための初めの経費ということで。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"だから、結局、これはほとんど委託費ということでよろしいのですか。システムを変えたりしなければいけないとかということには、また新たに経費がかかってくると判断してよろしいのでしょうか。","respondent":"福島会計管理者","answer":"その経費についても、今回の検討の中で、どういうシステムを導入すれば費用対効果も含めていいのかというところの検討もしたいというふうに考えております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"意見","question":"そのほか、評価すべきものとしては、例えば認知症対策プロジェクトや各種アプリの導入、また都市計画公園を使った保育園の建設であったり、医療障害児支援であったり、いわゆる厚生委員会の部分だと。総合判断としては、やはり区政の大きな問題である番号法であったり再開発を進めるところは、とても容認できるものではありませんので、区政全体としては反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]},{"id":"topic-02","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"本文の下から４行目ですか、世論調査でとあるのですけれども、区民からの請願で出てきたものをきっかけとした意見書であるということを踏まえると、世論調査だけではなくて、区民の皆様からこういう意見が出てきているというニュアンスが出せないものかと。ただ、さらっと読めば、そんなに気になるところではないので、ここはスルーしていただいても構わないのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のあべ委員の思いはわかるのですけれども、具体的にどうしたらそんな形になるのかと思うと、例えば、４行目、「審議を十分に尽くすべき点があるとの意見が寄せられ、また様々に実施されている世論調査で共通に明らかになってきている」だと、意が酌めるのでしょうか。私が修正するのはあれだけれども、一つのアイデアとして述べたにすぎません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"私はさっと読んで、あまりひっかからずに、昨日の請願の趣旨に沿っているかと思ったのですが、あべ委員のご意見を伺うと、確かにその辺がもうちょっと明確になるといいというふうには思います。ただ、これは意見ですので、あとはこの場にお任せいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"一応、意見書を出すということで、今回、請願を出された方の意向を酌んで、あべ委員のおっしゃるとおり、確かに言葉とか、その辺のところでちょっと問題点はあるものの、これでいいのではないか、スルーしておけばいいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"あべ委員","kind":"意見","question":"皆様のご意見にお任せいたします。は正副にお任せいたします。","respondent":"松澤委員長","answer":"今、須貝委員が、これでいいのではないかと言われると、大体、多数のほうがこのままでいいのではないかという形にとられるのですけれども、明確に、これはこういう言葉にしていただきたいというのがあれば検討いたしますが、こちらも正副で検討したもので、皆様方の意見の中で。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"先ほど別の委員から出ました、「審議を十分に尽くすべきであるとの意見が区民からも寄せられ、また様々に実施されている」というふうに、共通にとなると、２つのものが並列されているので、ちょうど収まりがよいかと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"委員長の場合は、委員会の決定で行うべきだと思いますので、提出者は、委員会で採択された以上、委員長も提出者になるべきではないかと私は思います。区議会議員としてとは別に、委員長としての、委員会の意思ということですから、区議と委員長との区別としてと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"松澤委員長","kind":"意見","question":"本会議の席で、委員会報告で、この議事の内容については、委員長としての報告はいたしますので、意見書の提出については総務委員長という形ではないと思うのです。何々君という個人名で呼びかけられているように感じているのです。","respondent":"原区議会事務局長","answer":"その提案説明についても、委員長としての理由での提案説明というよりは、実質的には委員長になりますけれども、個人の議員の資格の中で提案説明というようなことがこの間行われておりますので、そのように理解をしています。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"議案を提出するのは、確かにそれぞれの議員が議員という身分で提出するというのはわかるのですけれども、総務委員会での報告という意味では、そういうことが報告になるのだということ、それが今、論点だと思うのです。その辺の説明がよくわからなかったのですけれども。それと、委員長の報告の兼ね合いなのだと思うのです。そこを議会運営上、どういう見解があるのか伺います。","respondent":"原区議会事務局長","answer":"意見書については、意見書の議案として、議員提出ですので、それについては、提案者になるか、ならないか、それから提案する場合については、提案説明をどなたが行うかというところで考えますと、提案者になっていないところの中で提案説明をするというのは。","id":"exchange-021"},{"speaker":"あべ委員","kind":"提案","question":"確かに委員会報告と議案については分けて考えて、委員長報告については、今回の決定というのは尊重した報告をしていただきたいと思います。ただ、民主主義ですから、たとえ自分の意見に合わないものでも、一旦、正当な手続きで決まったものは尊重するというルールがあるので、委員長の役職として行う委員長提案というのは、この決定の内容を尊重した報告を行うということの括りでよいのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"会派順に倣って、私でよければ、私でやらせていただきたいと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"品川区総合戦略の策定および地方創生交付金の活用事業","agenda":"品川区総合戦略の策定および地方創生交付金の活用事業","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"表の面の(3)の4)で、策定にあたっては区民をはじめとありますけれども、この区民の方々というのはどういうイメージなのか、あるいは、どのような形でどういった方々を選定していくのかというところを教えてください。","respondent":"柏原企画調整課長","answer":"区民代表という意味で、そういった方々にお声がけをしている状況です。加えて、先ほど申しましたパブリックコメントであるとか、アンケート調査についても、何か別の形で、例えばインターネットを使ったような形ができないかというのは、今、調整をしているといったところです。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"いろいろな方を挙げていただきました。いろいろな方ですけれども、一方で、これまで区とお付き合いのある方ばかりだという印象も持ちました。公募は、ほかには設けることはなくて、要は、こういった町会と民生委員と成人式の実行委員会のメンバーだった方のみが区民枠で入っていくということなのでしょうか。例えば公募とか、何かそういったものはもう入ってこないのでしょうか。","respondent":"柏原企画調整課長","answer":"公募という形では、現段階では考えていないといったところですが、今、委員がおっしゃっていただいたように、いろいろな視点、それから例えば基本目標であります結婚・出産・子育ての希望をかなえるというところも、ご意見の部分といったところで申しますと。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問・要望","question":"繰り返しになりますけれども、品川区というのは、非常に人口の流動も多いところですし、そういった意味では、今挙がった中では、どちらかというと長く住み続けている方ばかりの意見になってしまっても何かなと思います。もちろんネット調査やアンケート等々もあるのでしょうけれども、やはり品川区としての人口構成の特性というのも、ぜひ反映していただきたいと思います。ぜひ、工夫をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"策定委員会は、メンバーとしては何人になるのか。もう一つ、地方創生交付金の説明で、箱物だったり国費が入っているものは使えないということですけれども、要するに、区の単独事業のみなのか、どういう税金が入っているものはいいのか悪いのか、そこを伺いたいのです。建設費です。もちろん土地の購入費もですけれども、箱物、国費は使えないのに関連して教えてください。","respondent":"柏原企画調整課長","answer":"区の職員といたしましては、２人の副区長が入るということでございまして、１１人もしくは１２人ぐらいで、今、人数としてはなろうかと考えています。それから、後段のご質問です。結論から申しますと、このお金は使えない、認可保育園の建設費には充てられないというものです。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"策定委員会は公開か傍聴可能かを伺いたいのと、ぜひ開催の案内はできるだけ早く幅広く周知に努めていただきたいと思うのですけれども、その案内についてもどういう周知がされるのか伺いたいと思います。認可保育園には使えないと。箱物、国費が使えないというのは具体的にどういうことなのか、もう少し教えていただきたいと思います。国の大きな流れと、品川区もここで言っている地方に当たるのか。","respondent":"柏原企画調整課長","answer":"国費が入っていなければ、基本的には入れられる、ソフト面のところで入れられるのですけれども、ただ運営費ということになりますと、継続的な部分といったところもありますし、それから今回の重要業績評価、要するに数値目標といったところを定めるという規定がありますので。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区としては、確かにお金をいただけるのですから、それはそれでいいと思うのですが、遠い将来は別としても、ちょっと不思議な戦略、それに対して地方版総合戦略として、品川区のほうが努力義務とされるというのに非常に違和感を感じて、品川区は品川区独自の戦略で、品川区の自治を守っていって、それで反映させるというのが主だと僕は思うので、こんなふうに押しつけられて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]},{"id":"topic-04","title":"町会・自治会のあり方と区との協働に関する調査研究","agenda":"町会・自治会のあり方と区との協働に関する調査研究","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"ただ、このアンケートの中にもありますけれども、様々な仕事が各町会・自治会のほうに、さらに増えているのではないか、増え続けているのではないかということもありますので、その辺もちょっと酌んでいただいて、各町会が動きやすいように、少し身軽になれるように対策をしていただければありがたいなという意見を聞いておりますので、一応、意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"本多委員","kind":"質問","question":"２３ページの問２８、未加入者への加入呼びかけの取組なのですけれども、従来から、加入促進でできる限りのことはやってほしいという意見を出してきたのですが、何か一歩前進するような部分というのはあるのでしょうか。","respondent":"柏原企画調整課長","answer":"かなり未加入者への加入呼びかけの部分につきましてはものすごく苦労されているといったところで、先日来、このアンケートの内容等も含めて、町会・自治会のほうにご説明に上がったところですが、そういったところでも議論といいますか、話題になっています。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"私、詳しくないものですから、町会長と区政協力委員の関係というのは、どういうふうなしくみになりますか。","respondent":"柏原企画調整課長","answer":"区政協力委員といいますのは、そういった方々に、区民の方々と区の行政との間に立っていただいて、区の情報を区民の方に伝えたり、区民の方々の情報やご意見を区にいただいたり、そういう間に入っていただく方ということで。","id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"京都ですか、今、自治会が大変もめているところがあると全国ニュースになっておりますけれども、加入以前の問題として、結構、お金の問題が大きいみたいです。それで、町会長そのものというのは報酬がなかったと思いますけれども、区政協力委員というのは区から報酬が出ていたと思うのですが、これはどのくらいなものなのでしょうか。","respondent":"柏原企画調整課長","answer":"所管ではないもので、詳しい数字はあれなのですが、たしか一回１万円前後だったと思いますけれども、お支払いをしているということだったと思います。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"純然たる自治的な組織が地域にあるというのは、それはそれで、とても価値があることだと考えています。特に、これまでこの地域に住んでいなかった方が入ってきたときに、地域のことだけではない、いろいろな動きがあったりする。そういった意味でも、町会を今の世の中に合わせていくということについては、区は何かお考えをもっていらっしゃいますでしょうか。","respondent":"柏原企画調整課長","answer":"こちらの答申文のほうにも少し、２ページ目の最初のところに町会・自治会がより力を発揮しやすいしくみづくりの中段のところです、そこ以降三段書き分ぐらいですけれども、もちろん町会・自治会が中心的に今まで努力してきたところを。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ、そういった視点でも進めていただきたいと思います。町会長たちが、例えば、事実上、自動的に政治家の後援会に組み入れられるようなしくみがあるとすれば、それは町会活動にとっては、あるいは地域づくりにとっては、決していいことではないと思うのです。そういったことも含めて、ぜひ具体的に検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"町会会館がない、ずっと積み立てているものはあるのだけれども、やはり土地の価格と建物の価格となかなか折り合いがつかず、いつも懸案だという話を伺います。ここについて、何らかの手だてをしようという方向というのは、今後、出てくるものなのかどうか。現状も含めてお考えを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"具体的に町会会館を区がつくれるかということではないのですけれども、町会の皆様の運営に対して、例えば恒常的な管理的なところがいいのか、どういう部分がいいのかというのは、今、政策のメニューということでいろいろな部分から検討しているというところで。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"いろいろなアイデアやご意見を伺うのです。ぜひ、幅広く検討をいただけたらというふうに思うのですけれども、まだ検討中ということでありますが、改めていかがでしょうか。","respondent":"柏原企画調整課長","answer":"例えば、先ほどの公園の部分についても、木密の担当部会のほうはそういった視点を広げたりとか、そういう部分では実際に動いている部分はあります。同じ答弁にはなってしまいますけれども、検討を深めてまいりたいと考えております。","id":"exchange-037"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"例えば名和田先生、たまたま昨年、都市問題会議に行ったところで名和田先生の講演があって、地域コミュニティーをつくり上げるという実践的な取組みもされていて、田村部長も、その当時の教育次長もいらっしゃいましたけれども、お話を伺ったところで、そういう議論も非常にあったのではないのかというふうに思うのですけれども、そういう新しい取組みについて、これからなのかもしれませんが。","respondent":"柏原企画調整課長","answer":"負担感の話も、全てが全て、解消というのはなかなか難しいのですけれども、その整理の方向性を見出すことはできるということも議論になった。","id":"exchange-038"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"たしか名和田先生の実践の活動で出てきたのは、神奈川県の、まさにコミュニティー意識が希薄なようなところで、どうやってコミュニティー意識を形成していくかという事例だったので、今のお話だと、品川区では強力な地域コミュニティーが既に形成されているから、それを深めていくというようなご認識だと思います。これは新しい人を巻き込むという話なのでしょうか。","respondent":"柏原企画調整課長","answer":"ただ、それを画一的に何かしようということではなくて、そういった人たちを大きく見ながら、町会の動きといいますか、支援のあり方というのを考えたらどうだろうかというイメージだろうと思います。","id":"exchange-039"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"最後になりますが、先ほどほかの委員からもありましたけれども、条例ということも、私は結構早いペースで進むのかなと思ったのですが、今年もこういう議論もされるということで、なかなか検討していく中でいろいろな新しい課題ではないのですけれども、やはり再確認という意味で、もう一回検証し直さなければいけないのかと、そのような議論の流れに多分なっているのではないかという雰囲気を受けましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-05","title":"品川区シティプロモーション戦略プランの概要","agenda":"品川区シティプロモーション戦略プランの概要","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"これを見ていくと、住んでもらう対象を女性、若者ということで本当にいいのかと。魅力も、これは８つ書いてありますけれども、これも全部打ち出していってしまうと、結局、伝わる人にはちょっと散漫になってしまって、何かを売るというのは、単一イメージを広く持ってもらうというのが基本になると思います。だから、そこら辺がちょっとまだ整理し切れていないように感じるのですけれども、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"イメージのところですが、これをつくるに当たりまして、これまで２年間にわたっていろいろな調査をやってきた結論として、いろいろな地域の魅力があって、それのバランスのよさ、いろいろなものがバランスよく魅力があるところが。","id":"exchange-041"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう少し最初の段階で、誰に何をしていくか、それを何で売るか、一つに絞るということは、ほかを捨てるということで、それは行政の普段の仕事からいえば、最も対極的にあるような部分ではないかと思います。だから、誰に何をしたいかというのをもう少しインパクトのある形で出していただきたいと思うので、そういう議論も当然されたと思うのですが、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"そういう方々を媒介として、品川区の生活しやすさとか、品川区の魅力的なところを発信していただけるような機会をつくっていきたいという思いです。","id":"exchange-042"},{"speaker":"あべ委員","kind":"意見","question":"本当に若い女性をターゲットにするのであれば、品川区としてもっとアート部門に力を入れていかないとと考えています。そこは大変手薄なところなので、本当に若い女性を狙うのであれば、やらなければいけないことはいろいろあるだろうと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"だから、極論を言ってしまえば、家賃が安くて見ばえのいい建物、さらに駅に近いところにあれば、どんどん若者はこちらに移住してくるわけですから、果たして品川区でシティプロモーションはそんなに頑張ってやることは必要なのかというのは疑問だというのを言わせていただきます。それだけです、質問はしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"東京の一極集中を加速させるようなことは止めるべきだと思います。そういう意味では、この議論が始まってもう今年で２年目ですけれども、区の努力でも、去年１年間で何がどう進んだのか正直よくわからないというのは、やはりなかなか進める要因が見当たらないからだと思いますので、大きく見直すべき時に来ているのではないかと思いますけれども、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"ですので、決して一極集中を加速するとかという視点で始めたものではございません。もっと地道に、地に足がついた骨太なものとしてシティプロモーションを捉えて、考えていきたいと思っているところです。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"情報発信とおっしゃいますけれども、足りないのは区民への情報発信ではなく、保育園だったり特養ホームだったり羽田や道路だったり、そういう具体的な問題を既に感じているわけですから、ぜひ、そういう解決こそ私は必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"あくつ副委員長","kind":"質問","question":"一つ目なのですけれども、シティプロモーション戦略プラン、これが多分、完成型だと思うのですが、概要とあるのですけれども、全体を拝見しないと文脈が読めないという部分もあるのですが、これは全体のものをいただくということはできないのでしょうか。","respondent":"中元広報広聴課長","answer":"今の段階ですと、まだ実は固める前の段階というところはあります。特に後段部分のどういうことをやっていくというのは、まだまだ内部調整や検討をしていますので、一定程度、きちんと形になってきた段階でご報告をさせていただけるタイミングになるかと考えています。","id":"exchange-047"},{"speaker":"あくつ副委員長","kind":"質問","question":"そういう点では、一つの形としてできてきたのかと思うのですけれども、このコンセプトのところ、先ほどほかの委員からもありましたけれども、私も一瞬、総花的だとは思ったのですが、確かにこれはコンセプトですから、ここで尖るというのはなかなか難しいところもあるので、その中で一つ、ときめきのある暮らしというところのときめきというところ、ここは非常に大事だと私は思っているのです。","respondent":"中元広報広聴課長","answer":"例えば、一つの例ですけれども、そういう情報発信サイトでありますとか、区の公式ホームページですとなかなかいろいろ制約等もございましてできないことを、そういう民間でシティプロモーションサイトみたいなものの提案が出てくればいいと期待しています。","id":"exchange-048"},{"speaker":"あくつ副委員長","kind":"提案","question":"わかりました。まだ正式には打ち出していないと思いますけれども、どういったことをお考えになっているのか、それももう一つ、教えていただきたいと思います。例えば、たしか車内でというような話か提案があったと記憶しているのですが。","respondent":"中元広報広聴課長","answer":"ただ、まだ細かいところは検討中です。","id":"exchange-049"},{"speaker":"あくつ副委員長","kind":"質問","question":"それで、最後に、今後のキャッチコピーとロゴマークというところなのですけれども、先にロゴマークというもの、個々の具体的な話だと、どうもいまいちイメージが湧かないのですが、ロゴマークを活用することによって、どんなシティプロモーション効果があるのか教えてください。","respondent":"中元広報広聴課長","answer":"区のホームページサイトとかにいろいろなカラーで置いて、それをご自由に使ってみんなで品川区のイメージアップをやっていきましょうみたいな呼びかけをして、皆様と統一感を持ってシティプロモーションに取り組んでいきたいと考えているところです。","id":"exchange-050"},{"speaker":"あくつ副委員長","kind":"質問","question":"ロゴマーク、先行自治体もあるということなのですけれども、例えば議論の中に、またかと言われるかもしれませんが、私はこれを言ったことはないですけれども、ゆるキャラとかもあるわけですよね。いろいろなキャラクターもあると思うのです。そういった議論はなかったのですかね、なぜロゴマークになってしまったのかというところがあって、ここのところはいかがでしょうか。","respondent":"中元広報広聴課長","answer":"まだ何と何、きちんと固めたわけではございませんので、また今後の、まちの方々に入っていただくシティプロモーション連絡会議の中でそういうようなご提案が出てまいりましたら、それは検討する余地はあります。","id":"exchange-051"},{"speaker":"大沢委員","kind":"意見","question":"そこのところをどういうふうに切り分けて、大崎は品川区、目黒は品川区だけれども、品川は品川区ではなくて港区、どうもここも、品川を一歩出た方たちの品川のイメージというのが、近未来的な品川駅周辺のようなイメージが、そのイメージが非常に強過ぎると僕は思うのですが、そのことについてどのように捉えられているか。","respondent":"中元広報広聴課長","answer":"どうしても品川駅近辺のイメージで、都会的なとか、そういうところが高くなってしまったのかというところは否めないところです。その辺も今後シティプロモーションをやる中で、もう少し本当に品川区本来の魅力というものを発信して、実際につなげていけたらと考えています。","id":"exchange-052"},{"speaker":"大沢委員","kind":"質問","question":"品川と品川区というのが違うのだというような、一つの情報発信を先ほどおっしゃっていたので、そこのところはする必要が僕はあるのではないかと。品川駅から醸し出す、昔ながらのではなくて、生活感がなくて、下町らしくない、これは品川駅、品川駅のある周辺から出されるイメージなので、品川区とそちらはちょっと違うのだというのを全面的に出すような一つの仕掛けも大事だと思うのですけれども、伺います。","respondent":"中元広報広聴課長","answer":"そのようにくっきりと、昔ながらの人情のあるお祭りが活発だったりするまちを打ち出すというところも大切だと思うのですが、逆にプロモーション効果の中でそのギャップをあえて強く打ち出していくというのも。","id":"exchange-053"}]},{"id":"topic-06","title":"第一回総合教育会議","agenda":"第一回総合教育会議","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区より反論がありましたが、率直に言ってこの反論がよくわからないので、幾つか伺いたいと思います。なぜ、採択すべき教科書について、協議題として取り上げるべきではないとされているのか、その理由を伺いたい。そして、もう一つ、このＱ＆Ａのどこを読んだら、教科書採択の方針を総合教育会議で協議できるということになるのか、具体的にご説明いただきたいと思います。","respondent":"江部総務課長","answer":"Ｑ＆Ａにつきましても今の点は、明確にだめだというのは、協議題としてはいけないというのは、教科書採択や個別の教職員人事についてという、まさに教育委員会の専権事項についてということでございまして。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、まず、政治的、中立的に要請の高い事項、つまり採択すべき教科書や人事について、なぜ取り上げるべきではないとされているのか、そこをしっかりご説明いただきたいということが一つと、あと後半の大綱について、教育委員会が適切と判断して、首長が記載することも考えられますとあるけれども、教科書採択の方針や人事について、首長が記載することも考えられますが、なぜ。","respondent":"江部総務課長","answer":"あくまでも中立性を保つというのは教科書採択そのものでございまして、基本的な考え方や方針ではないです。それで、首長と教育委員会の連携という中では、協議してもいいということになっているものです。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"協議できるとなっているという、その根拠が何かと説明していただきたいと思うのです。区の主張は、大綱策定における協議なら、首長の権限に関わらない事項である教科書採択の方針や人事の基準について、総合教育会議で協議することができるという解釈なのか、そこを伺いたいと思います。そこをしっかりとご説明いただきたいと思います。","respondent":"江部総務課長","answer":"4)一方、教科書採択の方針、教職員の人事の基準については、予算等の地方公共団体の長の権限に関わらない事項であり、調整の対象にならないものの、協議することは考えられるものであること、ということからＱ＆Ａがつくられてあります。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、大綱中の策定ならばいいのだということなのでしょうか。(3)の教育委員会からの協議事項等で教科書採択の方針が協議されたことが、なぜ議題２の大綱の策定についての議論の過程になるのか、そこがよくわからない。これがおかしいのではないかと思うのですけれども、いかがでしょうか。","respondent":"江部総務課長","answer":"一方、教科書採択の方針、教職員の人事の基準については、予算等の地方公共団体の長の権限に関わらない事項であり、調整の対象にはならないものの、協議することは考えられるものである、です、それが一点。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"とりあえず、これは手元の資料がないので、後でいただきたいということと、最後に一言、やはり区の説明を聞いていると、まず冒頭に、取り上げるべきではありませんとなった理由や歴史的背景があまりにも欠如しているというふうに思います。なので、改めて、採択すべき教科書について、総合教育会議の協議題として取り上げるべきではないとされた理由をしっかりとご説明いただきたいと思います。","respondent":"江部総務課長","answer":"中立性と申しますのは、教育に対する政治介入といった言葉が使われておりますけれども、国の基本的な考え方は、教育の政治的中立性、継続性、安定性は確保しながら、この総合教育会議については首長との連携を強化するという新たな方針を出してつくられたのが総合教育会議です。","id":"exchange-058"},{"speaker":"あべ委員","kind":"確認","question":"もう一回、確認しておきたいのですけれども、教育大綱の持つ性格が品川区の教育に対してどのような意味を持つのか。あるいは、何か制限するといいますか、規定するような部分があるのか、どういった性格のものなのか。そして、区長部局、教育委員会とどのような関係にあるのかということをご説明いただければと思います。","respondent":"江部総務課長","answer":"それで決められた事柄につきましては、首長および教育委員会それぞれの所管する事務において尊重し、執行していくということになりますので、今までの区長部局、教育委員会でやっていたことはベースとしてありつつ、そこのところの連携が図られて、より実効性の高い。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"今のご説明を伺っていると、教育大綱というものは品川区の教育のベースになっていく。そういう感じの捉え方でよろしいのでしょうか。割とフリートーク的な色合いが強かったかと思うのですが、それが今度、次回９月には、これまた区役所のほうで肉づけをされて素案になると。それで大綱としてつくられるものなのですか。どうお考えですか。","respondent":"江部総務課長","answer":"それにつきましては、区長部局は区長に説明をし、教育委員会は教育委員会の中でもむという作業は、もう事前に日々行ってきているということでございまして、総合教育会議は１時間少々ということで、それだけとれば、確かに短い時間ですが、初めて見るわけではございません。","id":"exchange-060"},{"speaker":"あべ委員","kind":"意見","question":"９月上旬には素案が出てくるということなので、それも、そういう形で物事をつくっていくというのが、本当に総合教育会議というものがエクスキューズになってしまわないような運用をぜひ願っているのですけれども、今のお話だと、言葉は悪いですけれども、アリバイづくりみたいな形では今後進んでほしくないなと思います。ご答弁、もし何かあれば。","respondent":"中山企画部長","answer":"最後に行われた懇談会の中では、もうこういう法改正の動きは明確になっていましたから、そういう中でも、今後の大綱についての基本的な考え方、進め方みたいな部分は懇談会の中ではありましたけれども、一定のお話がありました。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問・要望","question":"今後とも自由闊達で深い議論の行われる総合教育会議にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-07","title":"（仮称）上大崎三丁目高齢者福祉施設等擁壁改修工事請負契約","agenda":"（仮称）上大崎三丁目高齢者福祉施設等擁壁改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"簡単に２つ伺いたいのですけれども、今回の擁壁工事ですけれども、これは従来のスケジュールどおりなのか、ちょっと遅れた感はあるのか、そこを伺いたいと思ったのです。","respondent":"立川経理課長、小林施設整備課長","answer":"もともとこの施設につきましては、完成予定が平成２９年の第２四半期ということになっておりまして、今回の擁壁工事が入るですけれども、概ね予定どおりの進捗というふうに伺っています。本体の竣工のご質問にお答えします。平成２９年の３月いっぱいを今現在、目標にしております。","id":"exchange-063"}]},{"id":"topic-08","title":"大崎駅西口交通広場整備工事その２請負契約","agenda":"大崎駅西口交通広場整備工事その２請負契約","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"交通広場は、以前は今年の夏に竣工というような話を聞いていたかと思うのですけれども、このスケジュールの変更についてどうなったのか教えてください。実際、工事を見ていますと、一旦、舗装した部分をまたはがしている。その後、また止まってしまったりとか、見ていると、何となく不思議だという感じなのですけれども、今はどういう感じで工事がなされているのでしょうか。","respondent":"立川経理課長","answer":"こちらのバスターミナルの部分につきましては、今回はその２工事ですけれども、昨年度、この点線の部分の外側のところを実施したです。今回、予定どおり内側の部分を現在実施していくということで、予定、いわゆるスケジュールの変更については聞き及んでいないです。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"夏にできて、もうそのままバスの運行がされるというふうに聞いていたのですけれども、夏に工事が終わって、その後の話が遅れているということですか。","respondent":"立川経理課長","answer":"今回のバスターミナルの整備につきましては、２月の建設委員会で、所管のほうから報告をしたということは聞いておりまして、平成２７年度の今後の予定ですけれども、大きく３つありまして、路線バス事業者による路線認可手続と。","id":"exchange-065"},{"speaker":"あべ委員","kind":"確認","question":"確認ですけれども、ハードの整備自体は計画としては遅れがなくて、ただ、本当はできたらすぐに運用が始まるといいのですけれども、それはハードができたからといってすぐにできず、その予定が年末か、あるいは来年以降に持ち越されているという状況なのでしょうか。","respondent":"立川経理課長","answer":"ただいまのご質問につきましては、所管のほうからお答えすることが正しいと思いますので、ご質問の内容については所管にお伝えしたいと思います。","id":"exchange-066"},{"speaker":"中塚委員","kind":"意見","question":"記憶の範囲で曖昧なので、わからないところがあるのですけれども、ここをバスターミナルにするという話が挙がったときに、区は利用料を取らないかわりに、工事をたしか大崎エリアマネジメントがやるからみたいなやりとりがかつてあったような気がしていて、今回、区が工事をするというのがよくわからなかったのですけれども、バス停にするときに、大崎のまちに資するということで。","respondent":"立川経理課長、秋山財政課長","answer":"所管のほうから伝え聞いているところですけれども、施設の運営につきましては、まず運営手法といたしまして、自動車ターミナル法に基づくバスターミナル事業として運営する、これは国土交通大臣の事業認可が必要となるということと。運営につきましては、今ご説明さしあげたとおりですけれども、この建設工事につきましては、あの周辺の再開発事業者からの受託収入をもって充てるということで、一旦は区が工事をいたしまして。","id":"exchange-067"}]},{"id":"topic-09","title":"豊葉の杜学園屋内運動場落下防止対策その他工事請負契約","agenda":"豊葉の杜学園屋内運動場落下防止対策その他工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"今は豊葉の杜学園で、その後、品川学園ということですけれども、当初予算のときから非構造部材の工事が行われるという話はもちろん承知しているのですが、こうやって学校ごとに出るのか、それともこれは規模が大きいからこういう形なのか、そこだけご説明いただけますか。","respondent":"小林施設整備課長","answer":"委員がおっしゃるとおりです。規模が大きいものですから、こちらのほうについては学校ごと、豊葉の杜学園も１件物件で出しております。","id":"exchange-068"}]},{"id":"topic-10","title":"土地・建物の寄附受領","agenda":"土地・建物の寄附受領","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"大変ありがたいことだと思います。それで、いろいろと難しい条件があるというふうではありますけれども、一方で、ここは当面は公文書保管庫や児童用図書の物流拠点とありますが、また制約を何とかクリアできるような形で、今後もより有効な活用方法というのをぜひ考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"ありがたいということで、ぜひ有効に使っていきたいということなのですけれども、一応、支障がないことから受領したということですが、支障というのは何ですか。まだそこまでないのかわかりませんが、当面はわかったので、本格的にはどういうスケジュール感で考えているのか、スケジュール感を教えていただきたいのが２つ目。多少、違いはあるのかと思うけれども、その物差しをご説明いただきたいと思います。","respondent":"立川経理課長","answer":"２番目の当面の次のスケジュール感ですが、こちらの建物につきましては、ＵＲ（都市再生機構）との区分所有となっておりますので、区だけの意向でその後というか、長期的にどうするかということが、なかなかスケジュールを立てにくいところもありますので。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"わかりました。支障のところだけ、建築年数はどうなのか。要するに、旧耐震なのか、問題はないのか、そこだけご説明をいただきたい。","respondent":"立川経理課長","answer":"こちらは昭和４２年の新築でございまして、耐震基準としては旧耐震です。ただ当時、ＵＲの住宅につきましては、旧耐震基準ではありますが、堅牢に建てているというふうに伺っておりますので、震度５強については何ら問題はないというふうに聞いてあります。","id":"exchange-071"},{"speaker":"須貝委員","kind":"質問","question":"今回こういう寄附をしていただくというのは本当にありがたいことなのですが、三英社製作所は法人ですよね。区が何かと交換というか、交渉をしているというようなことはないと思いますけれども、今後こういうものが出てきてしまうと非常に我々も区民の方も心配に思うので、その辺は大丈夫なのですか。","respondent":"立川経理課長","answer":"行政が寄附をいただくということは、このように透明性を高めまして、また今後の活用についても、当然、効率的、経済的に使っていかなければならないというふうに考えているところです。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問・要望","question":"私よくわからないので、土地と建物を寄附してもらって、土地全体が７６８.６９m2で、建物はＵＲとの区分所有になる。その辺、今後、ＵＲとの権利関係とかを教えていただきたい。","respondent":"立川経理課長","answer":"実際、土地の所有、底地の所有というのは三英社製作所でございまして、それで建物の部分について、先ほどご説明したとおり、区分所有がなされている。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"ということは、これは土地、建物の寄附の申し出というふうになっていますが、土地に関しては借地権をということですか。","respondent":"立川経理課長、田村総務部長","answer":"それで、借地権もそれぞれ、自己借地権、区としての借地権を６８％持っておりまして、ＵＲのほうは借地権を３２％持っている。平たく言いますと、土地の７割は区の財産ということを考えています。ですから、今回はその全ての三英社製作所の持ち物、底地の部分と借地権の部分はそのまま、借地権と区分所有は全部区が引き継ぐということで、それ以外のＵＲの持ち物についてはそのままＵＲが継承するという考え方です。","id":"exchange-074"}]},{"id":"topic-11","title":"地方税の賦課及び徴収に関する事務に係る特定個人情報保護評価","agenda":"地方税の賦課及び徴収に関する事務に係る特定個人情報保護評価","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"主なリスク対策として、ずらっとありますけれども、これだけのリスクはあるということとあわせて、このリスク対策ができるのかということだと思います。あわせて、いろいろ対策をしたとしても情報が漏れた際の被害住民の補償についてはどういうふうに現在考えられているのかも伺いたいと思います。","respondent":"黒田税務課長","answer":"２点目の漏れた際の補償ですが、基本的に現在もシステムを運用しておりますので、そういった意味では、現在以上のリスク対策をやっておりますので、漏れることはないというふうに考えておりまして、その漏れた際の補償について何か規定があるというものではございません。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"漏れることはないとおっしゃいますけれども、やはり漏れている状況が現実にある中で、こういうリスク対策ができるのかと聞いたけれども、やはりできるというような答弁にならないわけですね。漏れることはないとおっしゃいますが、その根拠は何なのか。やはり関心が高い問題だけに、品川区だけの問題ではもちろんないのですけれども、ぜひご説明いただきたいと思います。","respondent":"黒田税務課長","answer":"そういった意味では、高いリスク対策をこれからとりましてシステムを運用してまいりますので、住民の情報がこのシステムから漏れるということがない対策をとっていきたいというふうに考えているものです。","id":"exchange-076"},{"speaker":"中塚委員","kind":"意見","question":"システムは別、正直どう別なのかよくわからないのですけれども、その別のシステムを超える技術で次々と情報が漏れ、イタチごっこのような状況が今は起きているのだと思います。やはりこういう危険な番号法は進めるべきではないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"吉田委員","kind":"質問・要望","question":"漏れることは絶対にないという覚悟でお仕事をしていただきたいと思います。漏れることがないような覚悟で仕事はしていただきたいが、でも万が一はあるということを想定しておいていただかないと、ここに情報を預ける、それぞれの区民、市民はとても不安だと思いますので、その辺はもう一回お考えいただきたいと思います。","respondent":"黒田税務課長","answer":"漏れることはないという考えで業務に臨んでおりますが、国のほうでも先般の年金の情報流出を受けまして、マイナンバーのセキュリティーについて強化していくということで、国の省庁では、今。","id":"exchange-078"}]},{"id":"topic-12","title":"公職選挙法等の一部を改正する法律","agenda":"公職選挙法等の一部を改正する法律","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"法改正の概要はそうなのかと思いますけれども、１８歳に拡大して、本当に歓迎いたします。民主主義の成熟度が試されると思いますので、歓迎したいと思います。ぜひ多くの方が選挙の投票ができるような環境や、また投票を呼びかける選挙管理委員会や明るい選挙推進協会の取組みや、いろいろ連動してくると思いますので、今後の方向を伺いたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"その考えとしまして、やはり今ある啓発の取組みということを、決まったばかりですのであれなのですけれども、今後どのようにしていくのかという部分は、今後、十分に検討しながら進めてまいりたいというふうに考えてあります。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区の選挙管理委員会だけで判断できることでは当然ないのかもしれませんけれども、そういう大学などの教育機関との連携というのも大事なのかと思いますが、そういった検討というのは今後あるのでしょうか、伺いたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"いろいろな部分で、大学というお話も出ました。高校３年生になっても、誕生日が来ればという状況でもあります。そういった部分で、いろいろな意味で検討、研究をしてまいりたいというふうに考えております。","id":"exchange-080"},{"speaker":"あべ委員","kind":"確認","question":"一応、確認なのですけれども、この公職選挙法の改正に伴って、品川区の条例その他、何か規則のようなところでも、もし、いじると言ったらいいのですか、改正するようなものがあるのであれば教えてください。","respondent":"工藤選挙管理委員会事務局長","answer":"ただ、当然のことながら、いわゆる選挙のシステムという部分を持ってありますので、その辺の要件等、いろいろとシステム改修等の事務作業という部分は当然出てくるかというふうに考えております。","id":"exchange-081"}]},{"id":"topic-13","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"あくつ副委員長","kind":"意見","question":"同じ九州ですけれども、大分県の豊後高田市というところで、これも昭和のまちづくりというところで、商店街の振興とかまちづくりというところにもちょっと絡んでくるのですが、調べましたら、総務委員会でかなり視察に行っているところなので、基本コンセプトを置いたところを一つ発信をして、それを広告、ＰＲをした結果、かなり人を呼んでいるというようなこともありますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"確かに遠方に行って、それぞれその市、町の活性化云々はあるのですが、どう見ても、やはり２３区、品川区の抱える問題と地方の抱える問題とは、もう大きく、これだけ乖離している状態ですから、近くで視察をするということもそろそろ選択肢として考える時期に来たのではないかというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"あべ委員","kind":"意見","question":"やっている都市はたくさんあるのですけれども、オープンデータの活用でコード・フォーということで、全国的に自治体のオープンデータを使って、民間でいろいろなサービスを展開するということをやっているまちが大分増えてきていると記憶しております。それで、どこでもいいのですけれども、役所だけではなくて民間の方々の話も含めて、そういった活動について勉強したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332522?Template=document&Id=2020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":75850,"voices":247}}]);
